// PROCESS STUDIO 서비스워커
// 2.077: 자리 적합 — 레이더(자리 요구 파란 점선 vs 현재 초록 채움) + 충족/미달/미평가 개수 + 영역별 막대. 총점·등수는 만들지 않는다(넘긴 항목이 못 미친 항목을 가리지 않게 개수로 센다)
// 2.076: KPI — 코치 성장 리뷰의 목표마다 확인 지표 하나(표준 24항목 × L1 빈도·L2 성공률). 후보는 코치 평가가 낮은 순. 선수가 보는 성장 대화에도 함께 실린다
// 2.075: 면담 기록 — 평가 화면에 '면담' 모드(선수 평가/포지션 요구/면담 3단). 12칸 양식에 칸마다 '무엇을 쓰지 말아야 하는지' 안내, 학부모 말·특이사항·지도 소견·도움 연계는 선수에게 안 보이는 칸으로 표시. 저장은 scout_tool_v1.players[].meetings(코칭스태프 전용)
// 2.074: 역할 요구·갭 — 평가 화면에 '선수 평가 / 포지션 요구' 두 모드. 요구는 scout_tool_v1.positions[].req(같은 1~5 눈금), 갭 = 요구 − 현재를 배지·요약으로
// 2.073: 코치가 IDP 를 열면 '평가'가 첫 화면 · 한눈에↔평가를 2단 세그로 · 선수 목록 칸을 262→206px 로 좁힘
// 2.072: 주간 보드 하루 최대 4세션(새벽·오전·오후·저녁) — 훈련 행을 시간대 묶음으로, ＋ 는 시간대를 먼저 묻는다. 경기일·OFF 에도 세션 추가(성격 유지, 경기도 세션 1개로 계산)
// 2.071: IDP 일정 = 일간부터 · 하루 출석 카드(참여/쉼 → 무엇을) · 느낀 강도 1~10 숫자 버튼(쉼으로 바꾸면 강도도 비움) · 하루 시간표 늘 펼침
// 2.070: 보관함 '목록으로 보기'를 커뮤니티 목록 카드와 같은 디자인으로 — 112x76 썸네일 왼쪽·아래 실선·제목 2줄·호버 회색·선택 연파랑. 보기/편집/⋯ 버튼과 표 머리는 보관함 문법 유지(머리는 카드가 되면서 정렬 의미가 없어져 숨김)
// 2.069: 팀 IDP에 '평가' 모드 — 왼쪽 선수 목록(사이드바) + 오른쪽에서 바로 평가. 저장은 scout.html 의 진짜 save() 가 하고 셸이 중계만 한다(평가 스냅샷·동기화 로직 복제 없음). 선수가 IDP를 안 열었어도 팀 명단만 있으면 평가 가능
// 2.068: 커뮤니티가 왜 안 보이는지 화면이 말해 준다 — 불러오는 중 표시(빈칸 20초 제거) · 원인별 문구(서버 무응답/인터넷 끊김/로그인 만료/권한 없음) + 다시 시도 버튼
// 2.067: 목표 탭 맨 위 '내 무기'(강점) 카드 — FA 4코너·EPPP 는 IDP 를 강점에서 시작한다. 후보는 셀프평가 상위·코치 리뷰 강점·분기 목표 4~5단 도달에서 자동 수집(새 입력 없음), 최대 2개 고정
// 2.000: 경기 준비 명단 — 트레이 안에서 선수 칩을 끌어 같은 그룹 안 순서 변경(끼울 자리 파란 선, 배치된 선수도 순서만 가능, 선수단 순서 데이터와 동일 저장) · 데스크톱도 아이패드처럼 선수 한 줄에 한 명 목록
// 1.999: 경기 준비 라인업 — 아이패드(≥768)도 명단 왼쪽 열(220px, 선수 한 줄에 한 명)·운동장 오른쪽 · '⛶ 회의' → '⛶ 전체 보기': 명단 + 운동장만 전체화면(국면 탭·도구줄 숨김, 오른쪽 위 닫기·Esc) — 경기 중 사용
// 1.998: 학습 페이지 — 최상단을 '선수 학습 | 코치 학습' 큰 모드로 분리(코치만 전환, 선수는 고정 배지), 모드별 부제·레슨 문장·전술 원칙 책 순서, 헤더 순서 제목 · 모드 · 영역 탭
// 1.997: 도크 스탬프에 GK 토큰(1번·GK 포지션, GK 유니폼으로 그려짐 — 필드 선수와 구별) · 유니폼 버튼을 '유니폼 설정' 글자 알약으로(데스크톱 레일·폰 도크) · 장비 색 버튼 라벨 '도구 색상 선택'
// 1.996: 보관함 카드 — 공유 상태와 만든 사람을 같은 줄에
// 1.995: 보관함 카드 알약(보기·편집)·⋯ 오른쪽 끝 정렬(⋯ 의 margin-left:auto 가 왼쪽으로 밀던 것 수리) · 알약 글자 정중앙
// 1.994: 보관함 카드(카드·크게 보기) 동작 줄 — 오른쪽 아래 알약 두 개(보기 파랑 채움 · 편집 연한 파랑) + ⋯, 복사·PDF·이동은 ⋯ 메뉴로(1.968 텍스트 버튼 왼쪽 정렬 규칙 위에 덮음)
// 1.993: IDP 루틴 — 요일 화면이 05:00~24:00 시간 줄이 미리 있는 하루 시간표(적은 항목·개인 훈련은 그 시간 줄에, 빈 시간 줄에 바로 적으면 그 시간으로 저장, 시간 못 읽는 항목은 '시간 미정')
// 1.992: 보관함 만들기 중 '전체화면'에서도 하단 도구 도크 유지(데스크톱 커맨드 도크·폰 도크, 스테이지 아래 여백 인라인) · 게임모델 기본 국면에서 세트피스·경합 제외(자동 보강 중단, 비어 있는 자동 추가분은 한 번 정리, 프리셋 가져오기·＋국면으론 계속 가능) · 팀 공통 언어 '우리 팀 언어' 탭을 글로벌 표준 탭과 같은 레이아웃(갈래 필터·검색 도구줄 + 카드 목록: 우리 말·외침·뜻·갈래·편집)
// 1.991: 경기 요약 띠의 장소 미정·구분 미정·담당 없음 칩 제거(사용자) — 값은 '경기 정보 · 선수 상태' 접이에서 편집
// 1.990: 경기 준비 라인업 카드 — 데스크톱(≥1100) 우리 팀 명단을 운동장 왼쪽 272px 열로(포지션 그룹 세로, 칩 줄바꿈, 스크롤), 국면 탭·운동장·도구줄은 오른쪽. 아이패드·폰은 위에 그대로
// 1.989: 팀 유니폼 팝오버에 필드 | GK 세그 — GK 도 주색·보조색·테두리·무늬 따로(gkColors·gkColor2·gkPattern·gkStrokeC, 스냅샷·복원·초기화 포함, 벤치 GK 칩도 같은 옷) · 보드 설정 '현재 배치 저장' 아래 '선수 불러오기' A팀·B팀·C팀·전체 선수(applySquadToBoard 재사용, 없는 조는 비활성)
// 1.988: 셀프평가 척도 말 변경(사용자) — 빈도 대신 성장 단계: 1 시작 · 2 배우는 중 · 3 할 수 있음 · 4 안정적 · 5 강점(eval-standard.js 사전 한 곳, IDP·평가표 설정에 반영) · 데스크톱·아이패드(≥641)는 문장 왼쪽·5칸 오른쪽 한 줄, 폰은 아래
// 1.987: 사이드바 '보드 설정' 항상 표시(데스크톱 레일, 다른 앱에서 누르면 보드로 가서 팝오버 열림) · 팀원 보기 팝업은 역할 읽기 전용(드롭다운·역할 저장 제거, 변경은 팀 설정 › 권한)
// 1.986: 사이드바 '훈련 디자인' → 보관함 '무엇을 만들까요?' 선택창(훈련·작전판·세트피스·미팅·경기 분석) · 보관함 카드 보기·편집 버튼 파란색(보기 채움·편집 연한 파랑)·카드 보기에서 오른쪽 아래 · 팀 공간 빈 보관함에 진단 줄(내 권한·공유 폴더·마지막 동기화·잠김 여부) + '이 기기에만' 안내 문구를 폴더 공유 모델로 수정
// 1.985: IDP 셀프평가 — 점수를 누르면 위 요약 카드(평균·레이더·영역 막대)가 즉시 갱신(카드만 다시 그림, 펼침·스크롤 유지)
// 1.984: IDP 폰 — 프로필·이미지노트 탭이 자기 탭을 켠다(전엔 '일정'을 켜고 '‹ 일정' 뒤로가기 머리를 붙였음 — 사용자 "지워죠"). 뒤로가기 제거. 선수용 하단 5탭처럼 그 탭이 숨겨진 경우만 예전처럼 일정 점등
// 1.983: IDP 요약 카드 — 평가 카드 클래스가 기존 .ev-sum(평가 진행 요약 줄, flex row)과 겹쳐 버튼이 왼쪽으로 가고 배치가 틀어지던 것 수리(evsum-card 로 분리) · '수정하기' 두 카드 모두 오른쪽 아래 고정 · 레이더·영역 막대 카드 중앙 정렬(모든 폭)
// 1.982: IDP 요약 카드 위계 통일 — 제목 16/800 → 핵심 숫자(평균 22/800 액센트) → 보조 메타 → 본문 → 오른쪽 아래 버튼 · 레이더 폰 가운데 230px·축 글자 13px, 데스크톱 200px, 영역 막대 행 24px
// 1.981: 부팅 두 번 뜨던 것(사용자 "새로고침하니까 이상하게 계속 뜨다가 돼") — sync.js 가 부팅 직후 서버 변경을 받으면 통째로 새로고침하던 것을 스플래시가 아직 떠 있을 때만으로(화면이 보인 뒤엔 storage 이벤트 갱신) · 팀 › 평가표 설정: 기본표를 라벨 칩 대신 표준 v1 행동 문장 행(라벨 태그·문장·en) + 선수/코치 톤 토글, 문구 20항목·척도 표기
// 1.980: IDP 프로필·셀프평가 요약 카드 뼈대 통일(머리 제목·메타 → 본문 → 오른쪽 아래 '수정하기 ›' 알약 버튼, 펼치면 '접기') · 펼친 프로필 폼 라벨 92px 열 + 입력 열(데스크톱 2열=4칸 정렬, 폰 1열, textarea 전폭)
// 1.979: 부팅 깜빡임 수리(사용자) — 셸 스플래시를 보드 iframe load+110ms 가 아니라 boardReady(마지막 작업 복원 완료)까지 유지(최대 1.5초, 안전 가드 2.5초) · 페이지 스트립을 boardReady 전에 그려 걷힌 뒤 피치가 밀리지 않게
// 1.978: 팀 홈 상단 카드 — 오른쪽 위 22px 색 버튼(팀 색 점, 누르면 엠블럼·색 팝오버가 오른쪽에) · 날짜 옆 '올해 D-n'
// 1.977: IDP — 홈 '이번 주' 요일 칸 두 층(위 팀 일정 경기/훈련/OFF 팀 색 · 아래 나: 기록 또는 개인 훈련 n/n, 요약 타일 팀/나 구분) · 내 프로필 탭: 프로필·셀프평가 카드 접힘 요약 기본(프로필 = 사진·이름·포지션·주발·나이·팀·키/몸무게 칩, 평가 = 평균·완료 n/20·미니 레이더·영역 막대) 누르면 세부 입력, 온보딩에서 오면 펼침, 편집 중 요약 실시간 갱신
// 1.976: IDP 역할 탭 → 목표 탭 '팀에서 내 역할' 카드로 통합(시즌→역할→이번 달 캐스케이드, 국면 접힘 목록, 목표 만들기에 역할 국면 선택지, 홈 '역할 ›' 스크롤; 1.963 bindRole 부재로 저장 안 되던 입력 바인딩 신설) · 개인 노트 → 보관함 세그(자료·분석·게임모델·개인 노트, 사이드바 항목 제거, 노트 머리 세그) · 폰 보관함 카드 축소(썸네일 2:1·메타 한 줄·보기/편집/⋯) · 경기 리뷰 폰 1열(1.880 2열 강제 수리)·데스크톱 카드 높이 맞춤 · 폰 팀 › 일정은 월간 먼저 · 주간 시트 요일 스냅 스크롤 · 주제 배분에 '경기' · 폰 액션바 줄바꿈 · 선수단 헤더 포메이션 셀렉트 제거 · 후보 카드 폰 위계(이름 17/800·소속·번호·나이·주발) · 스카우팅 포인트 안내문 제거·접이식 카드·폰 머리 줄바꿈(페이지 폭 478→375)
// 1.975: IDP 폰 — 상단 메뉴 전부 보이게(역할·내 프로필·이미지노트 포함, 코치 쪽 5탭 화이트리스트 해제, 알약 행 가로 스크롤) · 홈 '오늘 기록하기' 버튼과 미니 카드 사이 4→12px
// 1.974: PROCESS 평가 표준 v1(studio/eval-standard.js) — FIFA 홀리스틱 프로필 5차원·풋볼 랭귀지 개인 행동·FA 4코너를 뼈대로 20항목(전술4·기술5·체력4·심리3·태도4), 항목=행동 문장(선수 1인칭/코치 관찰 두 톤), 척도에 말(거의 안 함~거의 항상), 세트피스는 팀 기준으로. 팀 기본표 44(b_*)·IDP 개인 15(fifa_*) → 한 벌: scout 로드 시 fifa 모드 팀 자동 이관(옛 점수는 두고 대응표 평균으로 새 값 초기화, 포지션 기준도), IDP 는 옛 미러도 표준으로 읽고 옛 기록(process-fifa-v1)은 FIFA15_SET 으로 계속 읽음. 코치 평가 그리드에 관찰 문장, IDP 셀프평가는 문장+말 붙은 5칸. selfEval.levels 누락 저장본 탭 죽던 것 수리
// 1.973: 학습 › 전술 원칙 완성 — ① 홈 '최근' 카드에 학습 줄(원리 이해·적용·퀴즈·코치 과제) ② 랜덤 퀴즈 10문제 모드(결과·틀린 원리로 이동, 최근 20회 기록) ③ IFAB 경기규칙 코스 17조(재서술) ④ 코치용 트랙 배지(게임 플랜·축구 분석하기, 선수 관점에선 뒤로) ⑤ 코치 과제 배정(선수 IDP에서 책/원리 → cs_idp_pub_v1_<uid>.learnTasks, 선수는 완료 표시 → 코치에게 보임)
// 1.972: 작전판 — 훈련 편집기 닫을 때 라이브 보드가 흰 훈련 격자로 바뀌던 재발 수리(사용자 '업데이트 되니까 또'): 새로고침 뒤 남은 초안 장면(pitchTheme:'train')을 _activateTraining 이 먼저 올린 다음에야 되돌릴 피치를 기억해 'train'을 기억하던 순서 → 초안 복원 전에 editorStash 피치로 기억(train 이면 기본 피치)
// 1.971: 학습 › '전술 원칙' 탭 — 6권(포지셔널 플레이·데 제르비·버티컬 4-2-3-1·수비의 기술·게임 플랜·축구 분석하기)의 원리 78개를 우리말로 재서술(learn-principles.js). 원리 = 무엇·왜·큐·관찰 → 퀴즈 → 이해함 · 게임모델에 넣기 · 이 국면 훈련 만들기 · 적용 기록. 원문·도식은 싣지 않고 책·출판사만 표기
// 1.970: 선수단·스카우팅 폰 — 조 칩·보드 세그·정렬 세그 알약화(팀 운영 .tn-seg 문법) · 그룹 머리(골키퍼 1) 숨기고 포지션 머리 하나(13/800·2px 잉크선) · × 삭제 회색 고스트 · 그룹 간 40px 여백 22 제거 · 후보 목록 그룹 머리 동일 문법 / 훈련 편집기 폰 — 전체화면 폭(팝업 max-width 예외) · 항목 순서 DOM(인원→제목→분×세트→국면→강도→메모) · 인원 카드 2열 컴팩트 · 메모 머리 숨김 · 보관함 저장 오른쪽 고정
// 1.969: 분석 — 헤더 정리(제목·검색 폭 380·오른쪽 동작 묶음: 저장 팀·커뮤니티에 올리기(헤더로 이동)·＋ 새 경기) · 운동장 카드 아래 페이지 탭(장면=페이지, ＋ 페이지) · 보관함 목록 머리를 커뮤니티 bar 문법으로(검색 왼쪽·필터 오른쪽·아래 작은 '내 자료 · N개') · 사이드바 라벨 10.5px · '훈련 만들기'→'훈련 디자인'
// 1.968: 보관함 카드 — 컨테이너 가로 100%(커뮤니티처럼)·카드 최소 250(≥1500 은 270)·카드 바닥에 보기·편집·복사·PDF·⋯(목록 행은 PDF 숨김 유지)·썸네일 없는 항목은 장면에서 즉석 생성(최대 30장/렌더) · 사이드바 '훈련'→'훈련 만들기' · 새 훈련 열 때 훈련 인원을 선수단 상태(GK·필드·재활·부상)로 자동 채움
