// 1.966: 보관함 — 기본 보기를 카드로(한 번 강제 후 선택 기억) · 카드를 커뮤니티 카드 문법으로(썸네일 위 종류 칩·☆ 호버·제목 굵게·메타·보관 상태·태그 칩·바닥 편집·⋯, 빈 썸네일은 피치 실루엣)
// 1.965: 커뮤니티 — 기본 보기를 카드로(사용자) · 검색창 폭 340·높이 36 으로 축소, 필터는 오른쪽 끝
// 1.964: IDP 역할 — 더 쉽게(사용자): 국면마다 질문 한 줄 + 답 한 칸 + '얼마나 하고 있어?' 1~5·모르겠어, 근거·'하나만 바꾼다면'은 맨 아래 한 카드로, 문장은 선수 눈높이
// 1.963: IDP '역할' 탭(사용자) — 팀에서 내가 해야 할 역할을 메타인지 구조로: 한 줄 정체성·왜 → 게임모델 국면마다 ① 생각 ② 점검(1~5·모르겠다) ③ 근거(장면) ④ 다음(하나 바꾸기) + 이번 주 집중 + 팀 원칙 참고, 홈 목표 카드에 '내 역할' 행, 코치는 읽기 전용
// 1.962: 주간 PDF 재디자인(시트 문법 — 머리·요일 열 합계 분·칩 10px·경기/OFF 병합·미팅/웜업/보관함은 있을 때만·메모 필기줄·주제 배분+합계) · 보드: 훈련 편집기 열린 동안 라이브 보드 저장 중단(업데이트 후 피치가 흰 훈련 격자로 바뀌던 병) · 보드 왼쪽 위 안내 알약 제거
