// 1.960: 주간 시트 강도(RPE) 칩 왼쪽 정렬 — 점·숫자가 일정·주제 칩과 같은 x, 숫자 크기는 칩 글자와 맞춤(사용자: 일관성)
// 1.959: 주간 일정 = 시트(표 한 장) — 라벨 열 고정 + 월~일 7열, 같은 항목은 같은 행(요일 카드 7장은 코드에 남김) · 사이드바 '업데이트' 버튼을 하단 타일 규격(아이콘 위·라벨 아래, 연파랑)으로 + 계정 margin-top:auto 중복 수리
// 1.958: 보강 추천(4안) — 팀 일정 주간 카드에 국면 평가 낮은 국면 3개(점수·이번 주 횟수) → 요일 고르면 낮은 세부 국면이 미리 골라진 훈련 만들기 · 팀 홈 국면 평가 카드에 낮은 국면 2개+'보강 훈련 만들기' 다리 · 작전판에서 그린 일정 훈련도 gmPhases·초점 지님(국면 배분에 잡힘)
// 1.957: 게임모델 화면 재설계 — 정체성은 큰 제목, 국면 6장은 2열 카드(접힌 채로 세부 국면 칩·원칙/장면 수·최근 평가), 스타일 칩은 새 모델일 때만·초기화는 물러남
// 1.956: 팀의 공통 언어 — 우리 팀 언어 전부 한눈에(더보기 없음) · 칩을 누르면 폼에서 편집·삭제 · 글로벌 표준 탭 "표준 전체 가져오기"(우리 말이 없는 표준을 넣고 칩에서 우리 식 이름으로 바꾸기)
// 1.955: 선수 편집(평가표) 모달 글자 12/13/12 통일 · 선수단 명단 평가 열 글자 세로 쪼개짐 방지(nowrap·열 폭 262)
// 1.954: 주간 요일 카드 — 일정·강도·주제를 한 행에 하나씩(작은 라벨 + 전폭 칩)
// 1.953: 주제 ← 국면 자동 제안(훈련 칩의 게임모델 국면 다수 계열 → 그날 주제, 직접 고른 주제는 유지) · 배분 카드 문구 통일(주제=하루의 목적 / 국면=훈련의 내용)
// 1.952: 팀 일정 주간 = 요일 카드 실구현(머리 → 일정|강도|주제 한 줄 → 미팅·웜업은 있을 때만 → 훈련 → 보관함 → ＋미팅·＋웜업), 경기일·OFF도 같은 카드 · 월간·연간 배분 카드에 국면 배분 추가
// 1.951: 팀 일정 재디자인(A안) — 주간 보드를 요일 카드(열 좌우 헤어라인·머리 라운드·행 간격 0·빈 칸 ＋는 호버 때만·칩 무테 연회색), 경기일 열도 같은 카드, 강도 행 띠 제거 · 월간·년간·일간 라운드/헤어라인 통일
// 1.950: 훈련 편집 중 다른 화면으로 가면 자동 저장하던 것 → "저장하고 나가기 / 저장 안 하고 나가기 / 계속 편집" 묻기 · 만들기 팝업의 "팀 선수로 작전판" 항목 제거
// 1.949: 훈련 편집기가 켜는 "훈련" 피치 때문에 보드 피치가 바뀌던 것 — 열 때 보드 피치(테마·커스텀색·라인·그리드)를 기억하고 닫을 때 되돌림
