// 1.937: 유니폼 줄무늬 굵게(토큰·칩·견본 모두 4줄, 사선도 굵게) · 훈련 세션 3단계 "저장하기"=바로 저장 후 보관함, "나가기"=저장 없이(초안도 지움) 보관함
