// 1.934: 훈련 편집 인원 카드 2열 컴팩트(GK|필드 · 재활|부상 · 선수단) · 국면 선택을 보드 설정 문법으로(라벨 열 + 회색 컨테이너 + 흰 버튼, 활성 연파랑) · 장비 줄 "색상"→"색상 선택" 버튼을 줄 끝으로
// 1.933: 팀 홈 인원+세션 카드 2열 · 팀 일정 주간 카드에 "이번 주 국면 배분"(훈련 칩 gmPhases → 국면 단위) · 훈련 편집 초점 셀렉트 숨기고 국면 칩 "훈련 성격" 그룹으로 흡수(다중 선택 가능 표기) · 표준 국면 "세컨드 볼"→"경합"(기존 저장본 자동 정리) · 보관함 바 "양식" 버튼 제거
// 1.932: 훈련 세션 만들기 3단계 왼쪽 버튼 "세션 설정"→"나가기"(보관함으로), 세션 설정은 상단 인원 표시를 눌러 열기 · 팀 홈: 오늘 훈련 인원+오늘 팀 훈련 한 카드, 국면 평가는 자기 카드
// 1.931: 팀 홈 국면 평가 — 게임모델 국면이 없으면 "표준 국면으로 바로 시작"(6국면 심기) · 훈련 편집기에 게임모델 국면 다중 선택 칩(gmPhases, 첫 선택 시 초점 자동)
