// 1.852: 선수단 선수 편집 카드 — 스카우팅 프로필 패널과 같은 문법(사진 정사각·라벨 왼쪽 한 열·포지션/구분 칩)
// 1.851: 선수 추가·경기 추가 최소 입력 시트(psForm), 선수단 빈 상태 안내 카드
// 1.850: 팝오버 겹침 정리 — 앱 설정·계정·작전판 설정 중 하나만, 팝업 안 버튼은 팝업 닫고 모달, 계정 삭제는 로그아웃 아래 작은 링크
// 1.849: IDP 일정 요약 카드 3장·일정 탭 상단 목표 스트립 제거(사용자)
// 1.848: 팀 일정 요약 카드 3장 제거(사용자)
// 1.847: prompt() 4곳 → psPrompt(되돌리기·계정 삭제·전환 백업 복구·팀 선택), 짝 confirm 도 psConfirm
// 1.846: 작전판 선택 카드 — 토큰·장비 컨트롤을 카드 한 장으로, 다중 선택 바 같은 재질
// 1.845: 로그인 후 보기전용 잔류 수리 — 세션·권한표 변화 감지 시 탭 재부팅
// 1.844: 작전판 유니폼 → 벤치 칩·팀 팔레트 알약 동기화(무늬·보조색·테두리)
// 1.843: 팀 홈 오늘 세션 빈 상태 — 문구 '세션이 아직 없어요' + 점선 카드 스타일.
// 1.842: 팀 홈 — 넓은 화면에서도 한 열(2열 해제).
// 1.841: 작전판 설정 — 탭 제거·배치·관리를 보기 아래로 합침(한 패널·한 스크롤), 선수단·명단 버튼 숨김 · IDP›일정 요약 카드 3장(이번 주·이번 달·올해: 팀훈련·경기·개인운동·휴식·부상·재활 일수, 내 기록 doc.log 기준, 클릭 = 그 뷰로).
// 1.840: 팀›일정 요약 카드 3장(이번 주·이번 달·올해: 경기·훈련·휴식 일수 + 선수단 부상·재활 인원, 카드 클릭 = 그 뷰로) · 작전판 설정 두 탭 같은 크기(폭 340·배치 탭 컴팩트·내부 스크롤).
// 1.839: IDP 탭 일정 맨 앞 · IDP 일정 차트 카드 왼쪽 정렬·2열 · 팀 홈 2열(오늘 세션 | 오늘 훈련 인원) · 보관함 밀도 패스(필터 줄 40·행 44·액션 hover·레일 라벨 규격). CSS만.
// 1.838: 사이드바 하단 위계(구분선·풋볼A 칩·앱 설정 내비행) + '작전판 설정'을 작전판 헤더 오른쪽 끝으로 · 개인 노트 — 새 양식 '훈련 6면'(왼쪽 2/3 축구장 모눈 6면 3×2 + 오른쪽 1/3 메모장) · 도구줄 왼쪽 정렬 정돈(8px 간격).
// 1.837: 개인 노트 — 노트 선택 팝오버를 버튼 왼쪽 끝 기준으로 펼쳐 사이드바에 잘리지 않게.
// 1.836: IDP — 첫 화면을 일정으로, 홈 탭 숨김(폰 되돌아가기도 '‹ 일정') · 코치 선수단 IDP 목록 1열 · 탭 세그 내용 폭 · 개인 노트 모드 세그 헤더 줄로+도구줄 왼쪽 정렬 · 팀 홈 오늘 세션 카드를 주간 스트립 아래로.
// 1.835: IDP — '코치와 공유' 버튼을 '공유하기'로, 탭과 같은 헤더 줄 오른쪽 끝에 고정(전 데스크톱 폭).
// 1.834: 개인 노트 — 배경 양식 버튼 라벨 '노트 선택'으로, 모드 세그 옆으로 이동(CSS order).
// 1.833: 사이드바 그룹 라벨(개인/팀/성장/공유) 제거 — 묶음 순서·간격만 유지.
// 1.832: 작전판 설정 › 배치·관리 탭을 '보기' 탭과 같은 행 문법으로(라벨 왼쪽·컨트롤 오른쪽 36px 행, 34px 버튼/셀렉트, 작은 구획 라벨, 구분선 간격 축소). CSS만.
// 1.831: 감사 1-2·1-3·2-1 — ① 작전판 도크 이중 마운트 차단(app.html run(): command-dock-v5·폭≥768이면 모바일 도크 주입 안 함 + board.html 보험 CSS)
//   ② 게스트 개방: 로그인 흔적(ps_cache_owner_v1)·활성 워크스페이스가 없는 기기는 비로그인도 개인 공간을 로컬로 사용(perms.js guestOpen→admin, sync.js dataUnlocked) — 잔재 있는 기기는 종전대로 잠금
//   ③ 사이드바 그룹 헤더·재배열(개인/팀/성장/공유, CSS order).
// 1.830: 사이드바 하단(계정·앱 설정·작전판 설정·설치) — 아이콘 제거, 글자만 한 줄(두 줄로 꺾이던 '작전판 설정').
// 1.829: 개인 노트 — 페이지 레일 숨김 + 페이지 스와이프(종이 밖 가로 스와이프·펜 전용 시 손가락 스와이프·트랙패드 가로 휠) · 도구줄 글자 12px·줄바꿈 금지(세로로 꺾이던 '노/트' 수리)·세그 겹침 수리.
// 1.828: 팀›선수단 명단 데스크톱 — 열을 왼쪽에 붙이고(남는 폭은 맨 끝) 평가 5영역·주발 열을 폭과 무관하게 상시, 머리글 열과 정렬 고정 · 팀 운영 헤더 부제가 세그에 가려 잘리던 것 수리.
// 1.827: **헤더 규격 통일(데스크톱, CSS)** — 8화면 헤더를 한 띠 56px·제목 18/부제 12 같은 줄·알약 세그·액션 오른쪽으로(팀 운영 2단→1단, IDP 제목 복원+탭 알약, 학습 히어로→띠, 스카우팅 남색 띠→연회색).
//   + 팀›선수단 명단을 팀›스카우팅 후보 명단과 같은 시각 문법으로(상태 틴트 알약·조 배지·2px 그룹 밑줄·평가 상자). design-v2 LAYOUT-1824 블록.
// 1.826: 팀›스카우팅 폰 — 스카우팅/우리팀/전체 세그를 누르면 접힌 운동장 보드를 펼치고 스크롤(세그는 보드 표시 필터라 접힌 채로는 아무 변화가 없었다).
// 1.825: **레이아웃 정리 2** — 팀›선수단을 팀›스카우팅과 같은 레이아웃으로(데스크톱 도구 한 줄·폰 액션 한 줄+도구 2행+명단 카드) ·
//   IDP 홈 데스크톱 2단 균형(시간표 4행 스팬+긴 카드는 왼쪽 열로) · IDP 내 프로필 '연령 그룹' 셀렉트 숨김. 전부 CSS(design-v2 LAYOUT-1824 블록).
// 1.824: **레이아웃 정리 패스(CSS만, 기능 불변)** — 다크 테마 사이드바 붕괴 수리(app.html fmdark .appbar position:relative 제거) ·
//   코치 선수단 IDP 2단 그리드 오적용 수리(figma-premium :not(.idp-squad)) · 일간 뷰 행 순서를 주간과 통일+읽기 폭 860 ·
//   경기 준비 운동장 폭 상한 840 · 폰 커뮤니티 필터 인라인 · 폰 학습 이중 헤더 접기 · 다크 앱설정 제목색. design-v2.css LAYOUT-1824 블록.
// 1.823: **폰 후보 카드에서 아바타 제거** — 사진은 프로필에서. 카드는 이름부터 시작해 더 컴팩트.
// 1.822: **팀>스카우팅 폰 — 후보 카드 2행 + 도구 줄 2행**
//   카드: 1행 아바타·이름(크게)·소속팀·등번호·평가·상태 / 2행 메모. 프로필은 이름 탭. 도구 줄: 1행 포메이션+보기 세그 / 2행 ＋자리·회의 모드.
// 1.821: **스카우트 후보 명단 가로 여백 제거** — #scList 980px 상한을 없애 넓은 화면에서 명단이 카드 폭 전체를 쓴다(남는 폭은 메모 열).
// 1.820: **IDP 데스크톱 2단 + 팀 홈 정리 + 폰 후보 카드 통일**
//   IDP 홈 데스크톱: 좌 시간표(넓게) / 우 목표·오늘 기록·경기 카드. 팀 헤더 '동기화됨'·'팀 설정' 제거, 팀 홈 지표 4카드 제거, 1행 일정 스트립 → 2행 훈련 인원 → 3행 세션.
//   팀>스카우팅 폰 후보 카드를 사이드바 스카우팅 카드 문법으로(아바타·이름·소속·등급 배지·액션 줄). 붙이기 시 소속·등급을 자기 필드로(S→A).
// 1.819: **IDP 홈 = 오늘 시간표 (폰 우선)**
//   GROWTH SCORE 히어로·성장 여정을 걷어내고, 요일 스트립 + 세로 시간축을 첫 화면으로. 팀 일정·요일 루틴·개인 훈련·기록을 한 축에(기존 데이터 그대로),
//   식사·수면·학교·훈련·경기·미팅을 텍스트로 자동 분류해 색점. ＋ 추가(내용·시간) → 그날 기록 + 요일 기본 갱신, 항목 탭으로 수정·삭제, 개인 훈련 완료 체크, 좌우 스와이프로 날짜 이동.
// 1.818: **작전판 헤더·선택 패널 컴팩트**
//   페이지 스트립 64→40px(제목 13.5px·탭 26px·글자 11px). 아이패드 선택 패널은 2열 + 버튼 28px·11px로 압축(455→256px).
// 1.817: **작전판 선택 컨트롤 아이패드에서 잘림 수정**
//   토큰 선택 패널이 세로 1열로 20여 개 쌓여 아이패드 화면 아래로 잘려 선택이 안 되던 것 — 521~1100px 구간에서 2열 그리드 + 화면 높이 안 스크롤(셸 도크·단독 모두).
// 1.816: **팀>스카우팅 폰 후보 목록을 카드로**
//   폰에서 표 그리드가 깨지던 스카우트 후보 목록을 사이드바 스카우팅 카드 문법으로: 이름·상태·평가 / 소속·등번호·프로필 / 메모. 머리글·5영역 평가는 폰에서 숨김(프로필에서). 데스크톱 표는 그대로.
// 1.815: **팀>스카우팅 폰 화면 — ＋ 버튼 빠른 등록 + 운동장 보드 접기**
//   폰: 우하단 ＋ → 시트에서 이름·소속팀만 입력해 후보 DB에 즉시 등록('등록하고 다음'은 소속팀 유지). 운동장 보드는 접힘(헤더로 펼침). 데스크톱은 변화 없음.
// 1.814: **작전판 상단 '내보내기' 버튼 제거** — PNG·GIF·MP4 내보내기는 하단 도크에 그대로.
// 1.813: **팀>IDP 선수단 1열 + 스카우트 후보 카드 정리**
//   선수단 IDP 카드 목록을 1열로(다열이라 포지션 섹션이 좌우로 갈라져 보임). 스카우트 후보 카드의 '사이드바 스카우팅 열기' 버튼 제거.
// 1.812: **회의모드 카드 깨짐 수정**
//   슬롯 150px에 글자만 키워 고정열이 폭을 다 먹고 이름이 '전…'으로 잘리며 카드가 커져 겹치던 것 — 슬롯 240px + 회의 글자 크기에 맞춘 열 폭(소속 78·번호 26·이름 ≥56).
// 1.811: **팀>스카우팅 탭 2개(후보 DB · 스카우팅 포인트) + 후보 검색으로 찾기·붙이기**
//   '후보'→'후보 DB'로 개명, 임베드 탭 제거. 스카우트 후보 카드에 검색창: 붙인 후보를 이름·소속·포지션으로 거르고, 아직 안 붙은 후보 DB 선수도 함께 찾아 '자리에 붙이기'. 명단 열 폭을 내용물에 붙여 가로 여백 제거.
// 1.810: **스카우트 후보 ↔ 후보 DB 통합 — 후보의 원장은 후보 DB 하나**
//   팀>스카우팅 '후보' 탭의 스카우트 후보 카드는 포메이션 자리에 붙인 후보만 표시(＋ 후보 추가 → 후보 DB로). 다리 카드 제거.
//   후보 DB 탭 카드에 '자리에 붙이기' → 자리 선택 시트 → 스카우트 대상 생성/이동(dbId 참조, 기존 대상 데이터 보존). 붙은 후보는 카드에 '보드 · GK'로 표시.
// 1.809: **팀>스카우팅 '스카우팅 포인트' 탭 = 포지션별 포인트 질문지**
//   포지션×속성 매트릭스 대신 포인트 세트 편집기(그룹·적용 포지션·질문, 프로세스 기본세트)를 탭 안에 그대로 연다(scouting.html?view=points). 사이드바 스카우팅과 같은 데이터. 매트릭스는 게임모델>포지션·기준에 그대로.
// 1.808: **게임모델 PPT 하나로 통합 — 선수 설득·구단 면접 어디서든**
//   '선수용' 라벨 제거 → 'PPT 만들기'. 표지에 GAME MODEL·코치 이름·날짜, 코칭 철학 세 문장을 한 장씩 앞에, 4국면 개요 한 장, 원칙 슬라이드 하단에 트리거·왜·성공 기준(사고 체계), 마무리는 철학 문장.
// 1.807: **게임모델 → 선수용 PPT(.pptx) 만들기**
//   선수가 이해하는 순서로 조립: 표지(팀 색·엠블럼) → 왜(세 문장) → 국면 간지+단계별 원칙과 첨부 작전판 그림(4국면 먼저, 세트피스·경합은 부록) → 너의 역할(포지션별 요구) → 우리의 말(공용어) → 마무리. 한 장에 문장 하나·그림 하나.
// 1.806: **설정 3종 일관화 — 정본은 작전판 설정 문법**
//   앱 설정: 세그(언어·화면·테마)를 회색 트랙+선택 파랑 알약으로, 버튼은 흰 보더 규격, 섹션 타이틀·radius 통일(다크 포함).
//   계정 팝업: 회색 통버튼 11줄 → 흰 보더 버튼 + '팀 관리' 섹션 2열 그리드(길이 절반), 계정 삭제는 빨간 위험 톤.
// 1.805: **팀>스카우팅에 '후보 DB' 탭 + 탭 이름 정리**
//   후보 DB 탭 = 사이드바 스카우팅과 같은 화면·같은 데이터를 팀 안에서 그대로(임베드, 첫 진입 시 로드). '포지션별 기준' 탭은 '스카우팅 포인트'로 개명(기능 동일).
// 1.804: **스카우팅 포인트 평가지 + 팀 보드 다리**
//   [포인트 설정] 포지션 그룹별 체크 질문 세트(한 줄=질문·##=섹션, 텍스트 붙여넣기 편집) + '프로세스 기본세트'(FW·WF·CMF·DMF·SB·CB·GK 7그룹) 내장.
//   [포인트 평가] 프로필에서 전체 화면 평가지 — 선수 포지션 그룹 자동 선택, 질문마다 1~5, 평균·문항수 요약.
//   [다리] 팀>스카우팅 하단 '후보 DB' 카드 — 사이드바 스카우팅 후보를 비교 보드의 스카우트 대상으로 한 방향 복사(중복 방지, 두 화면 데이터는 계속 별개).
// 1.803: **스카우팅 필터 레일 폭을 내용물에 맞춤**
//   고정 148px → max-content(약 83px, '필터 초기화' 기준). 긴 커스텀 태그는 140px에서 말줄임. 본문 카드 영역이 그만큼 넓어짐.
// 1.802: **프로필에 계약기간 + 커스텀 프로필 항목**
//   계약기간 행 추가, '＋ 프로필 항목'으로 팀이 원하는 필드(병역·연봉·SNS 등)를 직접 추가·삭제(전체 적용, 값은 선수별 저장).
// 1.801: **회의모드 안에서 바로 필터링**
//   보드 상단에 구분·평가 칩 필터와 초기화 — 회의 중 조건을 바꾸면 운동장 슬롯이 즉시 갱신되고, 메인 목록과 같은 필터 상태를 공유한다.
// 1.800: **스카우팅 회의모드 — 운동장 포지션 보드**
//   회의모드 버튼 → 전체 화면 운동장 카드에 후보를 포지션 슬롯별로 배치(등급·평점 순, 인원수 표시). 빈 포지션은 흐리게 드러나 영입 공백이 보인다. 현재 검색·필터 반영, 이름 클릭 시 프로필로.
// 1.799: **스카우팅 프로필 확장 — 에이전트·영상 링크·커스텀 5영역 평가**
//   연락처가 비어도 에이전트 행 기본 노출, 영상 링크(유튜브 등, 새 탭)와
//   항목별 1~5 평가(기본 전술·기술·체력·심리·사회성, 팀이 항목 추가·삭제) + 카드에 평균 배지.
// 1.798: **스카우팅 팀 아이덴티티 밴드 + 레일 정렬 마감**
//   헤더 아래 밴드에서 엠블럼(클릭 업로드·128px 축소)·팀 이름·팀 색상을 직접 설정(밝은 색은 글자 자동 대비). 태그 추가·필터 초기화는 왼쪽 정렬 리스트 행으로 통일하고 레일을 더 조임.
// 1.797: **스카우팅 좌측 필터 컴팩트화**
//   레일 148px·행 2px 패딩·섹션 간격 축소 — 포지션·구분·평가 필터가 스크롤 없이 한눈에.
// 1.796: **스카우팅 폰 연속 기록 — 이름·소속팀·포지션 3요소**
//   폰은 ＋버튼 → 기록 시트: 큰 입력·포지션 칩·'등록하고 다음'으로 연속 입력(소속팀은 유지 — 같은 팀 선수 연달아). 데스크톱 바에는 소속팀·포지션 칩 복원.
// 1.795: **스카우팅 빠른 기록 = 이름 하나**
//   포지션·소속 입력을 빠른 기록 바에서 걷어내 이름+Enter만으로 등록(등록 즉시 프로필이 열려 이어서 채움). 소속 자동완성은 프로필의 현·전소속으로 이동.
// 1.794: **스카우팅 좌측 필터를 1열 리스트로**
//   포지션·구분·평가 필터를 세로 한 줄 리스트(활성 = accent-soft 내비 문법)로 바꾸고, 폰 가로 레일은 알약 유지.
// 1.793: **사이드바 '스카우팅' 신설 — 후보 선수 DB (v1)**
//   빠른 기록(이름+Enter)·프로필·평가(등급 S~D·한줄평·관찰 기록)·번개 검색(이름/소속·출신/포지션)·필터(포지션/구분 태그/평가).
//   구분 태그는 팀이 편집(범용 — 특정 구단 전제 없음), JSON·CSV 가져오기(FC안양 형식 어댑터 포함)·JSON 내보내기, 기기 로컬 저장(cs_scoutdb_v1).
// 1.792: **토큰 드래그 배치 후 연속 모드 유지 + 장면 '계속 강조'(지속 하이라이트) 추가**
//   도크 토큰을 드래그해 놓아도 연속 배치가 켜진 채 유지돼 이어서 탭·드래그로 계속 놓을 수 있다.
//   깜박임 옆에 계속 강조 버튼: 선택 토큰에 흰 할로+노란 링+밝기(화면)로 항상 환하게 — 재생·GIF·MP4·PNG 내보내기에도 그려진다(장면별 hl:[id]).
// 1.791: **작전판 설정 배치·관리 탭을 보기 탭 문법으로 통일**
//   라벨을 우리 팀·상대 팀으로, 배치 고정을 [고정|해제] 2버튼 세그로(원본 토글은 숨긴 상태 소스), 대형 없음 안내는 캡션 위계로 정리.
// 1.790: **데스크톱에서 운동장 개수 선택이 무반응이던 문제 수정**
//   레일(≥768) 부트가 run()을 건너뛰어 멀티피치 렌더러(__applyPitchN)가 보드 문서에 주입되지 않던 것을 레일 분기에서도 주입한다.
// 1.789: **작전판 설정 보기 탭에 운동장 개수·회전 복원**
//   구 셸 설정에만 있다가 1.787 통합에서 빠진 운동장 개수(1~6)와 90° 회전을 피치 행 아래에 되살린다. 멀티피치 렌더가 없는 단독 작전판에서는 개수 행을 숨긴다.
// 1.788: **사이드바 하단 그룹(계정·앱 설정·작전판 설정) 좌측 한 축 정렬**
//   구 상단바의 .gear 8px 마진을 제거하고 아이콘 18px 슬롯을 공유해 아이콘 중심과 라벨 시작점을 계정 칩과 맞춘다.
// 1.787: **앱 설정과 작전판 설정을 범위별 두 진입점으로 통합**
//   환경 설정은 앱 전체 설정으로 명확히 묶고, 보기·더보기는 원본 기능을 보존한 작전판 설정 탭으로 합친다.
// 1.786: **작전판 하단 도크를 한 줄로 정리하고 색상·시간 조작을 명확하게 개선**
//   팀·역할·장비를 한 행에 유지하고, 장비 색상은 현재색 스와치로 강조하며 재생 시간 선택 폭은 글자에 맞게 줄인다.
// 1.785: **iPad 작전판 경기장을 작은 안전 여백만 남기고 최대 확대**
//   하단 통합 도크의 중복 높이 예약을 제거해 축구 라인·토큰·그림을 같은 비율로 카드에 최대 맞춤한다.
// 1.784: **애니메이션 내보내기 형식을 GIF · MP4 · PNG 타이포 아이콘으로 통일**
//   모호한 그림 아이콘 대신 동일한 크기·서체·상태 규칙의 파일 형식 배지를 사용하고, MP4 미지원 브라우저의 WebM 대체 저장을 안내한다.
// 1.783: **작전판 축구 라인·토큰·그림을 운동장 카드 중앙에 정렬**
// 1.782: **프리미엄 작전판 도크 정렬·반응형·접근성 완성**
//   빈 레일이 차지하던 폭을 제거해 모든 행을 왼쪽 정렬하고, 장면·배치·장비·12개 편집 도구를 기능 손실 없이 직접 노출한다.
//   좁은 화면은 장비 전용 행으로 재배치하고 터치 크기·선택 상태·ARIA·운동장 간격을 일관되게 보정한다.
// 1.780: **보관함 저장 도크 고정 + 반응형 내보내기 버튼**
// 1.778: **Studio Light Grid 작전판 도크 + 연속 토큰 배치**
//   하단 도구를 설명 라벨 없는 40·36·36px 3행으로 정렬하고 장면·12개 그리기·장비 기능을 모두 직접 노출한다.
//   자동 번호와 C/N/T/S 토큰은 클릭 후 빈 운동장에 반복 배치할 수 있으며 기존 드래그·Undo·장면·자동저장 기능을 보존한다.
// 1.777: **작전판 자동저장 배지 제거**
//   작전판 오른쪽 위의 장식용 '자동 저장됨' 오버레이만 제거하고 실제 자동저장·복구 로직은 그대로 유지한다.
// 1.776: **Photoshop형 컴팩트 작전판 도크**
//   장면·선수·편집/장비를 38·32·32px의 정렬된 3행으로 압축하고 모든 동작 버튼·아이콘·토큰 규격을 통일했다.
//   필름·선수·장비만 독립 스크롤되며 기존 드래그·재생·저장 기능과 모바일 도크는 그대로 보존한다.
// 1.775: **개인 노트 문서 보관함 + 훈련 PDF 바로 가져오기**
//   개인 노트의 노트·메모 옆에 문서 보관함을 만들고 검색·원본 구분·페이지 미리보기를 한 흐름으로 묶었다.
//   보관함 훈련을 기존 PDF 엔진으로 개인 사본화해 바로 필기할 수 있으며, 데스크톱 사이드바도 절반 폭으로 정돈했다.
// 1.774: **장면 빠른 작업 상시 노출**
//   장면 갱신·깜박임·GIF·이미지 저장을 같은 크기의 아이콘으로 장면 행에 꺼내고, 현재 장면 수를 '장면' 라벨 옆에 배치했다.
//   상단의 중복 '＋ 장면'은 제거하되, 기존 자료의 다중 장면 전환 탭은 보존한다.
// 1.773: **전체 선수 전원 배치 + 선수단 버튼 정렬**
//   전체 선수는 재활·부상·불참 상태까지 모두 작전판에 올리고, 훈련 가능 인원 집계는 기존 의미를 유지한다.
//   A/B/C/전체를 같은 한 줄 4열·동일 글자/높이로 맞추며 전체를 항상 C팀 바로 옆에 둔다.
// 1.772: **훈련 인원 자동 집계 + 볼 소유 국면**
//   인원 숫자 열을 카드 오른쪽 끝에 정렬하고 A/B/C·전체 선수 선택을 공용 자동 집계·저장 경로로 통합한다.
//   선수단 비동기 로딩 후 버튼을 다시 동기화하며 훈련 국면에 볼 소유를 추가한다.
// 1.771: **작전판 장비·도구 행 정돈**
//   선수·팀·장비 토큰 크기를 통일하고 장비 원본 칩을 축소한 편집 도구 행으로 이동한다.
//   장비만 독립 가로 스크롤되며 드래그·업로드 기능과 모바일 팔레트는 그대로 유지한다.
// 1.770: **게임모델 보관함 헤더 + 중복 루트 칩 제거**
//   게임모델을 보관함에서 열면 자료·분석·게임모델 공통 헤더를 유지하고, 팀에서 열 때는 기존 팀 문맥을 보존한다.
//   자료 목록의 중복 보관함 루트 칩을 없애고 폴더 경로는 첫 항목부터 자연스럽게 표시한다.
// 1.769: **개인 노트 독립 메뉴 + 분석 헤더 연속성**
//   개인 노트를 보관함 탭에서 빼 사이드바의 개인 도구로 복귀하고, 필기·메모 상태는 같은 프레임에서 보존한다.
//   보관함의 자료·분석·게임모델 흐름은 유지하며 분석 화면에 고정 공통 헤더를 더해 전환 문맥을 잃지 않는다.
// 1.768: **훈련 편집 인원 6행 + 메모 탭 제거**
//   훈련 인원·GK·필드·재활·부상/불참·선수단을 정렬된 6행으로 만들고 A/B/C·전체 선수 버튼을 고정한다.
//   훈련 방법·코칭 포인트·학습 리뷰 탭은 없애되 기존 메모는 한 흐름에서 모두 편집·저장할 수 있게 유지한다.
// 1.767: **작전판 토큰 상시행 + 라이트 6메뉴 셸**
//   장면 필름을 축소해 4~5장을 보이고, 선수·장비 원본 토큰을 편집 도구 위에 상시 노출한다.
//   사이드바는 흰색·축소 로고로 복귀하며 분석·게임모델은 보관함 내부 메뉴로 이동한다.
// 1.766: **작전판 통합 Command Dock — 피그마 2단 구조·컨트롤 규격·팝오버 정합**
// 1.765: **Premium UX Concept 적용**
//   Figma의 Command Board · Team Today · Personal IDP · Vault Workspace를 기존 데이터·권한·편집 흐름에 연결한다.
//   데스크톱 216px 네이비 셸, 작전판 2행 도크, 팀 실데이터 지표, IDP 성장 여정, 보관함 3패널을 추가한다.
// 1.764: **공통 디자인 시스템 정본 + 모든 메뉴 표면 패스**
//   색·형태·모션·다크 의미 토큰을 한 벌로 통합하고 기존 dv2/premium 변수는 호환 alias로 유지한다.
//   전 메뉴의 일반 카드는 16px border-only, 실제 팝업·모달만 공용 float 그림자를 쓰며 배치는 바꾸지 않는다.
// 1.763: **애니메이션 장면 필름 가독성 + 4팀 유니폼 편집**
//   장면 썸네일을 크게 하고 키보드 선택·모바일 스크롤/길게 눌러 정렬을 지원한다.
//   선수 팔레트는 4팀으로 통일하고 팀별 주색·보조색·테두리와 5가지 유니폼 패턴을 제공한다.
// 1.662: **일정 주제를 주간·월간·연간 국면 배분에 연결**
//   드릴에 상세 국면이 없을 때만 그날 주제를 기본 국면으로 사용하고, 기존 상세 국면은 유지한다.
//   주간·월간 공용 집계에 연간 카드도 연결해 같은 일정이 기간별로 같은 비율을 보여 준다.
// 1.661: **IDP 경기 읽기 학습을 앱 최상위 메뉴로 이동**
//   IDP와 학습이 같은 프레임·같은 doc.learning 기록을 공유하고, 왕복할 때 홈/학습 위치를
//   명확히 복원한다. 선수 휴대폰과 팀원 읽기 화면에는 필요한 내부 진입점을 유지한다.
// 1.660: **IDP 휴대폰 화면을 Apple HIG 원칙으로 재설계**
//   핵심 5개 화면에 집중한 내비게이션, 큰 화면 제목, 카드 안의 오늘 기록 버튼과
//   안전영역 바텀 시트·44px 조작·VoiceOver 초점 관리를 적용한다. 저장 구조는 그대로 둔다.
// 1.659: **일정 확정 뒤 연결 경기를 자동으로 순서 저장**
//   편집 중이거나 일정이 서버에 아직 확정되지 않은 회차에는 연결 경기를 함께 보류하고,
//   일정 확인 뒤 새 회차에서 자동 전송해 정상 입력 중 나타나던 경기 연결 경고를 없앤다.
// 1.658: **iPad 5MB 빠른 저장에서 일정 중복본 자동 이전**
//   일정 3-way 병합 기준본을 검증된 IndexedDB로 옮기고 같은 문자열을 되읽은 뒤에만
//   localStorage 사본을 지워, 일정 원문 두 벌이 빠른 저장 공간을 채우지 않게 한다.
// 1.657: **새 기기에서도 이미 정한 팀 이름 복원**
//   로그인한 본인의 ps_members.name을 먼저 기기에 복원한 뒤 정말 이름이 없을 때만
//   입력창을 열어, iPad·새 브라우저·계정 전환 뒤 같은 이름을 반복해서 묻지 않는다.
// 1.656: **일정에 등록한 내용을 오늘에서 빠짐없이 보기**
//   오늘 화면의 14일 띠를 이번 주 월요일부터 열어 이미 지난 이번 주 훈련도 보존하고,
//   주제 없는 '훈련' 일정과 가장 가까운 경기 뒤의 추가 경기까지 각 날짜·상대로 표시한다.
// 1.655: **끝난 보관함 정리를 동기화 대기로 다시 세지 않기**
//   서버 반영으로 앱이 만든 정확한 revision만 완료 확인에 사용해, 충돌 캐시 정리 뒤
//   남던 '동기화할 변경 1건'을 없애고 그 뒤의 실제 사용자 편집은 계속 대기함에 지킨다.
// 1.654: **숨은 비공개 자료를 blind upsert하지 않기**
//   서버 목록에 없는 보관함 ID는 충돌 무시 INSERT로만 확인하고, 0행이면 타인의
//   비공개 원본을 그대로 둔 채 이 기기의 옛 공개 캐시만 정리한다.
// 1.653: **표시가 없는 옛 타인 공유본까지 전환 복구**
//   _teamSource가 없던 구버전 사본도 작성자(createdBy)가 다른 사람이면 내 자료로
//   다시 올리지 않아, 실제 풋볼A의 비공개 전환 항목까지 안전하게 정리한다.
// 1.652: **남의 비공개 보관함 항목이 워크스페이스 전환을 막지 않기**
//   공개일 때 받아 둔 타인 자료가 비공개로 바뀌면 로컬 사본을 다시 내 자료로
//   올리지 않고 조용히 정리해, 원본은 지키면서 내 작업 ↔ 팀 전환을 끝낸다.
// 1.651: **큰 일정도 저장한 뒤 워크스페이스 전환**
//   8주치 훈련을 담은 일정 한 키에만 안전 한도를 넓히고, 일정 급감 확인 중에는
//   연결 경기 업로드를 미뤄 일정 선택이 끝난 다음 서버 계보 순서대로 확정한다.
// 1.650: **워크스페이스 전환 실패 원인을 숨기지 않기**
//   강제 동기화 오류 코드와 실제로 남은 자료 이름을 전환 상태에 표시하고,
//   브라우저 진단에는 내용 없이 stage/code만 문자열로 남겨 실기기 원인을 구별한다.
// 1.649: **실제 대기함에서 워크스페이스 전환 보류 찾기**
//   급감 보호는 용량 초과 목록이 아니라 동기화 대기함에 남으므로, 현재 공간을 실제로
//   막는 키를 읽어 모두 보류 자료일 때 선택창으로 연결한다. 다른 실패는 계속 안전 중단한다.
// 1.648: **보류된 변경 때문에 숨겨지던 워크스페이스 전환 복구**
//   전환을 막은 급감 자료를 그 자리에서 정확한 원문으로 확인하고, 모두 클라우드 확인이
//   끝난 뒤 처음부터 안전하게 풋볼A 전환을 다시 실행한다. 개인 공간 문구도 클라우드로 바로잡는다.
// 1.647: **경기 서버 거부로 멈춘 워크스페이스 전환 복구**
//   서버 일정과 어긋난 경기 원문이 거부되면 최신 서버본을 새 회차에서 다시 받고,
//   이 기기 원문을 되돌리기에 확인한 뒤에만 적용해 내 작업 ↔ 팀 전환을 끝낸다.
// 1.646: **내 작업 ↔ 팀 워크스페이스 전환 복구**
//   일시적인 IndexedDB 검증 실패를 최신 원문으로 재확인하고, 개인 자료 대기를
//   팀 대기함과 분리해 실제 팀 자료가 안전할 때는 워크스페이스를 정상 전환한다.
// 1.645: **로그아웃 자료 잠금**
//   로그아웃한 기기에서는 보관함·팀 자료·백업/가져오기를 전부 잠그고,
//   같은 계정과 워크스페이스가 확인된 뒤에만 기기 캐시를 다시 연다.
// 1.644: **팀 메뉴별 파일 + 오래된 iPad 재발 방지**
//   일정·경기·선수·스카우팅·IDP·게임모델을 각각 자동 파일명으로 저장하고,
//   다른 기기에서 같은 메뉴로만 가져온다. 서버는 일정 계보와 경기 연결 필드를
//   다시 검증해, 구버전 기기가 정상 날짜·상대를 다시 덮지 못하게 한다.
// 1.643: **동기화 화면 한 줄로 단순화**
//   헤더의 대기 숫자와 설정의 올리기·받기·자료 확인 중복을 없애고 '지금 동기화' 하나로 합친다.
//   실제 급감 보류만 같은 버튼에서 확인하며, 검증된 8/8 복구와 서버 확인이 끝난 보류는 자동 정리한다.
// 1.642: **편집 중 일정 되감기·날짜 점프 차단**
//   일정 편집을 다른 탭·기기의 전량 동기화가 덮지 못하게 하고, IDB/로컬 거울 쓰기를
//   직렬화·CAS 검증한다. 보고 있는 주차는 기기 전용으로 분리하고 서버 확정 rev의 정확히 다음 판본만 받는다.
//   process.html을 필수 셸에 넣어 app/sync/process가 서로 다른 버전으로 섞이지 않게 한다.
// 1.641: **검증된 백업 파일로 8/8 일정 정밀 복구**
//   추정 이동을 중단하고 8/7 마지막 동기화 정본의 SHA-256·팀·경기 연결을 모두 확인한 뒤 적용한다.
//   일정은 정본으로 복원하고, 경기 준비·리뷰와 수동 경기는 유지한 채 연결 날짜·상대·시간만 교정한다.
//   일반 백업에도 IndexedDB의 일정·연결 경기를 포함해 이후 복구 파일에서 빠지지 않게 했다.
// 1.640: **8/8 일정 전체 역연산 복구**
//   1.637의 전체 -4 이동과 1.639의 -1→0 복사를 지문·상대·요일로 모두 검증한 뒤,
//   가짜 0을 버리고 전체 숫자 주차를 +4 이동한다. 일정·연결 경기·백업·저장 검증을 한 묶음으로 처리한다.
// 1.636: **관리자 — 누가 가입했고 누가 뭘 만들었나** (사용자 지시: "그게 제일 중요해")
//   ■ 못 답하던 이유는 데이터가 없어서가 아니라 **안 읽어서**였다.
//     ps_audit 이 90일치 «누가·어느 팀·무슨 키·만듦/고침/지움·언제» 를 이미 쌓고 있는데
//     관리자 RPC 22개 중 이걸 읽는 게 **하나도 없었다.**
//   ■ 새로 넣은 것 (설치: supabase-설치/supabase-admin-who.sql)
//     ① 운영 홈에 «최근 활동» — "3분 전 · 김코치 · 풋볼A · 훈련 세션 을 만들었습니다"
//     ② 사용자 목록에 **이름 · 소속 팀** — 카카오 가입자는 이메일이 없어 목록의 1/3이
//        "(이메일 없음)" 으로만 보이고 검색조차 안 됐다(실측). 이름·팀·UID 로도 검색된다.
//     ③ «만든 수» — 예전 lib_count 는 «내가 속한 팀의 자료 수» 라 한 팀 30명에게 전부
//        같은 숫자(30)가 붙어 "누가 만들었나" 와 **정반대로** 읽혔다. 이제 본인이 만든 것만 센다.
//   ■ 고친 거짓말 둘 (콘텐츠 탭, 실측으로 발견)
//     · 소유자가 전부 팀 주인이었다 — ps_admin_library 가 owner_email 을 w.owner_id 에서
//       뽑고 있었다. ps_library.owner_id(진짜 작성자)가 있는데 안 썼다.
//       화면(admin.html)은 이미 l.owner_email 을 먼저 읽게 돼 있었다 — RPC 만 안 주고 있었다.
//     · 558개가 **전부 같은 시각**(2026.08.07 11:51)이었다 — updated_at 은 DB 행이 마지막으로
//       닿은 시각(=동기화 시각)이다. 코치가 실제 저장한 saved_at 으로 바꿨다.
//   ■ 잡은 함정 하나 — 새 함수를 loadActivity/renderActivity 로 지었더니 **'활동 분석' 탭의
//     같은 이름 함수와 충돌**해(뒤 선언이 이김) 코드가 통째로 죽어 있었다. admin.html 은 단일
//     스코프다 — 새 함수는 반드시 고유 이름으로(loadWhoLog/renderWhoLog).
//   ■ 안 한 것 — ps_audit 은 **내용을 저장하지 않는다**(security-v2 의 의도적 설계).
//     그래서 "무슨 자료를" 까지만 말하고 "어떤 훈련을" 은 말하지 않는다. 화면 문구도 거기 맞췄다.
//     항목 단위 이사(sq:<선수id>)가 끝나면 "김코치가 3번 선수를 고쳤다" 까지 나온다.
//
// 1.635: **팀 탭 일곱 개를 한 결로** — 폭·제목·카드 규격 통일 (목업 승인)
//   ■ 데스크톱이 제일 컸다. 1440px 창 실측 —
//     선수·오늘 1440(여백 0, 창 가장자리에 닿음) · 일정 1408 · 스카우팅 1400 · 경기 1240 · IDP 860.
//     **선수에서 IDP 로 옮기면 콘텐츠가 580px 줄며 화면 가운데로 모였다** — 탭만 눌렀는데
//     레이아웃이 통째로 움직였다. 이제 일곱 탭 전부 **1360 · 여백 40**(사용자 확정 값).
//     premium-ui.css 의 --ps-w 한 곳만 고치면 전부 함께 움직인다.
//   ■ 함정 두 개를 지났다 —
//     ① IDP 의 860 은 idp.html 이 아니라 **공용 premium-ui.css** 의 .ps-page-idp .wrap 에 있었다.
//        파일 쪽만 고치면 특이도에서 밀려 계속 860 이다.
//     ② 게임모델은 .stage > * 에 margin-inline:auto 를 줘도 자식들이 자기 여백(.idcard 22px)을
//        갖고 있어 왼쪽으로 붙었다. 폭은 **컨테이너**에 줘야 한다.
//   ■ 제목 줄 — 규칙은 이미 있었고 IDP·scout 만 예외로 빠져 있었다. 그 예외를 없앴다.
//     다만 예외를 만든 이유(제목만 감추면 '개인 성장 계획' 같은 부제가 임자 없이 남아 위계가
//     뒤집힌다)는 옳았다. 그래서 되살리는 대신 **제목과 부제를 같이 감춘다** — 탭 내비가 이미
//     화면 이름을 말한다. 셸 밖(단독 실행·인쇄)에서는 둘 다 그대로 보인다.
//   ■ 카드 규격을 정본(scout.html .card = 모서리 16 · 여백 14 · 아래 12 · 그림자)에 맞췄다.
//     IDP .hm-card 는 16/13·15/10/없음, 게임모델 .phase 는 12/11·12/9/없음 이었다 —
//     한 화면 안에서는 안 보이지만 탭을 옮기면 카드가 들썩여 '결이 다르다'로 읽힌다.
//   ■ **안 한 것: IDP 보라 → 파랑.** 목업에서 제안했지만 코드를 보고 접었다.
//     idp.html 에 «색 = 의미» 규칙이 적혀 있다 — 보라=나의 목표/IDP, 파랑=코치.
//     파랑으로 바꾸면 '내 목표'와 '코치'가 같은 색이 된다. 게다가 --accent 는 94곳에서
//     크롬과 의미를 구분 없이 쓰고 있어(--c-goal 은 0회 사용) 통째로 바뀐다. 사용자와 다시 볼 것.
//   ■ 다음(1.636) — 머리 줄 통일. 지금 탭 본문 맨 위 컨트롤 수가 2개(경기·게임모델)부터
//     15개(오늘 — 14일 날짜 스트립)까지다. «세그 + 주요 동작 1개 + ⋯» 한 모양으로.
//
// 1.634: **팀 자료는 임원만 편집 · 코칭스태프는 보기 전용** (사용자 확정)
//   쓰려는 모양: 임원이 전부 입력한다 → 코칭스태프는 본다 → 다른 게 보이면 **말이나 메신저로**
//   임원에게 말한다 → 임원이 고친다. **수정 요청을 앱 안에서 주고받지 않는다**(제안·댓글·승인 없음).
//   ■ 크기가 작았던 이유 — perms.js 의 gate() 가 이미 완성된 읽기 전용 장치였다:
//     배너 + 편집 컨트롤 CSS 숨김 + **localStorage·IndexedDB 쓰기 차단** + 조작 직후 토스트.
//     여섯 화면(작전판·게임모델·일정·팀·공용어·보관함)이 이미 그걸 부르고 있어서,
//     myScopes() 가 빈 목록을 주게 하는 것만으로 전부 잠긴다. 새 화면 작업이 없었다.
//   ■ 기본값을 닫힌 쪽으로 — staffEdit='edit' 일 때만 코칭스태프가 편집한다.
//     일정(process_coach_v1)이 1.500 에서 같은 길을 갔고 그게 옳았다.
//   ■ **개별 지정(members[uid].scopes)은 이 잠금보다 앞선다.** 임원이 "이 코치에게는 선수단만"
//     하고 직접 체크한 것이라, 팀 전체 스위치가 그걸 덮으면 열어 준 사람이 왜 안 되는지 못 찾는다.
//     잠금은 '기본값'이지 '천장'이 아니다.
//   ■ 같은 표를 보는 곳을 줄였다 — 서버 쪽 쓰기 판정이 두 갈래였다: ps_can_write_key(RLS) 와
//     ps_kv_team_guard 의 마지막 else(트리거). 후자는 scopes 를 아예 안 봐서, 임원이 특정 코치에게
//     열어 줘도 트리거가 막을 수 있었다. 이제 else 가 ps_can_write_key 를 부른다.
//     설치: supabase-설치/supabase-staff-readonly.sql
//     ⚠ 서버 잠금은 ps_guard_mode.enforce=true 여야 실제로 걸린다(false 면 기록만 한다).
//   ■ 이미 쓰던 팀은 어제까지 고치던 스태프가 오늘 못 고치게 된다 — 조용히 바꾸면 그 팀은
//     "저장이 안 된다"만 겪는다(1.514·1.619 에서 겪은 그대로). 그래서 **아직 정하지 않은 팀의
//     소유자에게만** 한 번 알린다. 코칭스태프에게는 안 알린다 — gate 배너가 이미 이유를 말한다.
//   ■ 고친 거짓말 하나 — 전체 잠금인데도 "상태 변경 제안은 할 수 있습니다" 배너가 떴다.
//     그 제안도 팀 자료 쓰기라 막힌다. 지키지 못할 약속이라 전체 잠금일 때는 띄우지 않는다.
//   ■ 코칭스태프가 "지금 보는 게 최신"이라고 믿어야 이 모델이 굴러간다(아니면 이미 고쳐진 걸
//     두고 임원에게 연락하게 된다). 그래서 '마지막 수정 ○○ · n분 전'을 경기 화면에도 넣었다.
//     일정 ✓(1.482) · 선수 ✓(1.633) · 경기 ✓(1.634) · 게임모델·보관함은 아직.
//
// 1.633: **"이 자료는 이렇게 공유됩니다 · 마지막 수정 ○○ 코치 · 4분 전"** — 팀 공유 1단계.
//   ■ 왜 — 팀 자료는 3분마다 조용히 오가는데 화면에는 아무 말이 없다. 자기가 쓴 게 팀에 갔는지도,
//     남이 뭘 바꿨는지도 모른다. 그래서 사용자가 "탭마다 저장 버튼"을 요구하게 된다 —
//     **버튼이 없어서가 아니라 상태가 없어서** 생기는 요구다(2026-08-07 논의).
//     사고 추적도 같은 이유로 막혔다: 2026-08-05 스카우팅 34명→1명은 "어느 기기가 올렸나"를
//     끝내 못 찾았다. 서버엔 마지막 값만 남고 누가 썼는지는 안 남았기 때문이다.
//   ■ 앱 안에 이미 답이 둘 있었는데 각각 한 화면에만 있었다 —
//     일정의 '마지막 수정 ○○ · n분 전'(1.482) · IDP 의 공유 안내 문구(share-line).
//     새로 발명하지 않고 그 둘을 sync.js 로 올려 어디서나 같은 말을 하게 했다.
//   ■ 서버가 적는다 — ps_kv.updated_by 를 **트리거가 auth.uid() 로** 찍는다(클라이언트가 못 속인다).
//     쓰기 가드가 거부해 값을 되돌린 쓰기는 **찍지 않는다** — 안 그러면 거부당한 사람이
//     마지막 수정자로 보여 정반대의 거짓말을 한다. 시각은 새로 안 만든다(cupd 가 이미 그 값).
//     설치: supabase-설치/supabase-updated-by.sql
//   ■ SQL 을 안 깔아도 앱은 그대로 돈다 — 컬럼이 없으면 조회가 400 인데, 그걸 못 잡으면
//     '이름이 안 보인다'가 아니라 **팀 백업이 통째로 멈춘다.** 한 번 실패하면 끄고 예전 질의로
//     되돌아간다(보관함 private 컬럼과 같은 방법). 그때는 공유 안내 줄만 나온다.
//   ■ 문장은 손으로 쓰지 않는다 — 실제 판정에 쓰는 목록(PLAYER_BLIND·PERSONAL·isItemKey)에서
//     만든다. 권한을 잘못 말하면 "내 자료가 샌다"는 오해를 낳으므로 **모르면 아무 말도 안 한다**
//     (sync.js 가 빈 문자열을 주면 화면은 그 줄을 아예 안 그린다).
//     곁다리로 선수 차단 목록이 두 곳에 따로 적힐 뻔한 것을 PLAYER_BLIND 하나로 합쳤다.
//   ■ 이번 판은 **선수 화면 한 곳**에만 붙였다. 경기·게임모델·보관함은 같은 함수(psShareLine)로
//     한 줄씩 붙이면 된다 — 한 화면에서 실사용을 보고 넓힌다.
//
// 1.632: **스카우팅 보드 — 같은 포지션 자리가 둘일 때 선수가 양쪽에 다 떴다** (사용자 제보:
//   "442에서 포워드가 2명이 생성되서 한개에만 올려도 카드 2개에 다 올라가")
//   ■ 원인 — 4-4-2 는 CF 자리가 둘인데(TM_FORMS "442": ["CF",38,13],["CF",62,13])
//     선수는 posId(포지션) 하나로만 자리에 붙는다. 그래서 왼쪽에 넣어도 오른쪽 카드에 같이 떴고,
//     개수 배지도 양쪽에 1, 뎁스 비교(cmpOurs/cmpTgt)는 같은 선수를 두 번 셌다. 352·343 도 같다.
//   ■ 고친 방법 — 선수에 **'같은 포지션 중 몇 번째 자리인가'(sbSeat)** 를 적는다.
//     ⚠ 자리 번호(슬롯 index)는 쓰지 않았다. 포메이션을 바꾸면 같은 번호가 전혀 다른 자리가 되고,
//       그런 깨지기 쉬운 참조가 2026-08-07 에 후보 34명을 통째로 자리에서 떨어뜨렸다(1.625).
//       sbSeat 은 포메이션이 바뀌어도 뜻이 살아 있고, 자리 수가 줄면 마지막 자리로 접힌다.
//     예전 선수는 sbSeat 이 없다 → 전부 첫 자리에 모인다. **아무도 사라지지 않는다.**
//     자리가 하나뿐인 포지션(대부분)은 판정을 아예 타지 않아 예전과 글자 하나까지 같다.
//   ■ 곁다리 — 보드에서 '＋ 선수'로 넣은 선수에게 posName 이 안 붙고 있었다(드롭 경로에만 있었다).
//     포지션 목록이 새로 만들어지면 되살릴 단서가 없는 상태였다 — 1.625 와 같은 함정이라 함께 채웠다.
//   ■ 항목 이사(1.630~1.631)는 2단계 관찰 중이며 이 판에서 손대지 않았다.
//
// 1.631: **항목 단위 저장 — 1단계(쓰기 이중화).** 선수 한 명이 키 하나(sq:<선수id>)가 된다.
//   **읽기는 아직 통짜다 — 화면 동작은 하나도 안 바뀐다.** 계획: 문서/항목저장-이사계획.md
//   ■ 왜 이 순서인가 — 통짜라서 A 코치가 3번 선수를, B 코치가 7번 선수를 고치면 나중 사람이
//     이기고 앞사람 것이 사라진다. 항목이면 둘 다 산다. 44→32 도 76명(중복 29)도 여기서 왔다.
//   ■ 서버가 준비됐는지 **앱이 스스로 확인한다**(fail-closed)
//     supabase-item-keys.sql 을 안 깔면 sq:* 가 권한 표 밖으로 떨어져 선수 전원이 남의 평가를
//     읽는다. "SQL 을 먼저 실행하세요"라고 적어 두는 걸로는 다음 번을 못 막는다(1.590 교훈).
//     그래서 올리기 전에 ps_key_scope('sq:…')='team' 인지 서버에 물어보고, 아니거나 못 물어보면
//     **기기에도 안 쓴다.** SQL 을 깐 다음 회차에 한꺼번에 올라간다 — 잃는 것은 없다.
//   ■ 항목 세계의 안전장치를 새로 세웠다 — pushHold(급감 보호)가 여기선 영영 안 걸리기 때문이다
//     (키 하나당 개수가 늘 1이라 절대 급감하지 않는다). 그래서 **쓰기 지점**에서 '사라진 선수 수'를
//     본다: 5명 이상(또는 절반 이하로) 빠지면 **무덤돌을 쓰지 않고** 멈추고 묻는다.
//     그동안 그 선수들은 팀 서버에 살아 있다. 1.568 에서 배운 것과 같다 — 감지는 쓰기 지점에.
//   ■ 같이 막은 구멍 세 개 (전부 '이름을 적어 둔 고정 목록'이 원인 — 항목 키는 적을 수가 없다)
//     ① 공간 전환: IDB_CONTENT 에 없어 A팀 선수단이 B팀으로 따라가 **B팀 서버로 올라갈** 뻔했다(1.531 재현)
//     ② 전환 백업·자동 스냅샷: 비우는 목록에는 있고 담는 목록에 없으면 '지웠는데 백업엔 없는' 자료가 된다
//     ③ 내 데이터 삭제: 지워 달라고 눌렀는데 선수 기록이 기기에 남았다
//   ■ 앱과 서버가 **같은 권한 표**를 본다 — sync.js keyScope 도 sq:* 를 'team' 으로.
//     앱이 느슨하면 잠금이 아니고, 엄격하면 "저장했는데 안 올라감"이 된다.
//   ■ 다음(2단계) — 코드 변경 없이 1주 + 저장 3회 이상 관찰. 매일 '자료 확인 › 항목 저장 점검'
//     으로 **서버를 직접 읽어** 통짜 n = 항목 n 을 본다. 어긋나면 3단계로 안 간다.
//
// 1.630: **항목 단위 저장 — 0단계(바닥 공사).** 자료는 하나도 안 바뀐다. 화면도 그대로다.
//   계획 전문: 문서/항목저장-이사계획.md (0~4단계 · 되돌리기 · 옛 기기 영향)
//   ■ 이번에 한 것 — 항목으로 옮기기 **전에** 반드시 있어야 하는 네 가지
//     ① 서버 권한 규칙에 접두사 추가 (supabase-설치/supabase-item-keys.sql)
//        지금 규칙은 키 이름을 하나하나 적어 둔 표다. sq:<id> 는 그 목록 밖이라
//        앱을 먼저 고치면 **선수 전원이 남의 평가를 서버에서 받아 간다.** SQL 이 먼저다.
//     ② kv 전송 청크 분할 (pull 20개 · push 700KB/15행 — 보관함과 같은 잣대)
//        지금 kv 는 "키가 몇십 개"라는 가정 위에 있다. 44명이 키가 되면 첫 동기화가
//        URL 길이를, 첫 이사가 요청 크기를 넘는다 — 한 명이 아니라 그 회차 전체가 실패한다.
//     ③ 항목 키는 **접두사로** 판정한다(IDBK 같은 손으로 적는 목록을 늘리지 않는다 — 1.590 의 교훈).
//        저장소는 IndexedDB — 선수 사진이 들어 있고 이사 중엔 통짜와 항목이 두 벌이라
//        localStorage 5MB 를 그대로 밟는다.
//     ④ 점검 도구: 자료 확인 › 항목 저장 점검 — **서버를 직접 읽어** 통짜 n = 항목 n 확인.
//        기기 사본으로 판단했다가 틀린 복구를 한 게 2026-08-07 이다.
//   ■ 다음(1.631) — 쓰기 이중화. 읽기는 통짜 그대로라 화면 변화는 그때도 0.
//     그때 **사라진 항목 행 수** 검사를 같이 넣는다. 항목 세계에서는 pushHold(급감 보호)가
//     안 걸리기 때문이다(키 하나당 개수가 늘 1이라 절대 급감하지 않는다).
//
// 1.629: **선수를 항목 단위로도 남긴다** (사용자 지시: "보관함에 있는 것처럼 저장").
//   ■ 왜 — 오늘 사고의 근원이 여기다. 명단이 **통짜 문서 하나**라 44명이 한 덩어리로 움직인다.
//     그래서 한 번 덮이니 44명이 통째로 32명이 됐고, 두 사본을 합치니 76명이 됐다.
//   ■ 오늘 밤은 **저장만** 항목 단위로 간다. 서버 구조와 읽기 경로는 그대로다 —
//     이사 도중이 가장 위험한 걸 오늘 두 번 겪었기 때문이다(화면 동작은 하나도 안 바뀐다).
//     · 저장할 때마다 선수 한 명 한 명을 id 로 따로 기록한다(이 기기, ps_roster_keep_v1).
//     · 이 보관소는 **줄어들지 않는다.** 명단에서 빠져도 30일은 남는다.
//     · 다음에 열 때 5명 이상(또는 절반 이상) 사라져 있으면 물어보고 되돌린다.
//     · 용량이 모자라도 본 저장은 절대 막지 않는다(보관은 부수 효과여야 한다).
//   ■ 검증 — 오늘 새벽 사고를 그대로 재현: 44명 보관 → 32명으로 덮임 → 사라진 12명 감지 →
//     되돌리니 44명·중복 0.
//   ■ 다음 — 서버도 항목 단위로(선수 한 명 = 행 하나). 그건 이사 계획을 세우고 낮에 한다.
// 1.628: **긴급 되돌림 — 항목 병합을 끈다.**
//   2026-08-07 새벽, 1.619 의 항목 병합이 **팀 선수단을 44명 → 76명으로 불렸다**(중복 29명).
//   원인: 두 사본이 같은 선수를 **다른 id** 로 갖고 있으면 병합은 다른 사람으로 보고 둘 다 남긴다.
//   id 가 기기마다 새로 생기는 지금 구조에서는 '항목 단위 병합' 자체가 안전하지 않다
//   (1.626 이 포지션에서 겪은 것과 같은 병이다).
//   · **일정만 남긴다** — 일정은 날짜(칸)라는 안정된 열쇠로 병합해 이 문제가 없다.
//   · 선수단·명단·경기는 예전 규칙으로 되돌린다(충돌 시 이 기기 승, 서버본은 되돌리기용 보관).
//   이름+등번호 같은 자연 열쇠로 겹침을 거르는 건 자료를 임의로 합치는 판단이라 급히 넣지 않는다.
// 1.627: **1.626 이 낸 회귀 수습 — 카드 자리가 흩어진 것**(사용자: "막 같이 생겨서 이상해졌어").
//   1.626 에서 포지션 id 를 고정값으로 바꾸면서 **선수단 보드의 카드 좌표를 같이 옮기지 않았다.**
//   좌표(data.meta.tbXY)는 posId 를 열쇠로 쓰기 때문에 전부 미아가 됐고, 카드가 기본 자리와
//   화면 아래로 흩어져 GK·RCB·RW 가 서로 덮였다. **내가 만든 회귀다.**
//   · 좌표도 선수와 같은 두 갈래로 잇는다: 이번에 바꾼 매핑 → 이 기기에 남은 옛 포지션 표(이름 경유).
//   · 옛 표를 찾을 때 **특정 키만 뒤지지 않는다** — 백업·스냅샷·충돌본이 어디에 어떤 이름으로
//     있는지 그때그때 달라서, scout/stash/snap 이 들어간 저장물을 전부 훑어 positions 를 모은다(읽기만).
//   · 못 잇는 자리는 기본 자리로 돌아가고 콘솔에 몇 개인지 남긴다.
//   검증 — 회귀 상황 재현(포지션은 pos_*, 좌표만 옛 id, 옛 표는 다른 키 안에 중첩):
//   pos_GK·pos_LCB 좌표가 제자리로, 정체불명 한 개만 버려짐.
// 1.626: **포지션 id 를 이름에서 나오는 고정값으로** — 후보가 계속 사라지던 진짜 원인.
//   ■ 1.625 로는 부족했다. 고친 34명이 **또** 자리를 잃었다.
//     이틀 사이 포지션 id 가 **세 세대**나 생겨 있었다: pmqizobui… / pmshq7dzw… / pmshqwjng…
//     원인은 포지션 id 가 기기마다 uid("p") 로 새로 뽑히는 것이었다. 같은 'GK' 인데 기기마다
//     id 가 달라서, 다른 사본이 내려올 때마다 선수·후보가 통째로 자리를 잃었다.
//   ■ ① id 를 이름에서 만든다 — GK 는 어디서 만들어도 pos_GK.
//     부팅 때 옛 id 를 고정 id 로 바꾸고, 같은 문서 안 선수들의 posId 도 함께 옮긴다.
//     같은 이름이 둘이면 뒤엣것은 건드리지 않는다(합치지 않는다 — 자료를 임의로 줄이지 않기 위해).
//   ■ ② 그래도 남은 고아는 두 갈래로 잇는다: posName → 이 기기에 남은 **옛 포지션 표**
//     (ps_sync_base_/ps_sync_conflict_/ps_rescue_scout_tool_v1)에서 옛id→이름→고정id.
//     2026-08-07 실제 복구가 정확히 이 경로였다.
//   ■ ③ **후보를 합친 뒤에** 치유한다. 처음엔 load 중간에서 돌렸는데, 후보는 별도 키에서
//     그 뒤에 합쳐지므로 정작 자리를 잃은 후보를 손도 못 댔다(시험에서 셋 다 안 이어져 발견).
//   ■ 실제 자료 기준 — 팀 후보 54개 = 진짜 45명 + 빈 줄 9개.
//     45명 중 34명은 이름으로, 11명은 옛 표로 복구된다.
//   ■ 검증 — 사고 상태를 그대로 재현(세 세대 id + 단서 3종): 이름 있음→GK,
//     옛id만→LCB, 단서 없음→못 찾음(예상대로), 포지션 id 는 pos_GK 형태로 통일.
// 1.625: **스카우트 후보 34명이 보드에서 통째로 사라진 일** — 원인과 재발 방지.
//   ■ 무슨 일이었나 (사용자: "작전판에 왜 안뜨지? 스카우트 후보가")
//     자료는 멀쩡했다. 34명 다 있었다. 그런데 보드의 11자리가 전부 0 이었다.
//     원인: **포지션 목록이 통째로 새로 만들어지면서 id 가 전부 바뀌었다.**
//       후보가 가리키는 posId : pmqizobui…  (옛것)
//       지금 포지션 목록의 id : pmshq7dzw…  (새것)
//     보드는 posId 가 정확히 같아야 선수를 놓는다(sbPlayersAt). 34명이 어느 칸에도 안 걸렸다.
//     게다가 후보 자료에는 포지션 **이름이 없어서**(id만 저장) 그 자료만으로는 되살릴 수 없었다.
//   ■ 복구
//     마지막 동기화 기준본(ps_sync_base_scout_tool_v1)에 옛 포지션 표가 남아 있었다.
//     옛 id → 이름 → 새 id 로 이어 34명 **전원** 제자리로. 지금 값은 ps_pre_posfix_20260807 에 보관.
//     (localStorage 와 IndexedDB 두 곳에 같이 썼다 — 1.618 의 교훈)
//   ■ 다시 안 생기게 세 가지
//     ① **이름도 함께 저장** — 자리에 놓을 때 posId 와 posName 을 같이 남긴다.
//     ② **부팅 때 자가 치유** — 고아를 발견하면 그 이름으로 조용히 다시 잇고 몇 명인지 알린다.
//        이름조차 없는 옛 자료는 못 고친다 → '자료 확인 › 지난 판본'으로 되돌리라고 콘솔에 남긴다.
//     ③ **포지션 삭제 경고** — "이 포지션을 쓰는 N명(선수 n·후보 m)이 자리를 잃습니다".
//        예전에는 그냥 지웠고 그 선수들은 조용히 사라졌다.
//   ■ 검증 — 선수 3명의 posId 를 일부러 죽은 값으로 바꾸고 새로고침 → 이름으로 전부 제자리,
//     남은 고아 0, 모든 선수에 posName 저장(11/11).
// 1.624: **원칙에 '언제·왜'를 붙였다** — 게임모델을 프로 기준으로 올리는 첫 걸음.
//   ■ 무엇이 빠져 있었나
//     원칙이 **문장 한 줄**이었다. 그런데 축구에서 중요한 건 움직임 자체가 아니라 언제·왜 하는가다.
//     그 자리가 없으면 영상 태깅·훈련 연결·준수도 평가가 붙을 곳이 아예 없다 — 그래서 여기가 먼저다.
//   ■ 원칙 카드 (원칙 줄 옆 '상세')
//     왜 하는가 / 팀 행동 / 유닛 행동 / 개인 행동 / 성공 기준 / 실패 위험 여섯 칸.
//     · **기존 문자열은 그대로 둔다.** 상세를 처음 적을 때만 {t:…} 객체로 올린다 —
//       쓰지도 않을 빈 칸 여섯 개를 모든 원칙에 심어 동기화를 시끄럽게 만들 이유가 없다.
//     · 적힌 게 있으면 칩이 '상세 ●' 로 차고, 접혀 있어도 **인쇄에는 펼쳐 찍는다**
//       (누르기 전엔 칸이 DOM 에 없어 종이에 빈칸으로 나가던 것을 미리 만들도록 고쳤다).
//   ■ 트리거는 **넣지 않았다** — 단계마다 '트리거 (신호)' 목록이 **이미 있다**.
//     처음엔 원칙 상세에도 트리거를 넣었다가, 화면을 보고 중복인 걸 알아 뺐다.
//     같은 것을 두 곳에서 적게 하면 어느 쪽이 진짜인지 알 수 없게 된다.
//   ■ 곁다리로 잡은 진짜 버그 — process.html 의 훈련 태그가 `(p||'').trim()` 이라
//     **원칙이 객체면 예외가 나고 바깥 catch 가 삼켜 태그 목록이 통째로 비었다.**
//     문자열·객체 둘 다 받도록 고쳤다. scout.html 은 원래부터 둘 다 받고 있었다.
//   ■ 검증 — 원칙 입력 → 상세 열기 → 트리거… 아니라 '팀 행동' 입력 → 객체 승격 확인,
//     새로고침 뒤 상세 칸 6개가 미리 만들어져 있는지, 훈련 태그가 객체를 읽는지 모두 확인.
// 1.623: **노트를 보관함 안으로 · 게임모델을 최상단으로 · 슬라이드 PDF**(사용자 지시).
//   ■ 노트 (지시: "보관함에 넣어줘 보관함 옆에 노트 만들어서")
//     최상단 탭에서 빼고 보관함 바에 '노트' 칩으로 넣었다. 양쪽에 두면 어제 지적하신
//     "너무 많아 헷갈려"가 그대로 반복된다.
//     · 경로 칩(보관함 › 폴더 › …) **뒤에** 붙여 폴더 안에 들어가 있어도 경로가 안 깨지게 했다.
//     · 폴더가 아니라 다른 도구로 가는 문이라 점선 테두리로 결을 갈랐다.
//     · **노트에 있는 동안 최상단 '보관함'을 켜 둔다** — 안 그러면 아무 탭도 안 켜져
//       지금 어디 있는지 알 수 없다(인쇄 화면이 쓰던 방식 그대로).
//     · 설정 › 개인 도구의 노트 버튼은 남겼다 — 팀 화면에서도 닿는 뒷문이다.
//   ■ 게임모델을 최상단 탭으로 (사용자 정의: "게임모델은 일반 사용하는 사람이 만드는 거야")
//     팀 권한이 걸린 자료가 아니라 쓰는 사람이 자기 것을 만드는 도구라 personal 로 올렸다.
//     자료(cs_gamemodel_v1)는 지금 들어가 있는 공간을 따른다 — 개인 공간이면 내 것, 팀이면 팀 것.
//     showApp 의 'ps-team-open' 판정에서 gamemodel 을 떼어냈다. 팀 내비를 타고 들어왔을 때만
//     팀 화면으로 취급한다 — 안 그러면 최상단에서 열어도 팀 줄이 따라 붙는다.
//   ■ 슬라이드 PDF (내보내기가 두 가지로 갈라졌다)
//     · **문서 PDF** = 기존 A4 세로. 이어서 읽고 나눠 주는 것.
//     · **슬라이드 PDF** = 16:9 한 장에 한 국면. 빔에 띄워 설명하는 것.
//       표지(팀 이름 + 정체성 + 날짜) 한 장이 앞에 붙고, 국면마다 단계가 여러 칸으로 펼쳐진다.
//     추가 라이브러리 0 — @page 와 인쇄 CSS 만 쓴다(오프라인 앱이라 용량을 늘리지 않으려는 것).
//     크기는 파워포인트 기본 와이드(13.333in × 7.5in)와 같게 잡았다.
//     **이름 붙인 @page(page:gmslide)는 쓰지 않는다** — 브라우저마다 지원이 달라 어떤 곳에선
//     그냥 A4로 나온다. 인쇄 직전에 <style>로 넣고 끝나면 뗀다.
//   ■ 만들다가 낸 버그 둘
//     · gamemodel.html 의 esc 가 다른 함수 안에 있는 걸 '중복'으로 오판해 내 것을 지웠다가
//       'esc is not defined' 로 인쇄가 통째로 죽었다. 전용 gmEsc 를 따로 뒀다.
//     · 그때 gm-slide 클래스가 화면에 남아 편집 화면이 인쇄용 모양으로 굳었다.
//       이제 gmPrint 는 try/finally 로 무슨 일이 있어도 원래대로 되돌린다.
//   ■ 검증 — 인쇄 창을 띄우지 않고 준비 단계를 관찰했다: 16:9 종이 규칙 주입 확인,
//     표지 생성('FC 프로세스 게임모델'), 국면 6개 전부 펼침, 끝난 뒤 클래스·표지·규칙 모두 원복.
//   ■ 아직 안 한 것 — **PPTX 내보내기**(사용자가 "둘 다" 선택, PDF 먼저). 다음에 붙인다.
// 1.622: **담당 칩이 잘 안 보이던 것**(사용자 질문: "담당 칩이 어디에 생겨?").
//   위치는 팀 › 경기, 경기 제목 카드 오른쪽('장소 미정 · 구분 미정' 옆)이 맞다.
//   그런데 **실제로 눈에 안 들어왔다.** 그 카드(.match-summary)는 남색 그라디언트(rgb 21,42,88)인데
//   칩에는 라이트 토큰(--dim 회색·--line)을 그대로 썼다. 대비를 재 보니 **2.2:1** —
//   4.5:1 기준에 한참 못 미쳐 사실상 안 보이는 상태였다.
//   같은 줄의 '장소 미정' 칩은 이미 흰 글씨 + 반투명 흰 배경을 쓰고 있었다. 거기에 맞췄다.
//     · 담당 없음 = 점선 테두리 + 흰 글씨(.86)   · 담당 있음 = 실선 + 흰 글씨
//     · 내가 담당 = 연한 파랑(#A8C0FF 테두리 · #E4ECFF 글씨)
//     · 안내바도 같은 카드 안이라 흰 계열로 — 파란 글씨는 남색 위에서 역시 안 보인다
//   검증 — 같은 자리에서 다시 재니 **9.13:1**. 화면으로도 '담당 없음'·'담당 이슬기' 둘 다 확인.
//   교훈: 어두운 카드 위에 얹는 조각에 **라이트 토큰을 그대로 쓰면 안 된다.**
//   그 카드 안에 이미 있는 조각이 어떻게 칠해져 있는지를 먼저 볼 것.
// 1.621: **경기마다 담당 코치 한 명** — 사용자 제안("코치1만 수정 가능하게")의 실행판.
//   ■ 왜 '전부 한 사람'이 아니라 '자료마다 한 사람'인가
//     전부 한 사람으로 굳히면 34명이 보기만 하는 방송이 된다. 실제로 격리 중인데도 스태프
//     한 분이 경기 기록을 27건 썼다 — 필요해서 쓴 것이고, 막으면 앱 밖(수첩·단톡방)에 쓴다.
//     그리고 이건 2026-08-02 에 사용자가 이미 승인한 원칙이다:
//     **"통짜 키는 주인 한 명, 항목 단위는 만든 사람."**
//     경기는 항목이 여럿이라 경기 하나하나에 담당을 둔다. 김코치가 A경기, 박코치가 B경기를
//     같은 시간에 써도 서로 다른 항목이라 1.619 항목 병합이 둘 다 살린다 — 충돌이 0이다.
//   ■ 만든 것
//     · `cs_assign_v1` 신설 — {v:1, match:{경기id: 코치uid}}. **운영진만 쓴다**(canW + 서버 가드).
//       배정 권한과 편집 권한을 갈라 두지 않으면 담당자가 스스로를 다른 경기에 배정할 수 있다.
//       그래서 경기 문서 안이 아니라 별도 키다.
//       **IDBK 에는 넣지 않았다** — localStorage 하나만 쓰면 1.618 의 '저장소 짝 안 맞음'이
//       구조적으로 생길 수 없다.
//     · 경기 머리에 **담당 칩** — '담당 없음' / '담당 ○○○'(내 것이면 파랑). 운영진이면 눌러서 고른다.
//     · 담당이 남이면 그 경기만 보기 전용 + 파란 안내바. 기존 .match-shell.readonly 를 그대로 쓴다.
//     · **담당을 안 정한 경기는 예전 그대로** — 하루아침에 모든 경기를 배정할 수는 없다.
//       정한 것부터 차례로 잠긴다.
//   ■ 검증 — 규칙 7가지 node 하네스 통과(담당은 되고 / 남은 안 되고 / 운영진은 전부 /
//     미지정은 예전대로 / 선수는 담당이어도 불가 / 배정표가 깨져도 안 죽음),
//     브라우저에서 세 상태 확인(스태프·남의 담당 → 잠김+안내바 / 스태프·내 담당 → 열림 / 담당 없음 → 열림).
//   ■ 만들다가 낸 버그를 적어 둔다 — 팀원 이름을 못 받아오면 다시 그리기를 **끝없이 되풀이**해
//     화면이 멈췄다. 실패했을 때 캐시를 null 로 둬서 "아직 안 물어봄"과 구별이 안 됐다.
//     이제 실패해도 빈 배열로 표시해 재진입을 막는다(실제 호출 1회 확인).
//   ■ 서버 가드에도 cs_assign_v1 = 운영진만 을 넣었다 —
//     **supabase-team-write-guard.sql 을 한 번 더 실행해야 반영된다**(지금은 관찰 모드라 급하진 않다).
// 1.620: **되돌릴 수 있어야 팀을 연다** — 복구 창구를 하나로 모으고, 90일치 판본을 꺼내 쓴다.
//   배경 — "코치들에게 일단 건들지 말라고 했어, 날아갈까봐"(사용자).
//   그 판단은 옳았다. 되돌리기가 **일정에만** 있었기 때문이다. 서버 ps_kv_history 에 90일치가
//   쌓여 있는데 앱에서 꺼내는 길이 일정뿐이라, 선수단이 이상해진 걸 사흘 뒤에 알아채면
//   방법이 없었다(사고 직후 뜨는 칩은 그 순간 놓치면 끝난다).
//   ■ ① 문이 너무 많았다 (사용자 지적: "너무 많아 헷갈려")
//      계정 팝업에 '부딪힌 자료 5개' '멈춘 변경 1개' '덮인 자료 8개' 세 줄이 따로 있었다.
//      그런데 1.591 에서 그 셋을 **'자료 확인' 한 화면으로 이미 합쳤는데 옛 세 줄을 안 지웠다.**
//      게다가 여기 숫자는 중복 제거 전이라 설정의 숫자와 어긋났다(5+1+8=14 vs 11).
//      같은 사고가 두 곳에서 다른 이름·다른 숫자로 보이고 있었던 것이다.
//      → 계정 팝업은 **한 줄**로. 이름·숫자·열리는 화면이 설정과 완전히 같다.
//   ■ ② 지난 판본으로 되돌리기 (자료 확인 안에)
//      명단·선수단·경기·평가·보관함·게임모델·훈련·일정·권한 — 자료를 고르면 최근 30판본이
//      시각·항목 수와 함께 뜨고, 골라서 되돌린다. 되돌린 값은 팀에도 함께 올라간다.
//      **새 버튼을 만들지 않았다** — 진입점을 또 늘리면 ①을 되풀이하는 셈이다.
//      되돌릴 때 출고 검사(pushHold)에 걸리지 않도록 승인 도장을 미리 찍는다. 사용자가 직접
//      고른 복구이기 때문이다. 지금 값은 ps_rescue_ 에 남아 다시 되돌릴 수 있다.
//      0건일 때 문구도 "이 기기와 팀이 같습니다 · 지난 판본 되돌리기" 로 바꿨다 —
//      사고가 없을 때야말로 "되돌릴 수 있다"가 보여야 마음 놓고 팀을 연다.
//   ■ ③ 작은 아이패드에서 설정 패널이 잘리던 문제
//      .gearpop 의 높이 상한이 max-width:600px(휴대폰) 안에만 있었다. **가로로 쓰는 아이패드는
//      폭이 넓고 높이가 짧아** 해당이 안 돼, 아래쪽(자료 확인·새로고침)이 화면 밖으로 나갔다.
//      계정 팝업이 1.563 에서 겪은 것과 같은 문제 — 같은 방식으로 맞췄다
//      (max-height:calc(100dvh - 60px) + 스크롤, 100dvh 미지원 폴백, 자식 flex:0 0 auto).
//      검증 — 1024×768(가장 좁은 아이패드 가로)에서 내용 837px 이 708px 안에서 스크롤,
//      맨 아래 줄까지 닿고 가로 넘침 없음, 찌그러진 줄 0개.
//   ■ 아직 안 해 본 것 — 판본 '되돌리기' 버튼은 실제로 눌러 보지 않았다.
//      판본 목록 불러오기(읽기)는 같은 RPC 로 확인했지만, 복구는 자료를 바꾸는 일이라
//      한 건으로 먼저 시험해 보시길 권한다.
// 1.619: **팀원이 임원 자료를 덮지 못하게** (사용자 지시: "워크플로우 잘 설정해야 할 것 같아").
//   ■ 먼저 확인한 것 — 가정이 아니라 풋볼A 실제 기록이다
//     · 2026-08-04 15:26 소유자가 지정한 **운영진이, 15:36 다른 팀원의 낡은 사본에 덮여
//       약 1시간 30분 동안 사라져 있었다.** 그 사이 네 명이 더 그 상태를 밀어 올렸다.
//     · **선수 2명이 권한 문서(cs_perms_v1)를 서버에 썼다**(8/5). 선수는 쓸 수 없어야 하는 자료다.
//     · 서버가 막고 있던 건 일정 하나뿐이었고, 그 가드마저 역할을 ps_members.role 에서 읽는데
//       풋볼A 는 소유자를 뺀 33명 전원이 'member' 라 **어떤 분기에도 걸리지 않았다.**
//   ■ 왜 뚫렸나 — 잠금장치의 열쇠를 문 바깥에 뒀다
//     푸시 권한 판정이 `var role='admin'` 으로 시작했다. 권한 문서를 못 읽으면 그대로 admin 이라
//     **모든 팀 자료를 올릴 수 있었다.** 못 읽는 경우는 드물지 않다 — 새 기기 첫 부팅, 저장 공간
//     부족, 그리고 1.589~1.617 처럼 권한 문서가 아예 전달되지 않던 기간(1.618 참고).
//   ■ ① 기본값을 닫았다 (앱)
//     · 푸시 판정 role 기본값 'admin' → 'player'. 권한 문서를 못 읽으면 아무것도 못 올린다.
//       못 올린 자료는 m.h 를 갱신하지 않아 로컬에 남고, 문서가 도착한 다음 회차에 올라간다.
//     · 화면 권한(perms.js myRole)도 팀 공간에서는 'player' 로 닫았다. **개인 공간은 그대로 admin**
//       이라 혼자 쓰는 사람은 영향이 없다.
//     · 남의 IDP 를 받아오는 판정도 같은 fail-open 이었다 — 권한 문서를 못 읽은 기기가 팀원 전원의
//       개인 성장 계획을 통째로 받아 오고 있었다. 함께 닫았다.
//     · 권한 문서는 동기(sync) 판정에 쓰이므로 permsPrime() 으로 IndexedDB 에서 미리 확보하고,
//       localStorage 거울을 **없어도 만든다**(3KB). 안 그러면 새 기기가 억울하게 막힌다.
//   ■ ② 서버에 진짜 잠금 (supabase-설치/supabase-team-write-guard.sql — 직접 실행 필요)
//     · 역할을 **권한 문서에서** 읽는다(ps_members.role 은 전원 'member' 라 못 쓴다).
//       표는 앱 canW 와 글자 그대로 같다: 일정·권한=운영진만 / 나머지 팀 자료=스태프 이상 /
//       선수=자기 IDP만. 서버가 더 엄격하면 "저장했는데 안 올라감"이 되므로 어긋나면 안 된다.
//     · **권한 문서 통째 덮기 차단** — 운영진이 아니면 '자기 항목이 있는지 확인'만 할 수 있다.
//       남의 역할도, 자기 역할도 못 바꾼다. 8/4 사고가 바로 이 통째 덮기였다.
//     · 앵커 롤백 금지는 **소유자에게도** 적용한다. 2026-08-03 펌프의 범인이 소유자 본인 계정의
//       잊고 켜 둔 컴퓨터였기 때문이다 — 여기서 소유자를 빼면 그 사고가 그대로 다시 열린다.
//     · **예외를 던지지 않는다.** ps_kv 는 배치 upsert라 한 행이 예외를 내면 그 사람의 다른 자료까지
//       통째로 실패한다(1.501 에서 겪음). 거부는 ps_kv_denied 에 남긴다.
//     · **처음엔 차단하지 않는다.** ps_guard_mode.enforce=false 로 설치돼 기록만 남는다.
//       하루쯤 보고 억울하게 걸리는 사람이 없으면 그때 켠다. 잘못 걸어도 아무도 못 저장하는
//       사태가 생기지 않게 하려는 것이다(로컬 Postgres 가 없어 실행 검증을 못 했다).
//   ■ ③ 거부를 알린다
//     서버가 조용히 옛 값을 지키면 올린 사람 화면에만 남아 "내 수정이 팀에 안 보여"가 된다 —
//     2026-08-06 하루를 그렇게 썼다. 이번에 올린 키 중 거부된 게 있으면 칩으로 알리고,
//     m.c[k]=0 으로 두어 다음 회차에 팀 자료를 받아 화면을 실제와 맞춘다.
//     그때 kvWrite 가 내 값을 ps_rescue_ 로 남기므로 작업이 사라지지는 않는다.
//   ■ ④ 허락된 사람끼리도 안 덮이게 — 항목 단위 병합
//     명단(scout_tool_v1)·선수단 거울(cs_squad_v1)·경기(cs_team_matches_v1)는 **문서 통째
//     마지막 저장 승**이었다. 코치 둘이 같은 시간에 다른 선수를 평가하면 늦게 저장한 쪽이 이기고
//     먼저 저장한 쪽 작업이 통째로 사라졌다 — 경고도 없이.
//     일정에 쓰던 3-way 병합(base·내 것·서버 것)을 항목 id 단위로 일반화해 붙였다.
//     한쪽만 고친 항목은 그쪽, 양쪽 다 고친 항목만 로컬 승, 삭제는 반대쪽이 안 건드렸을 때만 존중.
//     **명단 순서는 내 화면 기준으로 유지**한다 — 코치가 직접 맞춰 둔 것이라 흔들면 안 된다.
//     검증: 17개 시나리오(선수단 11 · 경기 2 · 명단문서 4) node 하네스 통과.
//   ■ 곁다리로 찾아 함께 고친 것
//     · 팀원 권한 편집창이 저장할 때 문서를 **통째로 새로 만들고 있었다.** 그래서 목록에 안 뜬
//       사람의 권한이 매번 사라지고, 일정·선수단 잠금 토글(schedEdit·rosterEdit)도 초기화됐다.
//       이제 지금 문서를 바탕에 놓고 이 창에서 다룬 사람만 덮어쓴다.
//     · PSPerms.set 이 localStorage 에만 썼다(1.618 과 같은 저장소 버그) → 두 곳에 같이 쓴다.
//     · 스카우팅의 경기 화면이 **일정 문서에도** 쓰고 있었다(경기 ID 도장). 저장소 버그였고,
//       이제 일정 편집권이 없으면 그 도장을 건너뛴다 — 없으면 엉뚱한 거부 경고만 뜬다.
// 1.618: **내가 고친 게 팀에 안 보이던 진짜 이유 — 자료가 두 저장소에 따로 살고 있었다.**
//   신고: "선수단이 팀에 안 올라간다", 이어서 "일정도 내가 수정한 게 다른 팀원에게 안 보여".
//   같은 원인이었고, 실제로는 **일정·경기·권한·선수단 네 가지가 함께** 끊겨 있었다.
//   ■ 무슨 일인가
//     동기화(sync.js)는 IDBK 목록에 든 키를 **IndexedDB 에서 읽어 올린다.**
//     그런데 그 화면들의 저장 코드는 **localStorage 에만** 쓰고 있었다.
//       · 일정 process_coach_v1  ← process.html save()
//       · 경기 cs_team_matches_v1 · 후보 cs_scout_targets_v1 ← scout.html store.set
//       · 권한 cs_perms_v1        ← process.html / scout.html 잠금 칩
//       · 선수단 cs_squad_v1      ← scout.html 거울
//     처음 한 번은 맞았다 — storage.get 이 "IndexedDB 가 비면 localStorage 값을 끌어와 심는"
//     폴백을 갖고 있어서다. 그 뒤로 IndexedDB 에 그때의 사본이 굳었고, 화면을 아무리 고쳐도
//     팀에는 굳은 옛 자료만 계속 올라갔다. **오류도 경고도 없다** — 올리기는 성공하니까.
//     실제 확인(2026-08-06 풋볼A): 선수단 화면 44명 / 팀 27명, 일정·경기·권한도 어긋나 있었다.
//   ■ 언제부터인가
//     선수단은 그 전부터, 나머지 셋은 **1.589** 부터다. 1.589 는 "앱이 IndexedDB 에 쓰는데
//     동기화가 localStorage 를 읽는다"는 반대 방향 버그를 고치려고 네 키를 IDBK 에 넣었는데,
//     정작 그 화면들이 IndexedDB 에 안 쓰고 있다는 걸 확인하지 않았다.
//   ■ 고친 것
//     ① storage.js 에 **psSaveShared(키, 문자열)** 신설 — localStorage 와 IndexedDB 에 같이 쓴다.
//        성공 여부는 localStorage 기준으로 돌려준다(호출부의 판단 기준을 바꾸지 않는다).
//        저장 지점 다섯 곳(일정 save·일정 시점복구·scout store.set·권한 칩 2곳)을 여기로 모았다.
//     ② scout.html 에 SHARED_IDB 목록 — 이 파일이 쓰는 키 중 IndexedDB 쪽이 동기화 대상인 것들.
//        **주의: scout.html 의 store 는 IndexedDB 가 아니라 localStorage 껍데기다.**
//        board.html 의 store 와 이름만 같다 — 이것 때문에 첫 수정이 통째로 헛돌았다.
//     ③ **받는 쪽도 끊겨 있었다.** 내려받은 값은 kvWrite() 가 IndexedDB 에만 쓰는데,
//        작전판 squadLoad() 는 localStorage 를 먼저 읽고 값이 있으면 IndexedDB 를 안 본다.
//        → 내려받을 때 **이미 거울이 있는 키만** localStorage 도 함께 갱신한다.
//           없던 키까지 만들지는 않는다 — 노트·매치데스크 같은 큰 값이 5MB 한도를 다시 넘는다.
//     ④ 남은 IndexedDB 키 전수 대조: 훈련·보관함·노트·매치데스크·경기(cs_match_v1)·자료실은
//        IndexedDB 에만 있어 어긋날 여지가 없다(board.html 의 store 는 원래부터 두 곳에 쓴다).
//   ■ 왜 '보류'로는 못 고쳤나
//     승인(holdApprove)은 **IndexedDB 값**의 해시를 허가증으로 남긴다. 그 값이 이미 서버와 같은
//     옛 자료였으니 승인해도 올릴 게 없어 pushed:0 만 반복됐다. 보류는 원인이 아니라 결과였다.
//   ■ 교훈
//     `pushed:0` 인데 화면 값과 다르면, 보류·권한을 의심하기 전에
//     **"동기화가 읽는 저장소"와 "화면이 쓰는 저장소"가 같은지부터** 볼 것.
//     IDBK 에 키를 넣을 때는 그 키를 쓰는 화면이 정말 IndexedDB 에 쓰는지 반드시 확인할 것.
// 1.617: **강도를 숫자만 고르게**(사용자 지시: "그냥 숫자만 선택할 수 있게").
//   ① 1.613 은 버튼 하나에 숫자와 말을 둘 다 넣어(1 아주 쉬움) 두 줄이 됐고, 다섯 칸이 모두
//      상자라 요란했다. 이제 **한 줄에 숫자 다섯**(34×34), 줄 전체가 186px 로 줄었다.
//   ② **색은 고른 칸 하나에만.** 나머지는 조용한 회색이다. 한 화면에 강한 색이 하나면 충분하다.
//   ③ 말(아주 쉬움·쉬움·보통·힘듦·아주 힘듦)은 title 과 aria-label 로 남겨 뜻을 잃지 않는다 —
//      눈으로는 숫자만 보이고, 오래 누르거나 스크린리더로는 말이 나온다.
//   ④ 옆 뱃지(원본 1~10 값)는 뺐다 — 1~5 버튼 옆에서 '8'을 보여 주면 서로 어긋나 보인다.
//      저장은 여전히 1~10(2·4·6·8·10)이라 부하 계산은 그대로다.
//   ⑤ 검증 — rpe 8 → 4번 칸에 주황, 나머지 넷은 회색 하나로 통일, 뱃지 0개.
// 1.616: **훈련 만들기가 '훈련 구성'에서 바로 시작한다**(사용자 지시).
//   «이런 단계 필요없고 바로 이 화면 나오게 해줘, 바로 만들 수 있게»
//   ① 1단계(세션 설정)는 이름·날짜·시간·팀·인원·목표를 묻는 관문이었는데, 그 값들은 코드가
//      **이미 기본값으로 채워 두고 있었다**(오늘 날짜, "8월 6일 훈련" 같은 이름).
//      즉 관문을 지나며 하는 일이 대개 '다음'을 누르는 것뿐이었다. 이제 작전판이 바로 열린다.
//   ② 없앤 게 아니라 뒤로 옮겼다 — '이전'을 누르면 1단계로 가고, 값도 채워진 채로 뜬다.
//   ③ 함정 하나 — setTrainingWizardStep(2) 는 들어가면서 trainingWizardSyncSetup() 으로
//      **1단계 입력칸을 읽어** meta 에 되쓴다. 1단계를 건너뛰면 그 칸이 비어 있어 방금 채운
//      기본값이 그대로 지워졌다(첫 시도에서 이름·날짜가 빈 값으로 확인됨).
//      그래서 넘어가기 전에 trainingWizardFillSetup() 으로 칸을 먼저 채운다 —
//      화면에 안 보여도 값은 거기 있어야 한다.
//      확인: 시작 시 name "8월 6일 훈련" · date 2026-08-06 · time 16:00 · players 18 유지,
//            '이전' → 1단계로 가며 입력칸에 같은 값이 들어 있음.
//   ④ 메모 안내문 "현장에서 바로 적어두세요." → "메모"(사용자 지시).
// 1.615: **오늘 화면 인원 카드 정리 셋**(사용자 지시).
//   ① 가용 경고 띠(⚠ GK 가용 1/3 · 수비 5/16 …) 삭제 — «없어도 돼».
//      바로 위 타일이 이미 '훈련 가능 14/44 · GK 1 · 필드 13'을 말하고 있어, 같은 사실을
//      포지션별로 한 번 더 적으면서 **빨간 경고의 무게까지** 얹고 있었다.
//      빨강은 손을 써야 하는 일에만 쓰는 색이다 — 매일 뜨는 빨강은 곧 안 보이게 된다.
//      warn 계산은 남겨 뒀다: 나중에 조용한 방식(포지션 줄 숫자 색)으로 되살릴 수 있다.
//   ② "상태는 '상태 확인'에서" 안내 삭제 — 카드 오른쪽 위에 '상태 확인 ›' 버튼이 이미 있다.
//      버튼 옆에서 그 버튼을 말로 한 번 더 가리키던 줄이다.
//   ③ '선수 체크인' 카드 삭제 — 선수가 IDP에서 강도를 눌러야 채워지는데, 비어 있는 동안에는
//      "아직 없습니다 + 어떻게 하면 채워집니다"라는 안내만 카드 한 장을 차지했다.
//      renderTeamCheckin 은 남겼다 — 대상이 없으면 첫 줄에서 그냥 돌아간다.
//   ④ 숫자를 파랑으로(--blue) — 이 카드에서 읽는 것은 숫자인데 검정이면 라벨·이름과 같은
//      무게라 눈이 어디를 볼지 정하지 못했다. 인원 타일(11 · 1 · 10)과 포지션 줄 숫자 모두.
//   ⑤ 검증 — 셋 다 0개, 숫자 rgb(58,109,240), 가로 넘침 0, 스크립트 오류 0.
// 1.614: **드릴 편집기에서 날짜·시간을 걷었다**(사용자 판단).
//   «어차피 훈련을 계속 만들 거고, 도서관에서 찾아 읽듯 보관함에 잘 보관해서
//    필요할 때 꺼내 쓰거나 편집해서 쓰면 될 것 같아»
//   ⓪ 맞는 말이고, **코드가 그 말을 배반하고 있었다.** 그 칸은 드릴이 아니라
//      **세션의 날짜**(session.date)를 고치고 있었다. 보관함 카드를 열어 편집할 때도 떠 있어서,
//      재사용하려고 꺼낸 카드에 "이 카드는 며칠입니까"를 물었다. 카드는 날짜를 갖지 않는다.
//   ① 세션의 날짜·시간은 마법사 1단계(#twDate·#twTime)가 맡는다 — 원래 거기 있었다.
//      즉 같은 값을 두 곳에서 고치고 있었고, 그중 한 곳은 뜻이 맞지 않는 자리였다.
//   ② 시간도 함께 걷었다 — 날짜 없는 시간은 혼자 설 수 없다. 시간만 따로 필요하면 되살리겠다.
//   ③ 값은 그대로다(session.date·time 보존 확인). _bindMeta 는 대상이 없으면 조용히 건너뛴다.
//   ④ 이제 편집 패널 첫 줄은 인원(GK·필드·재활·부상·불참)으로 시작한다.
// 1.613: **강도 5단계 선택 + 메모칸 다섯 줄**(사용자 지시).
//   ① 강도 — 슬라이더를 걷고 **다섯 칸 선택**으로. 코치가 실제로 구분하는 건 다섯 단계인데
//      1~10 슬라이더는 손끝으로 눈금을 맞추게 했다. 문구는 IDP 와 같은 말로 맞췄다:
//      아주 쉬움 · 쉬움 · 보통 · 힘듦 · 아주 힘듦.
//   ② **저장 값은 1~10 그대로 둔다**(2·4·6·8·10). 부하가 분×RPE 라, 눈금을 1~5 로 바꾸면
//      예전에 적어 둔 세션의 부하 숫자가 통째로 절반이 된다. 보이는 것만 다섯으로 줄였다.
//      옛 값(7 같은 것)은 가장 가까운 칸이 켜지고, 동점(7 은 6·8 과 똑같이 1 차이)이면 **센 쪽**을
//      잡는다 — 7을 '보통'으로 낮춰 부르면 실제보다 가벼운 세션으로 읽힌다.
//      확인: 1→아주 쉬움 · 3→쉬움 · 5→보통 · 7→힘듦 · 9,10→아주 힘듦.
//   ③ 메모칸을 74px(세 줄) → 118px(약 다섯 줄)로. 현장에서 적다 보면 금세 스크롤이 생겼다.
//      다른 항목(116px)과 같은 높이로 맞췄다.
//   ④ 인원 합계를 제 줄로 내렸다 — 네 칸이 좁은 패널에서 두 줄로 접히는데 합계까지 끝에 붙으면
//      "부상·불참 훈련 18명"처럼 한 덩어리로 읽혔다.
//   ※ '날짜와 강도 5단계' 중 날짜는 손대지 않았다 — 날짜는 다섯 단계로 나눌 값이 아니라
//     잘못 적으신 것으로 보았다. 다른 뜻이면 알려 주시면 고치겠다.
// 1.612: **훈련 편집 패널 덜어내기 넷**(사용자 지시).
//   ① 마법사 단계 탭 4개 삭제 — «이게 너무 많아».
//      아래 '이전'·'다음' 버튼이 같은 단계 이동을 하고, 지금이 몇 단계인지는
//      '1 / 4 · 세션 설정' 줄이 말한다. 탭은 그 둘을 세 번째로 되풀이하던 것이다.
//      setTrainingWizardStep 과 배선은 그대로 뒀다 — 대상이 없으면 조용히 건너뛴다.
//   ② '빠른 메모' → '메모' — «빠른 필요 없어 메모만».
//      이미 저장된 양식(cs_drill_form_v1)의 이름도 따라 바꾼다. 이름만 바뀌므로 적어 둔 내용은 그대로.
//   ③ '경기와 닮은 설계 · 4Ds'를 **접어 두고 쓸 사람만 편다**.
//      지우지 않은 이유 — 이건 코치가 무엇을 생각해야 하는지 알려 주는 틀이다. 늘 펼쳐 두면
//      매번 지나쳐야 하는 벽이 되고, 지우면 그 물음 자체가 사라진다.
//      **이미 고른 게 있으면 열어 둔다** — 적어 둔 것이 접혀 숨으면 안 된다(확인함).
//   ④ 인원을 **GK · 필드 · 재활 · 부상·불참** 넷으로.
//      오늘 화면이 이미 'GK 2 · 필드 16'으로 세고 있어 같은 문법으로 맞췄다.
//      session.players(총원)는 **그대로 둔다** — 세션 목록·주간·저장 등 여러 곳이 이 값을 읽는다.
//      넷을 고치면 훈련 가능(GK+필드)을 그 자리에 다시 써 넣어 옛 값을 읽는 곳이 계속 맞는다.
//      재활·부상은 총원에 안 넣는다 — '오늘 훈련에 설 사람'이 이 숫자의 뜻이기 때문이다.
//      옛 세션(총원만 있는 것)은 그 값을 '필드'로 옮겨 잃지 않는다(확인함).
//   ⑤ 검증 — 단계 탭 0 · 옛 인원칸 0 · 새 인원칸 4 · 항목 15개 중 첫 이름 '메모' ·
//      4Ds 비었을 때 접힘/값 있을 때 열림 · 'GK 2 필드 16 재활 3 부상 1' → 표시 "훈련 18명 · 빠짐 4",
//      총원 18 · 옛 세션 18 → 필드칸 18.
//   ※ 남은 제안(빈 항목 전체 접기, 양식 편집을 설정으로 이동, 국면 중복 제거, 날짜·시간 이동)은
//     목업으로만 두고 손대지 않았다 — 사용자가 고른 넷만 했다.
// 1.611: **팀에서 받기** — 올린 것을 다른 사람이 설정에서 가져온다(사용자 지시).
//   ⓪ 먼저 사실 정리 — «저장 버튼»은 이미 있었다(1.588 '동기화 · 지금 올리기').
//      그리고 syncNow 는 올리기와 받기를 **함께** 한다. 없던 것은 기능이 아니라
//      **받는 사람이 누를 자리**였다. 버튼 이름이 '지금 올리기'라, 팀원이 올린 걸 가지러 온
//      사람에게는 누를 이유가 없어 보인다. 그래서 같은 엔진을 부르되 받는 쪽 언어로 말한다.
//   ① 설정에 '팀에서 받기 · 지금 받기' 한 줄 추가. syncNow 가 돌려주는 applied 가 곧
//      '서버에서 받아 쓴 항목 수'라 "새 자료 3건 받았습니다"로 그대로 쓴다.
//      받은 게 있으면 열려 있는 탭에 dataPulled 를 보내 화면이 곧바로 따라오게 한다.
//   ② 마지막으로 받은 시각(ps_last_pull_at)을 남겨 누르기 전에도 "3분 전"을 보여 준다.
//      **자동 회차도 이 값을 남긴다** — 자동으로 이미 받아 놓고 "아직 받은 적 없음"이라 하면 거짓말이다.
//   ── 그리고 '빠르게'의 실체
//   ③ 전에는 자동 회차가 늘 3분이라 팀원이 올린 걸 최대 3분 뒤에야 봤다.
//      **화면을 보고 있는 동안에는 45초**로 당기고, 탭이 숨겨져 있으면 3분 그대로 뒀다
//      (배터리·요청 수). 숨은 동안 쌓인 것은 돌아오는 순간 visibilitychange 가 즉시 당겨온다.
//      → 팀원 편집 후 내가 보게 되기까지: 최대 3분 → **최대 45초**(설정에서 누르면 즉시).
//   ④ 더 빠르게 하려면 Supabase Realtime(웹소켓)으로 1초 이내가 되지만,
//      대시보드에서 테이블 Realtime 을 켜야 하고 실기기 둘로 검증해야 해서 따로 남긴다.
//   ⑤ 덮어쓰기는 늘어나지 않았다 — pushHold(급감 보호)·conflict 처리는 그대로다.
// 1.610: **오늘 화면 — 2주 스트립 + 위계·정렬 정리**(사용자 지시, 목업 확인 후).
//   ── A. 주간 스트립 → 2주(14일) 고정
//   ⓪ 전에는 경기가 가까우면 그 날까지만 그려 칸 수가 5~10 사이로 들쭉날쭉했다(MD-2 면 5칸).
//      보는 창이 매번 달라지면 어디를 보고 있는지 매번 다시 가늠해야 한다. 오늘부터 14일 고정.
//   ① 14칸을 한 줄에 넣으면 칸당 63px 이라 '목 6 · MD-2'가 안 들어간다 → **7칸씩 두 줄**.
//      덤으로 열이 요일로 맞아떨어져 '다음 주 같은 요일'이 세로로 읽힌다.
//      ‹› 이동도 하루 → **일주일**씩으로 바꿨다(한 줄이 곧 일주일이므로).
//   ② 폰(≤760px)에서는 칸이 42px 이라 '목 6 · MD-2'가 한 줄에 안 들어간다.
//      가로 스크롤로 도망가지 않고 **MD 를 아랫줄로 내려** 2주를 그대로 한눈에 둔다.
//      그러려면 가운뎃점이 CSS 여야 해서 글자에서 빼 .d i::before 로 옮겼다(텍스트 노드는 못 지운다).
//      MD+10·MD+11 이 잘려 자간만 -.05em 좁혔다 — 12px 바닥은 지켰다.
//   ── B. 위계와 정렬(목업에서 합의한 것)
//   ③ **왼쪽 축을 하나로** — 카드는 x=20 에서, 카드 속 글은 x=38 에서 시작하는데 상단 날짜만
//      x=22 라 위에서 아래로 읽을 때 글의 시작점이 튀었다. 카드 속 글이 화면의 대부분이므로
//      그쪽(38)을 주축으로 삼고 상단을 맞췄다. 이제 날짜·TODAY·세션 제목이 모두 38.
//   ④ **굵기 800 을 하나로** — 전에는 날짜 16/800, 눈썹 10/800, 칩 날짜·숫자·주제 800,
//      부하 16/800 … 여섯 곳이 최대 굵기였다. 전부 최대면 굵기로는 아무것도 구분하지 못한다.
//      800 은 세션 제목('수비') 하나만 남기고 나머지는 700·600·400 으로 갈랐다.
//   ⑤ **날짜를 낮췄다** 16/800 → 13/600(2차색). 맥락이지 주인공이 아니다.
//   ⑥ **10·11px 을 12·13px 로** — 눈썹 10 → 12, 설명 11 → 13, 칩 날짜 10 → 12, 주제 14/800 → 13/600.
//      12px 바닥을 지킨다. 반대로 '계획 부하' 숫자는 16 → 22px 로 키웠다 — 읽으라고 있는 값이다.
//   ⑦ **빈 상태를 한 줄로** — 90px 짜리 점선 상자였다. '없다'는 말에 카드의 3분의 1을 쓸 이유가 없다.
//      한 줄로 눕히고 버튼은 줄 오른쪽 끝 링크로. 32px 로 줄었다.
//   ⑧ 칩 높이 56 → 44px(손가락 최소 크기 44pt 에 맞춘 값. 내용이 있으면 49px 로 늘어난다).
//   ⑨ 검증 — 데스크톱 1024: 14칸·7열·왼쪽 축 전부 38·800 은 제목 하나·빈 상태 32px·가로 넘침 0.
//      폰 375: 14칸 7×2, MD 아랫줄, 잘린 칸 0, 가로 스크롤 없음.
// 1.609: **경기 준비 화면 정리 — 순서 바꾸고 둘 걷어냄**(사용자 지시).
//   ── A. 경기 정보를 맨 위로
//   ⓪ 이 화면에서 먼저 확인하는 건 "어떤 경기인가"인데, 그 카드가 큰 보드 아래 접혀 있었다.
//      순서: [경기 정보·선수 상태] → 보드 → 게임플랜 → 선수별 준비 → 코치 메모.
//   ── B. '명단·포메이션'(03) 카드 삭제
//   ① 그 안의 포메이션 select 는 **바로 아래 보드의 '우리 11' 칸과 같은 값**을 정하고 있었다.
//      한 값에 손잡이가 둘이면 어느 쪽이 진짜인지 알 수 없다. 보드 쪽을 남겼다.
//      ※ 함께 사라진 것 — 주장 선택(m.captainId)과 '작전판에서 포메이션 편집' 버튼.
//        둘 다 이 카드에만 있던 것이고 핸들러는 널 가드가 있어 조용히 건너뛴다.
//        주장을 다시 고르셔야 하면 말씀해 주시면 경기 정보 카드로 옮기겠다.
//   ── C. '국면별 상세 게임플랜 · FIFA' 카드 둘 삭제(준비 + 리뷰)
//   ② 이건 원래 **간단/상세 모드의 '상세' 전용 화면**이었다. 그런데
//      · 숨김 규칙 `.match-shell:not(.detailed-mode) .match-fifa-detail` 이 겨냥한 클래스를
//        **어떤 요소도 갖고 있지 않았다**(오타로 보인다) → 간단 모드에서도 늘 보였다.
//      · 모드 토글(`[data-match-mode]`)·안내(`#matchModeHint`) 마크업이 **아예 없었다**
//        → 켤 수도 끌 수도 없었다. 기본값은 simple 인데 상세 화면만 떠 있는 상태.
//      준비 카드만 지우면 짝인 리뷰 카드가 영영 빈 상태로 남으므로 둘 다 걷었다.
//   ③ **자료는 건드리지 않았다** — m.fifaPlans 와 그것을 읽는 곳(오늘 화면 '분석 과제' 3줄)은
//      그대로다. 이미 적어 둔 게 있으면 계속 쓰인다. 화면만 걷었다.
//      죽어 있던 CSS 규칙(.match-fifa-detail)도 함께 지웠다.
//   ④ 검증 — 준비 패널 순서 확인, 지운 셋 마크업 0(주석 제외), 가로 넘침 0, 스크립트 오류 0.
// 1.608: **'훈련이 끝나면 … 훈련 후 기록 ›' 띠를 지웠다**(사용자 지시).
//   화면 맨 아래에서 다음에 할 일을 설명하던 줄이다. 가는 곳(teamHomeGoSchedule)이 이미
//   같은 화면 안 여러 곳에서 열린다 — '오늘 세션 열기'·'훈련 계획 열기'.
//   길이 하나 줄어드는 게 아니라 **같은 문 앞의 안내판 하나가 줄어드는** 것이라, 잃는 건 없다.
//   검증 — 마크업 0, 일정으로 가는 길은 '훈련 계획 열기'·'오늘 세션 열기'로 그대로.
// 1.607: **오늘 화면 되풀이 걷어내기 + 날씨 현재 위치**(사용자 지시).
//   ── A. 같은 사실을 두 번 말하던 넷을 지웠다
//   ⓪ 세어 보니 오늘 화면에서 `MD` 가 여덟 번, 상대팀 이름이 두 번, 경기 날짜가 두 번 나왔다.
//      사용자가 고른 넷을 지운다:
//        · #teamHomeMatchMeta("팀 일정")        — 경기의 출처. 화면이 답할 질문이 아니다.
//        · #teamHomeCycleHint("8/8 (토)")      — 경기 날짜. 아래 스트립이 '토 8' 로 말한다.
//        · #teamHomeEyebrow("MATCH WEEK · MD-2") — 스트립이 MD-2~MD+2 를 펼쳐 이미 말한다.
//        · '경기 계획 보기' 버튼                — 스트립의 경기 칩을 눌러도 같은 곳으로 간다.
//      MD-2(strong)는 남겼다 — 다음 경기까지 며칠인지는 상단이 맡는 유일한 정보다.
//   ① 값을 쓰던 코드는 전부 널 가드가 있어 그대로 두면 조용히 건너뛴다(삭제하지 않았다).
//   ※ 딸려 간 것 둘 — 지운 #teamHomeMatchMeta 는 원래 **대회·장소**(m.competition·m.venue)를
//      싣던 자리고, 경기가 없을 때는 '경기 일정을 등록하면…' 안내를 싣고 있었다.
//      지금 데이터에서 competition 이 '팀 일정'이라 그렇게 보였을 뿐이다. 필요하면 되살릴 것.
//   ── B. 날씨가 처음부터 뜨고, 현재 위치로 맞출 수 있다
//   ② 진짜 마찰은 «지역을 고르기 전까지 버튼에 '날씨'라고만 뜬다» 였다. 두 단으로 풀었다:
//      · 첫 화면 — 시간대(Asia/Seoul)로 기본 지역을 깔아 **묻지 않고 바로** 보여준다. 팝업 0.
//      · 지역 창 첫 자리에 '현재 위치로 맞추기' — **누른 사람에게만** 권한 팝업이 뜬다.
//        원래 주석의 «GPS 팝업도 코치에게 소음이다»는 그래서 지켜진다.
//   ③ 좌표는 역지오코딩 API 를 부르지 않고 **기존 17개 지역 중 가장 가까운 곳**으로 맞춘다.
//      네트워크가 한 번 더 늘지 않고 이름도 한글 그대로다(위도 보정 평면거리).
//      부산·광주·제주·춘천·대전·서울·대구 7개 좌표로 전수 확인 — 전부 맞았다.
//   ④ _headers 의 `geolocation=()` 를 `geolocation=(self)` 로 풀었다. self 라 남의 사이트가
//      iframe 으로 끼워도 못 쓴다. app.html 의 #fScout 에 allow="geolocation" 도 명시했다
//      (같은 출처면 대개 물려받지만 브라우저마다 다르다).
//      ※ _headers 는 넷리파이가 배포할 때 읽는 파일이라 **업로드해야 적용된다.**
//   ⑤ 실패는 조용히 — 권한 거부·시간 초과면 지역 목록으로 돌아가 사유를 한 줄로 알린다.
//      10분 위치 캐시(maximumAge)라 두 번째부터는 즉시.
//   ⑥ 검증 — 저장값을 지우고 새로 열어 **묻지 않고 35° 표시** 확인. 지운 넷은 마크업 0.
// 1.606: **카드에서는 아예 글씨가 안 써지게**(사용자 지시).
//   ⓪ 1.605 는 '평소엔 닫고 누르면 연다'였다. Scribble 은 막았지만, **여는 순간** 그 자리가
//      다시 Scribble 대상이 되므로 펜슬을 쓰는 동안 완전히 안심할 수는 없었다.
//   ① 그래서 작전판 카드에서 편집을 **없앴다** — contenteditable·tabindex·data-tbnum 을 다 뺐다.
//      data-tbnum 이 사라지면 tbWire 의 편집 배선이 붙을 대상 자체가 없어진다(배선도 삭제).
//   ② 잃는 기능은 없다 — 등번호는 **아래 명단의 번호 칸**(#teamList .t-num, 11개)에서 고친다.
//      거기가 원본이고, 폰에서도 그 칸으로 고친다.
//   ③ '눌러서 고칠 수 있다'고 약속하던 표시도 함께 걷었다: 글자 커서·hover 배경·포커스 테두리·
//      '#' 자리표. 약속하지 않으면 눌러 보지도 않는다.
//      커서는 알약의 grab 을 물려받아, **번호 위에서 끌어도 선수 옮기기가 된다**
//      (전에는 번호 칸이 pointerdown 을 막아 그 자리에서만 끌기가 안 먹었다).
//   ④ 스카우팅 칩(소속팀·번호·이름)은 1.605 방식(눌러야 열림)을 유지한다 —
//      «후보는 칩에서 바로 고친다»가 1.558 의 사용자 지시라, 거기선 편집이 기능 자체다.
//      필요하면 칩도 같은 방식으로 걷어낼 수 있다.
//   ⑤ 검증 — 작전판 번호 11칸: 편집 가능 0 · data-tbnum 0 · tabindex 0 · 커서 grab ·
//      드래그 선택 막힘. 명단 번호 입력칸 11개는 그대로.
// 1.605: **애플펜슬로 카드를 끌면 글이 써지던 문제**(사용자 보고, 아이패드).
//   ⓪ 원인 — iPadOS 의 **Scribble**. 펜슬이 '지금 편집할 수 있는 칸' 위를 지나가면 그 움직임을
//      손글씨로 보고 글자로 바꿔 넣는다. 작전판 카드의 등번호 칸이 contenteditable="true" 로
//      **늘 열려 있어서**, 카드를 끌다 펜슬이 다른 카드의 번호 칸을 스치기만 해도 글이 써졌다.
//   ① 왜 기존 방어가 안 통했나 — 그 칸들엔 이미 `pointerdown → stopPropagation`(1.558·1.560)이
//      걸려 있었다. 하지만 그건 **끌기와의 충돌**을 막는 장치다. Scribble 은 포인터 이벤트를
//      보지 않고 **'편집 가능한가'만** 본다. 그래서 이벤트를 아무리 막아도 소용이 없었다.
//   ② 고침 — 펜슬을 무시하는 게 아니라 **평소에 열어 두지 않는다.** Scribble 은 편집 가능한
//      곳에만 붙으므로, 닫혀 있으면 애초에 붙지 않는다.
//      마크업에서 contenteditable 을 빼고, 눌렀을 때(click) 열어 focus·전체선택,
//      손을 떼면(blur) 다시 닫는다. 열린 뒤에는 Scribble 이 정상 작동한다 —
//      번호를 펜슬로 써 넣는 건 그대로 된다. 키보드로도 열 수 있게 tabindex 와 Enter/Space 를 뒀다.
//   ③ 같은 노출이 **스카우팅 칩**에도 있었다. 칩도 끌리는 물건인데(sbChipDown) 안에 늘 열린
//      칸이 셋(소속팀·등번호·이름) 있었다. 같은 방식으로 닫았다.
//      → 작전판 11칸 + 칩 24칸, 평소 열린 칸 **0개**로 확인.
//   ④ 덤 — 손가락으로 스칠 때 생기던 오입력도 같이 사라진다.
//   ⑤ 검증 — 누르기→열림·포커스, 입력, 손 떼기→저장·재렌더·다시 닫힘까지 양쪽 다 통과.
//      (작전판: 저장값이 localStorage 까지 반영되는 것 확인. 칩: 재렌더 후 값 유지 확인.)
// 1.604: **scout 도 같은 손질** — 화면 이름을 되살린다(사용자 확인).
//   ⓪ scout 은 IDP 와 구조가 달랐다. 페이지 머리가 아니라 **뷰 안쪽 섹션 제목** 둘이다:
//      '경기 분석'(matchView) · '스카우팅'(playersView). 둘 다 1.575 규칙에 감춰져
//      설명만 남아 있었다 — '경기 전 계획부터 실제 장면 리뷰…', '후보 선수를 관찰하고…'.
//      역시 이름표가 아니라 부제라, 임자 없이 떴다. 위계도 같은 모양으로 뒤집혀 있었다:
//      설명 12px/600 인데 바로 위 자기 탭이 12px/700.
//   ① 이번엔 **감춤을 되돌리지 않고 선택자에서 뺐다** — premium-ui.css 의
//      `:root[data-shell="1"] .ps-pagetitle` 를 `:not(.ps-page-idp):not(.ps-page-scout)` 로.
//      속성을 하나씩 되돌리면(1.603 의 IDP 방식) margin 같은 걸 빠뜨려 셸 밖(단독 실행)과
//      다르게 그려진다. 1.603 의 IDP 되돌리기도 이 방식으로 바꿔 둘을 한 갈래로 모았다.
//   ② 설명은 400 굵기로 내렸다(`.ps-page-scout .ps-pagedesc`) — 제목과 굵기까지 같으면
//      두 단계가 한 덩어리로 읽힌다.
//   ③ 크기는 각자 자리에 맞게 둔다 — IDP 20px(높이 59~64px 짜리 머리 띠 안, 액션과 한 줄),
//      scout '경기 분석' 30px(내용 맨 위 제목), '스카우팅' 17px(탭 줄에 인라인).
//      맞춘 것은 크기가 아니라 **규칙**이다: 이름이 위계를 갖고 부제는 400 으로 받친다.
//   ④ 나머지 다섯 화면(process·gamemodel·analysis·note·learning)은 이 줄 자체가 없어
//      규칙이 의도대로 작동한다 — 그래서 규칙을 없애지 않고 두 화면만 뺐다.
//   ⑤ 검증(1024px, 셸 안) — IDP 'IDP 20/700 · 개인 성장 계획 13/400',
//      scout 경기 '경기 분석 30/700 + 설명 14/400', scout 스카우팅 '스카우팅 17/800'.
//      셋 다 가로 스크롤 없음. (.sb-desc 는 1280px 아래에서 원래 display:none — 그대로 뒀다.)
// 1.603: **IDP 머리에 화면 이름을 되살린다** («IDP - 개인 성장 계획» — 사용자).
//   ⓪ 무엇이 잘못돼 있었나 — 1.575 규칙이 «탭 내비가 이미 화면 이름을 말하니 페이지는 다시
//      안 적는다»며 제목을 감추고, **설명 한 줄이 눈에 보이는 이름표를 맡는다**고 적어 두었다.
//      그런데 '개인 성장 계획'은 이름표가 아니라 **부제**다. 이름 없이 혼자 서니 브랜드 행과
//      탭 행 사이에 낀 고아 줄이 됐다 — 무엇의 설명인지 위에 아무것도 없다.
//      정작 이름(IDP)은 폰에서 **하단바, 800px 아래**에 있어 눈이 둘을 잇지 못한다.
//   ① 위계는 아예 뒤집혀 있었다 — 화면 이름 자리가 12px/600 인데 바로 아래 자기 탭이 14px/600.
//      **화면의 주인이 자기 탭보다 작고 약했다.** 세 단계로 다시 벌렸다:
//        IDP 20px/700 --text(17.8:1) · 개인 성장 계획 12~13px/400 --text-3(5.4:1) · 탭 14px/600
//   ② 제목은 지운 게 아니라 감춰 둔 것이라(스크린리더용) 마크업은 그대로 두고 감춤만 풀었다.
//      잇는 부호는 앱이 이미 쓰는 가운뎃점(오늘 · 8/6, 하루 루틴 · 잠들기 전 5분)으로 맞췄다.
//   ③ 좁은 화면에서 부제를 --fs-caption(11px)으로 떨어뜨리던 규칙도 --fs-sub(12px)로 올렸다 —
//      12px 바닥 아래였다.
//   ④ premium-ui.css 의 `.ps-page-idp .idp-title small`(0,2,1)이 나중에 로드돼 굵기 600 을
//      도로 씌우고 있어, 클래스 셋(0,3,1)으로 올려 이기게 했다.
//   ⑤ 머리 행 높이는 그대로다(폰 64px · 데스크톱 59px) — 같은 줄에 서므로 세로 공간을 안 먹는다.
//   ※ 다른 5개 화면(process·gamemodel·analysis·note·learning)은 이 줄 자체가 없어 문제가 없다.
//     scout 만 같은 구조('경기 분석' + 설명)라 같은 손질이 필요하다 — 따로 볼 것.
// 1.602: **폰에서 판만 감추고 남아 있던 손잡이도 함께 내린다**(«작전판 밑에 있는 리스트만» — 사용자).
//   ⓪ 1.601 이 판은 내렸는데 그 판을 조작하는 것들이 위에 남아 있었다. 유니폼·GK 색이 그렇다.
//      두 색의 oninput 은 redrawTeamPitch·renderReportPitch·renderPosField·feRender 만 부른다 —
//      **명단에는 한 군데도 쓰이지 않는다.** 판이 없는 폰에서는 눌러도 아무 일이 안 일어난다.
//      감춘 판의 손잡이만 남기면 고장으로 읽히므로 같이 내렸다.
//   ① 포메이션 선택과 ＋자리는 남긴다 — posApplyFormation 이 data.positions 를 채워
//      명단의 포지션 그룹(GK·LCB·RCB…)을 만드는 게 그것이라, 판이 없어도 쓰는 물건이다.
//   ② 검토하다 접은 길 — «접어서 확인», «카드만»도 재 봤다. 접기는 자리를 아낄 뿐
//      펼친 화면이 여전히 24쌍 겹친 채라 '확인'이 안 된다. 판 없이 카드만 2열로 깔면 읽히기는
//      하는데, 그 카드가 담는 내용(포지션·번호·이름·조·상태)이 **바로 아래 명단과 같은 것**이라
//      같은 정보가 570px 를 더 차지하며 두 번 나온다. 그래서 둘 다 접었다.
//   ③ 검증 — 375px: 판·유니폼·GK 색 모두 숨김, 포메이션·＋자리·명단 11행 그대로,
//      가로 스크롤 없음, 페이지 높이 1948px. 1024px(아이패드 가로): 넷 다 보임, 겹침 0.
// 1.601: **폰에서는 작전판을 내리고 명단만 보여준다**(사용자 판단).
//   «폰으로 볼 때는 목록으로 충분할 것 같아 / 작전판은 컴퓨터나 아이패드로 확인하고»
//   «아이패드는 가로로 사용할 거야»
//   ⓪ 숫자가 그 판단을 그대로 받쳐 준다 — 760px 아래에서 판 높이가 420px 로 떨어지는데
//      카드는 180×92 로 고정이라 **카드 11장 넓이가 판 넓이의 127%** 가 된다.
//      자리를 어떻게 옮겨도 안 들어간다: 375px 에서 24쌍, 700px 에서 12쌍이 겹쳤다.
//      좌표계가 가로 경기장(GK x=14% → CF x=89%)인데 담긴 상자는 세로로 길어,
//      11명이 퍼지는 긴 축이 짧은 변(341px)에 눌린 탓이다.
//   ① 줄이는 길도 재 봤다 — 판을 세로로 돌리고(좌표가 % 라 축 교환이면 된다) 카드를 58px 로
//      줄이면 들어간다. 그런데 58px 카드에는 **번호와 이름밖에** 안 남고 끌기·＋선수·조 변경이
//      전부 불가능해진다. 폰의 판은 그림일 뿐 도구가 못 된다. 그래서 축소가 아니라 **제거**다.
//      («코치가 핸드폰을 들고 코칭하는 일은 없다» 는 전제와도 맞는다.)
//   ② 경계 760px — 새로 만든 줄이 아니라 **이미 판이 깨지기 시작하던 바로 그 줄**이다.
//      아이패드는 세로(768)·가로(1024) 둘 다 겹침 0 이라 그대로 둔다.
//   ③ 포메이션 선택(#tmForm)은 폰에서도 남긴다 — posApplyFormation 이 data.positions 를 채워
//      **명단의 포지션 그룹(GK·LCB·RCB…)을 만드는 게 그것**이라, 판이 없어도 쓰는 물건이다.
//   ④ 판 자리에는 한 줄만 둔다("작전판은 아이패드 가로·컴퓨터에서 봅니다 — 폰에서는 아래 명단으로").
//      빈자리를 그냥 두면 고장으로 읽힌다. '미배치 · 우리 선수' 트레이는 판과 함께 내려간다 —
//      판이 없으면 '배치'라는 말 자체가 뜻을 잃는다.
//   ⑤ 검증 — 375px: 판 none·자리 0·명단 11행·가로 스크롤 없음, 페이지 높이 2500→1979.
//      760px 숨김 / 768px 다시 보임(겹침 0) 으로 경계 확인.
//      1024px(아이패드 가로) 네 탭 모두 겹침 0·창 밖 요소 0·콘솔 오류 0.
// 1.600: **넓은 화면 가로 스크롤 제거** — 1.598에서 «따로 볼 문제»로 남겨 둔 것.
//   ⓪ 증상 — 900~1279px 에서 선수 탭만 문서 폭이 창보다 20px 넓어 가로 스크롤바가 생겼다.
//      (1250px 창에서 문서 1270, 1024px 창에서 문서 1044.)
//   ① 원인 — 운동장(.tb-board)에 걸린 `margin-left/right:-21px`. 이 값은 1.583 에서
//      **카드 안쪽 여백 20px + 테두리 1px 을 되빼** 운동장을 카드 끝까지 닿게 하려던 것이었다.
//      그런데 그 뒤 `#teamView.on>.card{padding-left:0!important;padding-right:0!important}` 가
//      들어와 **같은 여백을 이미 걷어내고 있었다.** 되뺄 게 없는데 21px 을 또 빼니
//      운동장이 카드 밖으로 42px 나갔다. 한 가지 목적에 대비책이 둘이었던 셈이다.
//   ② 고침 — 음수 마진만 지웠다. padding:0 만으로 운동장이 이미 카드 끝까지 닿는다.
//   ③ 겹침은 어떻게 됐나 — 1.583 이 음수 마진을 되살린 이유가 «아이패드 1024 에서 카드 4쌍 겹침»
//      이었다. 지금은 그 폭에서 판이 1022px 이고, 음수 마진이 만들어 주려던 폭(982+42=1024)과
//      사실상 같다. 그래서 겹치지 않는다 — 실제로 **11자리 전부 겹침 0** 으로 확인했다.
//   ④ 검증(선수 탭, 포메이션 11자리 배치 상태)
//        910px  판 908  겹침 0  스크롤 없음
//        1024px 판 1022 겹침 0  스크롤 없음   ← 1.583이 문제 삼던 바로 그 폭
//        1279px 판 1277 겹침 0  스크롤 없음
//        1440px 판 1438 겹침 0  스크롤 없음
//      네 탭(오늘·경기·일정·선수) 모두 창 밖으로 나간 요소 0.
//   ⑤ 남는 문제(이번 변경과 무관, 확인함) — **375px 폰에서는 자리 11개가 341px 판 위에서 24쌍이
//      겹친다.** 배포된 1.599 로도 똑같아 이번 수정과 관계없다. 판을 줄이는 게 아니라
//      폰에서는 포메이션을 목록으로 보여주는 쪽이 맞아 보인다 — 설계 판단이 필요해 남긴다.
// 1.599: **선수 명단 이름 칸을 적당히 줄였다**(사용자 지시).
//   ⓪ 1.598 에서 순번 칸(22px)을 빼자 그 폭이 전부 이름 칸으로 흘러갔다. 이름 칸은 `minmax(0,1fr)`
//      이라 남는 폭을 다 먹는다 — 넓은 화면에서 **458px**. 한글 이름 세 글자가 36px 이니 열두 배다.
//   ① 무엇이 문제였나 — 눌러서 편집하면 458px 짜리 빈 입력 상자가 열리고, 평소에도 이름과 상태
//      배지 사이가 400px 씩 벌어져 '이 줄의 상태'를 찾으려면 눈이 미끄러졌다.
//   ② 이름은 **170px 로 묶고**(안쪽 여백 22px 을 빼면 글자 자리 146px — 'Hwang Hee-chan' 이 116px
//      이라 로마자 긴 이름도 들어간다), 남는 폭은 **맨 끝에 1fr 칸을 하나 두어 거기서 받는다.**
//      그러면 배지가 이름 바로 옆(간격 6px)에 붙어 한 덩어리로 읽힌다.
//      칸을 안 두고 이름만 줄이면 배지가 여전히 오른쪽 끝에 붙어 있어 아무것도 안 바뀐다.
//   ③ 이름 칸을 내용 크기(max-content)로 두는 방법은 버렸다 — 행마다 grid 가 따로라 이름 길이가
//      다르면 **줄마다 배지 위치가 어긋난다.** 명단은 세로로 훑는 화면이라 그게 더 나쁘다.
//   ④ 행을 눌렀을 때 뜨는 액션은 폭에 상관없이 아랫줄에 두도록 규칙을 넓은 화면 밖으로 꺼냈다
//      (전에는 min-width:1200px 안에만 있어서 좁은 화면에선 배지 사이로 끼어들 수 있었다).
//   ⑤ 검증 — 470px·900px·1250px 세 폭에서 열 정렬·가로 넘침 0 확인.
//      이름 칸 470px에서 222→170, 1250px에서 458→170. 행 높이·활성화 동작 그대로.
// 1.598: **죽어 있던 글꼴 선언 105곳 복구 + 선수 명단 순번 동그라미 제거**(사용자 지시).
//   ── A. 글꼴 선언 105곳 (스카우트 70 · 프로세스 13 · 보드 8 · 게임모델 7 · 분석 3 · 앱 3 · IDP 1)
//   ⓪ 무엇이 잘못됐나 — `font:800 11px/1 inherit` 처럼 **글꼴 이름 자리에 inherit** 을 쓴 선언이었다.
//      inherit 은 그 자리에 올 수 없어 브라우저가 **선언 전체를 버린다**. 크기만이 아니라 굵기·행간까지
//      같이 사라진다. 그래서 8.5px 배지도, 11px 버튼도, 13px 탭도 전부 **14px/400** 한 덩어리로
//      그려지고 있었다 — 위계가 아예 없었다. (`font:inherit` 단독은 정상이라 37곳은 그대로 뒀다.)
//   ① 되돌리기가 아니라 **재설정**으로 갔다. 원래 값(8.5~11px)을 그대로 살리면 지금 읽히던 글자가
//      갑자기 절반으로 줄어든다. 12px 을 바닥으로 잡고 토큰 스케일에 얹었다:
//        8.5~12px → --fs-sub(12/13)   13~14px → --fs-body(13/14)   15px → --fs-title(15/17)
//        굵기 600/700/800 → --fw-body/strong/head
//   ② 입력칸(textarea·input) 4곳은 --fs-input(16px). 16px 아래면 iOS 가 화면을 확대해 버린다.
//   ③ analysis.html 만 raw px(12/13px). 이 페이지는 premium-ui.css 를 안 불러 var(--fs-sub) 가
//      정의되지 않는다 — 토큰을 쓰면 **선언이 또 버려진다**(같은 버그의 재발).
//   ── B. 선수 명단 순번 동그라미(.tm-depth) 제거 — 사용자 판단("이건 필요없을꺼 같아")
//   ④ 그 자리에서 말하던 두 가지를 화면이 이미 말하고 있었다: 순서는 **행 순서**가, 선발 여부는
//      **아래 줄 흐리기**(tm-sub-row)가. '선발로 올리기'도 ↑ 화살표가 같은 일을 한다(같은 포지션
//      안에서만 자리를 바꾸므로 반복해 누르면 맨 위). 잃은 건 한 번에 올리는 지름길뿐이다.
//      스카우팅 대상 목록(#tgtList)의 '1순위' 동그라미는 그대로 뒀다 — 다른 화면·다른 뜻.
//   ⑤ 빼고 나니 **가려져 있던 레이아웃 버그 둘이 드러났다**:
//      · `#teamList.tm-4col .tm-row` 는 flex 가 아니라 **grid** 였고 첫 칸 22px 이 동그라미 칸이었다.
//        칸을 안 빼면 나머지가 통째로 한 칸씩 밀려 **이름이 202px → 38px 로 찌부러진다.** 칸을 뺐다
//        (이름은 202 → 222px 로 오히려 넓어졌다).
//      · `.t-idp`·`.t-fit`·`.t-foot`·`.t-grp` 에 order 가 없어 기본값 0 이었다. 동그라미(order:0)가
//        앞을 막던 덕에 우연히 맞아 보였을 뿐이라, 빼자 **IDP 칩이 이름보다 앞에 섰다.**
//        줄 순서를 번호1·이름2·적합3·발4·상태5·조6·IDP7·포지션8·액션9 로 **전부 못 박았다** —
//        순서를 비워 두면 다음에 뭘 하나 빼도 같은 일이 난다.
//   ⑥ 검증 — 7개 화면 CSSOM 파싱(무효 0), 6개 뷰 가로 넘침 0, 정상 `font:inherit` 37곳 전수 보존,
//      인라인 스크립트 69개 문법 이상 0, 명단 행 470px·1250px 두 폭에서 열 정렬 확인.
//      ※ 1250px 에서 .wrap 이 20px 넘치는 것은 **이번 변경 전에도 같았다**(수정 전 파일로 확인) —
//        따로 볼 문제로 남긴다.
// 1.597: **IDP — '루틴'과 '개인 훈련'을 한 탭으로**(사용자 지시).
//   ⓪ 왜 — 둘은 같은 것을 반씩 갖고 있었다. 루틴은 **시간**이 있는데 알맹이가 없었고(자유 한 줄),
//      개인 훈련은 **알맹이**가 있는데 시간이 없었다(요일만). 둘 다 '요일마다 반복되는 내 것'인데
//      탭이 갈려 있으니 하루가 두 화면에 나뉘어, 어느 쪽도 하루로 안 보였다.
//   ① 훈련에 시간을 줬다 — trainings[].time. 편집기에 '시간' 칸 추가. '1900' '19' '19.30' 도 받는다
//      (폰에서 콜론을 찾는 건 손이 많이 간다). 알아볼 수 없는 값은 조용히 버리지 않고 되돌려 준다.
//   ② 루틴 탭 = 그 요일의 하루. 시간표 줄과 그 요일 훈련을 **시간순으로 같이** 세운다.
//      원본은 그대로 — 요일은 여전히 trainings[].days 가 갖고, 완료 체크·목표 연결·달력 투영은 안 건드렸다.
//      '＋ 개인 훈련'은 보고 있던 요일이 이미 골라진 채로 편집기를 연다.
//      '이 요일 비우기'는 시간표만 비운다 — 훈련은 다른 요일에도 걸려 있어 여기서 지우면
//      모르는 사이에 그 요일들에서도 사라진다(문구·확인창도 그렇게 고쳤다).
//      요일이 없는 훈련은 어느 요일에도 안 떠서 사라진 것처럼 보이므로 아래에 따로 모은다.
//      코치가 읽을 때는 목표·운동 목록까지 펼친다 — 옛 훈련 탭에서 보던 것을 잃지 않게.
//   ③ 홈 '하루 루틴' 카드도 같은 하루를 보여준다 — 오늘 훈련이 시간 자리에 함께 서고, 그 줄에서
//      바로 완료 체크(일정·목표와 같은 doc.done). 끝낸 줄은 색을 낮춘다.
//   ④ 탭 8 → 7. curL==='train' 은 render 초입에서 routine 으로 돌려 옛 딥링크를 살린다.
//      선수 하단바(5칸)는 그대로 — train 은 원래 선수에게 안 보였고, 이제 루틴 안에서 닿는다.
//      목표 탭 '더보기'의 '개인 훈련' 자리엔 **홈**을 넣었다: 선수 하단바에 홈이 없어서,
//      처음 뜨는 화면인데 한 번 벗어나면 돌아올 문이 없었다.
//   ⑤ 행·열 정리(사용자 지시: 고급스럽게) — 시간 48 · 여백 12 · 내용 · 여백 12 · 조작 34.
//      74px 이던 시간 열은 '07:00'(41px)보다 33px 넓어 시간과 내용이 두 덩어리로 읽혔다.
//      오른쪽 34px 은 모든 행이 공유한다: ×, ›, 완료 동그라미가 **같은 세로선** 위에 선다.
//      보라색 '훈련' 알약은 뺐다 — 절반의 행에 강한 색이 붙으니 목록이 두 갈래로 갈라져 보였다.
//      ›(열림)와 '운동 2 · 25분'(오른쪽 열)이 이미 훈련임을 말한다. 남긴 차이는 굵기 한 단(500).
//   ⑥ premium-ui.css 의 `.ps-page-idp input`(나중에 로드, 같은 특이도)이 루틴 줄을 회색 입력 상자로
//      되돌리고 padding 12px 으로 시간 자리를 어긋내고 있었다. 클래스 셋으로 올려 이긴다.
//   ⑦ **어두운 화면에서 IDP 의 모든 입력칸이 흰 바탕 + 흰 글씨(1.06:1)였다.** premium-ui.css 의
//      `background-color:#fafbfc` 에 dark 짝이 없어서 — 이름·소속팀·포지션 무엇을 적어도 안 보였다.
//      루틴 검토 중 발견해 함께 고쳤다(11.8:1). '이 요일 비우기' 빨강도 3.36 → 5.7:1.
// 1.596: **IDP 폰트 위계 정리 — 루틴 카드 · 탭 내비**(사용자 지시: 애플식으로 깔끔하게).
//   ① 루틴 카드 — **값이 제목보다 강했다.** 시간 07:00 과 내용이 16px/600 이라 카드에서 제일 먼저
//      눈에 띄고, 정작 제목과 같은 무게로 읽혔다. 굵기는 위계를 만드는 도구지 강조 스티커가 아니다.
//      제목 20/600 → 설명 13/400 → 값 16/400 → 보조 13/500 으로 네 단계를 벌리고 입력의 굵기를 걷었다
//      (16px 은 iOS 자동 확대 때문에 못 내린다 — 대신 굵기로 낮췄다).
//      선택 요일도 꽉 찬 보라 → 옅은 틴트 + 보라 글자. 한 화면에 강한 색은 하나면 충분하다.
//      줄 구분은 hairline, 입력 중인 줄만 조용히 떠오르게(:focus-within).
//      삭제는 소문자 x → 곱셈기호로, 평소엔 흐리게 두고 그 줄에 손이 갈 때만 또렷해진다.
//      '이 요일 비우기'는 되돌리기 어려운 동작이라 더하는 버튼들과 같은 줄에서 떼고 한 단 아래 빨강으로.
//   ② 탭 내비 — **선택 표시가 두 개 겹쳐 있었다**: 연보라 알약 배경(premium-ui)과 밑줄(idp .on::after).
//      한 상태를 두 신호로 말하면 둘 다 약해진다. 알약만 남기고 밑줄을 껐다.
//      그리고 **모든 탭이 굵기 800** 이라 선택 여부가 색으로만 구분됐다 — 색각이 다르면 구분이 사라진다.
//      비활성 500 / 활성 600 으로 굵기에도 차이를 줬다. 크기 12 → 14px(탭 라벨은 길잡이라 본문보다
//      작을 이유가 없다).
// 1.595: **IDP 에 '루틴' 탭 · 프로필+평가 병합**(사용자 지시).
//   ① 루틴 탭 — 월~일을 한 화면에서 짠다. 홈 카드에서는 '오늘' 밖에 못 고쳐서
//      월~일을 다 채우려면 일주일을 기다려야 했다. 요일 칩(44px)에 채워진 개수를 배지로 띄우고,
//      '다른 요일에서 가져오기'로 요일마다 처음부터 적는 수고를 던다.
//   ② **A안 확정** — 편집하는 곳이 둘이 되면서 의미를 갈랐다:
//        루틴 탭 = 요일별 **기본** / 홈 카드 = **그날만**.
//      1.594 에서는 홈에서 고치면 요일 기본까지 따라 바뀌었는데(편집 창구가 하나였으니 그게 맞았다),
//      이제는 홈에서 고쳐도 기본은 그대로다 — 병원 가는 월요일에 고쳤다고 매주 월요일이 바뀌면 곤란하다.
//   ③ 프로필과 평가를 '내 프로필' 한 탭으로 합쳤다. 둘 다 '나는 어떤 선수인가'를 적는 곳이라
//      나눠 둘 이유가 약했고, 루틴을 늘리면서 탭이 9개가 되는 걸 막았다(모바일 내비는 5개 이상부터
//      읽기 어려워진다 — 늘리려면 어디선가 줄여야 한다). 탭은 8개 그대로.
//      curL 'eval' 값 자체는 살려 뒀다 — 코치 화면·딥링크가 아직 쓴다. 어느 쪽으로 들어와도 같은 화면.
//   ④ 선수 폰 하단바도 같이 고쳤다 — 그 규칙이 없어진 eval 탭을 가리키고 있어서, **정작 루틴을 쓸
//      선수 폰에서 루틴 탭이 안 보였다.** 4칸(목표·평가·일정·학습) → 5칸(목표·내 프로필·루틴·일정·학습).
//   실측: 탭 8개 · 요일 칩 44px · 요일별 저장/불러오기 · 홈 편집이 기본을 안 건드림 · 프로필+평가 동시 표시 ·
//        선수 폰 하단바 5칸에 루틴 노출(52px·가로 넘침 없음).
//   ⑤ 그 하단바가 **왼쪽으로 몰려 붙어 있던 것도 고쳤다**(사용자 화면). 선언은 display:grid 인데
//      실제로는 flex 였다 — mobile-polish.css 의 `.ps-page-idp #layers{display:flex !important}` 가
//      **ID 선택자 + !important** 라 선수용 격자를 통째로 눌렀다. 그 블록은 코치용 가로 스크롤 내비이므로
//      `body:not(.ps-player-role)` 로 코치일 때만 걸리게 했다. 실측: 선수 5칸 각 70px 균등·넘침 없음.
//      코치 내비의 라벨 '내 프로필'도 폰에서는 '프로필'로 줄였다(390 → 377px).
// 1.594: **IDP 에 '하루 루틴' 추가** — 이명주 선수 글(«기록하는 습관이 좋은 축구 선수를 만든다»)을 옮겼다.
//   ① 시간별 하루 일과 ② 오늘 가장 좋았던 것 ③ 다음 훈련에서 발전시킬 것.
//   ③이 기존 '아쉬운 것'과 다른 점: 회고가 아니라 **다음 행동**이다. 그래서 다음 날 '오늘 집중할 것'
//   자리로 흘러가 루프가 닫힌다(«기록해 두면 언제든 다시 꺼내 볼 수 있다»).
//   **훈련 안 한 날에도 매일 뜬다** — 기존 '훈련 후' 카드는 체크인한 날만 나왔는데,
//   기록 습관은 쉬는 날에도 이어져야 습관이 된다. 그래서 카드를 따로 만들었다.
//   회고 두 줄은 이 카드로 일원화했다(같은 lg:good 을 두 곳에서 입력받아 같은 칸이 두 번 떴다).
//   **요일별 루틴**(사용자 지시): 오늘 루틴을 고치면 그 요일의 기본이 되고 다음 주 같은 요일에 그대로 뜬다.
//   고정 '기본 틀'은 두지 않는다 — 처음 만든 틀은 이명주 선수의 하루였는데 그건 **그 사람의 루틴이지
//   이 선수의 루틴이 아니다.** 남의 시간표를 기본값으로 깔면 지우는 것부터 시작해야 한다.
//   대신 '오늘 팀 일정 넣기'로 앱이 이미 아는 것(훈련 시간·경기·미팅)을 끌어온다.
//   실측: 요일 루틴 자동 적용 · 고치면 기본 갱신 · 두 줄 저장 · 어제 next→오늘 focus 연결 · 입력 48px/16px.
//   ※ 검증 메모: IDP 는 pagehide 에서 메모리 doc 을 강제 저장한다. 그래서 localStorage 를 직접 심고
//     페이지를 이동하면 **심은 값이 옛 값으로 덮인다** — 앱이 없는 별도 페이지에서 심어야 한다.
// 1.593: **주간 일정은 보호가 애초에 안 걸리고 있었다.** 1.592 의 올린 기록이 첫날 잡아낸 구멍이다.
//   기록에 `process_coach_v1(0)` 이 찍혔는데 화면에는 8주치 일정이 멀쩡히 있었다. 값을 뜯어보니:
//     { weeks:{ 0:[7일], 1:[7일], … }, templates:[], wk, dayIdx, … }   ← 127KB
//   psCount 는 **최상위 배열만** 셌고, 최상위 배열은 비어 있는 templates 하나뿐이라 0 이 나왔다.
//   psCount 는 pushHold 가 쓰는 잣대다 → 일정이 통째로 비어도 bigDrop(0,0) 이라 **한 번도 못 막았다.**
//   08-05 스카우팅 후보 사고와 같은 계열(보호가 있다고 믿었는데 실은 안 걸리는 자리)이다.
//   고침: 깊이 3까지 내려가며 배열 길이를 더한다. 배열이 하나도 없는 문서는 예전처럼 칸 수.
//   실측: 8주치 56 · 1주치 7 · 빈 일정 6 → 8주→빈 일정이 이제 막힌다. players/items/배열형은 그대로.
//   ※ m.n(전 회차 개수)은 옛 잣대로 적혀 있어 그대로 두면 가짜 보류가 뜬다 — 한 번만 비운다(ps_count_scale=v2).
// 1.592: **자동 백업(스냅샷) 추가** — 파일 없이도 며칠 전으로 돌아갈 자리를 만든다. 설정 → 자동 백업.
//   지금 백업은 **사람이 눌러야** 생긴다(설정 → 내보내기). 7일 지나면 '백업 권장' 칩이 뜨지만,
//   그걸 안 누른 상태에서 사고가 나면 돌아갈 자리가 없다 — 08-05 가 그랬다.
//   되돌리기(ps_rescue_*)는 **직전 한 판만** 잡아 두므로 며칠 전으로는 못 간다. 그 사이를 메운다.
//   하루 한 번(앱 연 뒤 8초, 첫 화면을 늦추지 않게) 이 기기 안에 한 판을 통째로 뜨고 최근 3개를 굴린다.
//   되돌릴 때는 **되돌리기 직전 상태를 먼저 한 판 뜬다** — 돌아올 자리가 없는 복구는 또 다른 사고다.
//   **파일 백업을 대신하지 않는다**: 브라우저 저장소가 통째로 비면 이것도 같이 사라진다.
//   그건 파일 내보내기만 막을 수 있어 '백업 권장' 칩은 그대로 뒀다. 이건 훨씬 흔한 쪽
//   (동기화가 덮음 · 실수로 지움)을 위한 바닥이다.
//   검증: 34명 스냅샷 → 1명으로 망가뜨림 → 되돌려 34명 복구 · 선수단 47명 유지 · 직전 상태도 함께 보존.
// 1.591: **'자료 확인' 한 화면으로 합친다**(사용자 지적: "다른 기기와 부딪힌 자료 이런 것들이 헷갈려
//   어떻게 해야 할지 모르겠어"). 설정 → 자료 확인.
//   지금까지 사용자는 네 가지 말을 구별해야 했다 — '동기화 대기' '팀에 올리지 않고 멈춘 변경'
//   '동기화로 덮인 자료' '충돌'. **이건 앱의 내부 사정이지 사용자의 질문이 아니다.**
//   어느 경우든 사용자에게 질문은 하나다: "이 자료가 여기랑 팀에서 다른데 어느 쪽을 남길까?"
//   그래서 세 갈래를 한 목록으로 모으고 «이 기기 것 / 팀 것» 두 버튼만 남겼다.
//   갈래마다 '이 기기 것'의 실제 뜻이 다른데(보류=아직 안 올라감, 덮임=이미 덮인 뒤, 충돌=이미 이 기기가 이김)
//   그 차이는 dataReviewApply 가 흡수한다. '대기'는 선택이 아니라 진행 상태라 넣지 않았다.
//   만들면서 세 가지가 더 나왔다:
//   ① **답한 질문이 다시 나오는 루프.** '팀 것'을 고르면 로컬을 덮는데, 그 덮어쓰기를 안전망이
//      "당신 것이 덮였습니다"로 기록해 같은 항목이 '덮인 자료'라는 다른 이름으로 되살아났다(실측).
//      사용자가 의도해서 고른 덮어쓰기이므로 흔적을 남기지 않는다(사고로 덮인 경우의 안전망은 그대로).
//   ② **conflictRestore 가 IndexedDB 쓰기를 안 기다렸다.** 동기 함수라 kvWrite 가 건 쓰기가 끝나기 전에
//      true 를 돌려주고 목록에서 지웠다. localStorage 키만 있을 땐 안 드러났는데 1.590 에서 IDBK 에
//      네 개를 넣자 일정·경기·권한·후보가 전부 이 경로를 타게 됐다 — 내가 만든 부작용이다.
//      1.589 의 rescueRestore 와 같은 병이라 같은 처방을 썼다(되읽어 확인한 뒤에만 정리, 실패 시 보존).
//   ③ 설정의 '자료 확인' 줄은 건수가 있을 때만 빨갛게 알린다. 없으면 "이 기기와 팀이 같습니다".
//   검증: 보류·덮임·충돌 셋이 한 목록에 모임 / 각 선택이 올바른 내부 동작으로 갈라짐 /
//        쓰기 실패 시 false 를 주고 목록·백업 보존 / '팀 것' 후 같은 항목이 되살아나지 않음.
// 1.590: **같은 사고가 다시 나지 않게 — 재발 방지 셋.** 1.589 는 '복구가 되게' 했고, 이번은 '안 나게'다.
//   ① **IDB 키 목록을 손으로 유지하지 않는다.** IDBK 는 "이 키는 IndexedDB 에 산다"를 사람이 적어 둔
//      목록이었고, 앱이 새 키를 IDB 로 옮길 때 여기 적는 걸 잊으면 동기화가 엉뚱한 저장소를 읽고 썼다.
//      1.501(매치데스크)·1.504(노트)·1.531(경기)·1.589(후보 외 3개) — 같은 이유로 네 번 사고가 났다.
//      **목록을 고치는 것으로는 다음 번을 못 막는다.** 이제 실제 IndexedDB 키를 읽어 합치고(1분 캐시),
//      정본에 없던 키가 나오면 진단에 남긴다. IDBK 는 '아직 안 만들어진 키'용 바닥으로만 남는다.
//   ② **올린 기록을 남긴다(ps_push_log_v1).** 08-05 사고에서 복구는 했지만 언제 어느 기기에서
//      1명짜리가 올라갔는지 끝내 추적하지 못했다 — 서버엔 마지막 값만 남고 누가 썼는지는 안 남기 때문이다.
//      이제 올릴 때마다 시각·기기·이름·키별 개수를 이 기기에 남긴다(최근 60건). 값은 안 담는다.
//   ③ **1.573 보호가 뚫려 있던 자리를 막았다.** pushHold 는 push 지점 11곳 중 4곳만 지키고 있었고,
//      그중 "서버에 이 키의 행이 없다"(loc!=null && !row)는 경로가 **조건 없이** 올리고 있었다.
//      행이 없는 건 처음 올릴 때만이 아니다 — 그 회차 조회가 이 키를 못 받았거나 공간을 막 바꾼 직후일 수도 있다.
//      그때 로컬이 반쯤 비어 있으면 **그 빈 값이 서버 정본이 되고** 다음 회차에 모든 기기를 덮는다.
//      08-05 의 34명 → 1명이 정확히 이 모양이다. 이제 기억해 둔 개수와 견줘 막는다.
//      실측: 34→1 막힘 · 34→28 막고 확인요청 · 34→33 통과 · 첫 등록(기억 없음) 통과.
// 1.589: **되돌리기가 조용히 실패하던 것을 고친다 — 2026-08-05 스카우팅 후보 34명 → 1명 사고의 진짜 원인.**
//   사고 경위: 08-05 23:35 동기화가 **서버에 있던 1명짜리 값을 내려받아** 로컬 34명을 덮었다.
//   지운 게 아니라 받아온 것이다(같은 순간 cs_perms_v1·cs_team_matches_v1 도 같은 경로를 탔다).
//   그런데 되돌리기(rescueRestore)를 눌러도 복구가 안 됐다 — 이유가 둘이었다.
//   ① **IDBK 목록에 네 개가 빠져 있었다**: cs_scout_targets_v1 · cs_team_matches_v1 · cs_perms_v1 ·
//      process_coach_v1. 이 목록에 없으면 kvWrite 가 localStorage 쪽에 쓰는데 앱은 IndexedDB 를 읽는다.
//      그래서 (가) 서버에서 받은 값이 화면에 반영되지 않고 (나) 되돌리기도 엉뚱한 곳에 써서 화면은 그대로이며
//      (다) storage.get 은 IDB 가 비면 localStorage 값을 끌어와 IDB 에 심으므로 잘못된 값이 앱까지 번진다.
//      실제 기기의 IndexedDB 키 목록과 KEYS 를 대조해 찾았다. 이제 13개로 맞다.
//   ② **rescueRestore 가 결과를 확인하지 않고 백업을 지웠다.** kvWrite 가 true 만 주면 성공으로 보고
//      ps_rescue_ 원본을 삭제했다 — 복구는 안 되고 백업만 사라진다. 이제 **앱이 실제로 읽는 자리에서
//      되읽어 확인한 뒤에만** 지운다. 확인에 실패하면 false 를 돌려주고 백업을 남긴다.
//   ③ ②를 고치다 하나 더 나왔다: 실패 시 백업을 '남겨도' 내용이 이미 망가져 있었다.
//      kvWrite 안의 rescueStash 가 **되돌리려던 그 백업을 지금 값(1명)으로 덮어쓰기** 때문이다.
//      그래서 확인 실패 시 원본을 백업 자리에 다시 써 넣는다. 검증: 쓰기 실패를 흉내내도 백업 34명 보존 →
//      재시도하면 34명 복구. (이 셋이 다 맞물려 있어서 하나만 고치면 여전히 못 살린다)
// 1.588: **설정에 '동기화 · 지금 올리기' 추가**(사용자 요청: 작업물을 버튼 한 번으로 전부에게).
//   먼저 확인한 것 — 동기화 자체는 **이미 있었다**: 3분마다(interval) · 탭을 벗어날 때(hide) · 부팅 시 ·
//   실패 시 재시도, 그리고 계정 팝오버에 수동 버튼도 있다. 없던 것은 셋이다.
//   ① 설정에 누를 자리가 없다(홈 화면 설치 상태면 더 찾기 어렵다)
//   ② 기존 버튼 이름이 '팀 자료 새로고침'이라 **받아오기**처럼 읽힌다 — 사용자가 원한 건 올리기다
//   ③ 눌러도 올라갔는지 아닌지 말해 주지 않는다
//   그래서 엔진(PSSync.syncNow)은 그대로 두고 위 셋만 채웠다. 상태줄이 '올릴 것 N건 / 보류 N건 /
//   팀과 최신 상태입니다' 를 보여 주고, 누르면 결과를 말한다(올렸습니다 ✓ / 이미 최신 / 못 올렸습니다).
//   **강제 덮어쓰기가 아니다.** 이 자리는 조용히 밀어붙이면 남의 작업이 사라질 수 있는 곳이라,
//   pushHold(항목이 5개 이상 또는 절반 이하로 줄면 올리기를 막는 보호)를 우회하지 않는다 —
//   대신 막힌 게 있으면 감추지 않고 '보류 N건'으로 띄우고, 눌러서 확인하도록 안내한다.
//   검증: 로그아웃(버튼 비활성·안내문) / 성공 / 보류 / 네트워크 실패 / 이미 최신 다섯 갈래를 각각 확인했고,
//   핸들러가 localStorage 를 직접 건드리거나 승인 키(ps_push_ok_*)를 손대지 않는 것도 확인했다.
// 1.587: **설정에 '최신으로 새로고침' 추가**(사용자 요청). 테마 아래·build 태그 위.
//   왜 필요한가: ① 홈 화면에 설치해 쓰면 주소창이 없어 새로고침할 방법이 아예 없다.
//   ② 더 근본적으로, 이 앱은 화면 파일을 **캐시 우선**으로 연다(아래 fetch 핸들러) — 새 버전을 올려도
//   앱을 완전히 껐다 켜기 전까지는 옛 화면이 그대로 남는다. 실제로 확인했다: 서버 파일을 바꾼 뒤
//   **일반 새로고침을 해도 옛 빌드가 그대로**였고, 이 버튼을 눌렀을 때만 새 빌드를 받아왔다.
//   무엇을 지우나: 서비스워커 등록 + 캐시 저장소(화면 파일 사본)뿐이다.
//   **localStorage(선수단·일정·평가·작전판 등 모든 기록)와 로그인 세션은 건드리지 않는다** —
//   캐시는 서버에서 다시 받으면 그만이지만 기록은 이 기기에만 있을 수 있기 때문이다.
//   실측: 기록 11개 키 전부 보존 · 빌드 태그가 새 값으로 갱신 · 서비스워커는 다음 로드에서 자동 재등록.
//   캐시 정리가 늦어져도 3초 뒤에는 그냥 다시 연다(재로드 자체가 사용자가 기대한 동작이므로).
// 1.586: **스카우트 보드 칩을 한 줄로 되돌린다 — 팀 이름 / 등번호 / 이름 / 평가**(사용자 지시).
//   1.585 에서 팀 이름이 잘리는 걸 막으려고 윗줄로 올렸는데, 팀 이름이 비어 있어도 한 줄을 통째로 차지해
//   이름만 있는 칩까지 두 줄로 커 보였다. 다시 한 줄로 놓되 잘리지 않게 만드는 과정에서 세 번 고쳤다:
//   ① 팀 이름을 max-content 로 → 팀 이름은 다 나왔지만 이번엔 **이름이 19~28px 로 짜부라져** 잘렸다.
//      이름이 이 칩의 주인공이라 더 나쁜 교환이다.
//   ② 이름에 바닥(64px)을 깔았더니 팀 이름이 **한 글자로**(소…/수…/울…) 잘리고 평가 칩이 아랫줄로 밀렸다.
//      산술이 안 맞았다: 180px − 여백16 − 칸사이15 − 등번호20 − 평가18 = 111px, 이름 64 를 빼면 팀 이름은 47px 뿐인데
//      '수원삼성블루윙즈'는 9.5px 로 약 76px 이 필요하다. **폭을 늘려야 풀리는 문제**였다.
//   ③ 슬롯을 180 → 232px. 넓히면 카드가 겹칠까 걱정했으나 실측 겹침 0쌍.
//   그리고 두 줄 배치를 되돌리며 영역 이름을 없앴는데 `.gr{grid-area:grade}` 한 줄이 남아 **없는 영역**을
//   가리켰고, 그러면 자동 배치로 평가 칩만 아랫줄에 떨어진다 — 이것이 ②의 '평가 칩이 밀린' 진짜 원인이었다.
//   실측: 팀 이름 잘림 0 · 이름 잘림 0 · 전부 한 줄 · 칩 높이 26px(두 줄일 때 48px) · 슬롯 겹침 0쌍.
//   ※ 잘림 판정을 scrollWidth 로 하면 **빈 칸까지 '잘림'으로 나온다**(contenteditable 은 캐럿·패딩 때문에
//     scrollWidth 가 항상 크다). Range 로 실제 글자 폭을 재야 한다.
// 1.585: **선수용 IDP 모바일 다듬기 · 다크 대비 · 스카우트 칩 소속팀 · 미배치 후보 풀 제거**(사용자 지시).
//   먼저 정정 — 1.584 작업 중 "IDP 탭 타깃이 36px, 평가 16개·프로필 18개"라고 봤던 건 **코치로 본 IDP** 였다.
//   실제 선수 화면(body.ps-player-role)에는 전용 레이아웃이 이미 있어(하단 4탭 고정 · .ev-dots 44px · 입력 44px)
//   44px 미만이 1개뿐이었다. '학습' 탭의 선수/코치 관점 토글도 coach 조건이라 선수에겐 아예 안 보인다.
//   그래서 이번엔 **선수 화면에서 실제로 남아 있던 것**만 고쳤다.
//   ① 일정 탭 — 날짜를 눌러 그날을 기록하는 화면인데 정작 누를 대상의 라벨이 제일 작았다:
//      날짜 11px · 요일 10px(이 탭 글자의 89%가 12px 미만). 날짜 15px · 요일 12px 로 올리고,
//      년간·월간·주간·일간과 ‹오늘› 을 44px 로. 실측 12px 미만 89% → 11%.
//   ② 강도(RPE) 라벨이 두 줄로 접혀 1·5번 칸만 높아 보이던 것 — 또 `font:600 10px/1.25 inherit` 이었다.
//      축약형 글꼴 자리의 inherit 은 쓸 수 없는 키워드라 선언 전체가 버려지고 기본값 16px 로 그려진다.
//      낱개 속성으로 고쳤다(1.584 에 적은 106곳 중 idp 2곳 처리, 104곳 남음).
//   ③ `--text-1` 이 2곳에서 쓰이는데 **정의가 없었다** — 강도 숫자·평가 진행수가 상속색으로 떨어지고 있었다.
//      라이트/다크 양쪽에 정의.
//   ④ 평가 요약 줄이 «0/15» 와 «남은 곳 …» 사이에 간격이 없어 "15남은" 으로 읽혔다 → 간격+가운뎃점.
//   ⑤ 다크 대비 39%(28/73) → 4%(3/73). 원인이 셋이었다:
//      (가) --ps-premium-text·--ps-premium-violet·#707783 같은 **라이트 전용 고정색에 다크 짝이 없음**
//           (로고 1.09:1 · 내비 3.59:1 · 활성 탭 2.72:1)
//      (나) .ps-page-idp 는 <html> 에, fmdark 는 <body> 에 붙는다 — `body.fmdark .ps-page-idp …` 는
//           부모·자식이 뒤바뀐 선택자라 **구조상 절대 안 맞는다.** `.ps-page-idp body.fmdark …` 만 유효하다.
//      (다) .hm-tile 이 <button> 인데 색 지정이 없어 UA 기본값(buttontext=검정)을 썼다.
//           버튼은 글자색을 상속하지 않는다 — 라이트에선 흰 카드 위 검정이라 아무도 몰랐고,
//           다크에서 #1A212B 위 검정 = 1.3:1 로 평가·개인 훈련·이미지노트·학습 네 칸 제목이 통째로 안 보였다.
//      남은 3건: 활성 탭 4.09:1 · 보라 CTA 의 흰 글자 3.13:1(강조색 자체 대비라 색 결정이 필요).
//   ⑥ 스카우트 보드 칩의 소속팀이 '울산...' 으로 잘리던 것 — 원인이 둘이었다.
//      1.584 에서 상태 칩을 빼면서 그리드의 마지막 18px 칸이 **죽은 채로 남아** 소속팀 몫을 갉아먹었고,
//      남은 폭을 소속팀 1fr : 이름 1.1fr 로 나누니 180px 슬롯에서 소속팀은 약 40px 뿐이었다(필요 57px).
//      소속팀을 윗줄 전체로 올린다. 1.581 의 두 줄 시도는 flex 라 칸이 제 폭을 못 받아 한 글자씩 깨졌는데,
//      grid-template-areas 로 행을 명시하면 그 문제가 없다. 실측: 잘림 0 · 칩 높이 42px 균일 · 슬롯 겹침 0쌍
//      (1.581 이 우려한 카드 겹침 부작용은 나타나지 않았다).
//   ⑦ '미배치 · 스카우트 후보' 풀 제거(사용자 지시) — 보드 빈 자리마다 자체 '＋ 선수'가 있고 후보는 아래
//      목록에 전부 있어, 같은 사람을 한 화면에서 두 번 보여 주던 자리였다. 참조하던 JS 에 널 가드를 넣었다
//      (없는 요소에 쓰면 예외가 나고 그 아래 sbWire()·sbClamp() 까지 멈춰 보드가 안 그려진다).
// 1.584: **폰 하단 탭바 정리 · 명단 1열 복귀 · 스카우트 상태 4단계 · 이름 모달 무한 반복 수정**(사용자 지시).
//   ① 하단 탭바 — 원인이 둘이었다. (가) premium-ui.css 의 데스크톱 알약 스타일에 미디어쿼리가 없어 폰 탭바까지 덮었다.
//      `.ps-page-app .seg button.on`(0,3,1)이 모바일 규칙(0,2,1)을 특이도로 이기고 파일 순서도 뒤라 두 번 이겨서,
//      모바일이 지우려던 그림자가 살아남아 '배경 없이 그림자만 뜬 흰 카드'가 됐다 → 데스크톱(≥601px)으로 가뒀다.
//      가두자마자 활성색이 회색으로 죽었는데, 같은 파일 max-width:767px 블록의 `.ps-page-app .seg button` 이
//      활성색을 눌러서였다 — 활성색을 그 블록에 같이 넣었다. (나) 팀·IDP·노트만 아이콘이 없어(나중에 추가되며 라벨만)
//      그 셋의 라벨이 12px 위로 떠 한 줄에 기준선이 둘이었다(실측 y=818 vs 830) → 같은 문법의 아이콘을 채웠다.
//      (다) grid-auto-columns:1fr 은 minmax(auto,1fr) 이라 글자가 긴 탭이 폭을 더 가져갔다(커뮤니티 63px 대 52px)
//      → minmax(0,1fr) 로 일곱 칸을 정확히 같게. 실측 52.1px 동일·기준선 일치·그림자 없음.
//   ② 선수 명단 — 1.583 에서 넓은 화면만 여러 열로 폈던 것을 되돌린다. 열이 360px 로 좁아지면 행 안의 이름 칸이
//      짜부라져 **이름이 한 글자만 보였다**(박예준→"브"). 명단에서 이름이 안 보이면 명단이 아니다.
//   ③ 스카우트 후보 상태를 추천 → 관찰중 → 영입대상 → 확정 넷으로. '보류'는 진행이 아니라 멈춤이라 같은 줄에서
//      순환시키면 단계가 앞뒤로 튀었다. 보류로 적어 둔 후보는 중립인 관찰중으로 읽는다(기본값 추천으로 떨어뜨리면
//      멈춰 둔 후보에 없던 판단이 생긴다). 보드 칩의 중복 상태 표시(1.564)는 뗐다 — 상태는 후보 목록에 그대로 있다.
//   ④ 상태 칩이 두 줄로 접혀 타원이 되던 진짜 이유: `font:800 10px/1 inherit` — 축약형 글꼴 자리의 inherit 은
//      쓸 수 없는 키워드라 **선언 전체가 버려지고** 버튼 기본값 16px 로 그려지고 있었다. 낱개 속성으로 고쳤다.
//      ※ 같은 패턴이 앱 전체에 106곳 더 있다(scout 70·process 13·board 8·gamemodel 7·analysis 3·app 3·idp 2).
//         전부 지정한 크기가 무시되는 중 — 아직 안 고쳤다. 찾기: grep -o "font: *[0-9][^;}]*inherit" *.html *.css
//   ⑤ '팀에서 쓸 이름' 모달이 이름을 넣어도 계속 뜨던 버그: setItem 실패를 catch(_){} 로 삼키고도 '저장됨 ✓'
//      토스트를 띄워서, 저장이 안 된 채 renderUI() 마다 30초 가드만 지나면 같은 모달이 영원히 다시 떴다(역할 무관).
//      이제 쓴 뒤 다시 읽어 확인하고, 실패하면 같은 질문 대신 이유와 할 일을 말하고 멈춘다. 닫기('나중에')도 열었다 —
//      이름 없이도 앱은 돌아가고, 못 닫는 창은 저장이 실패하면 그대로 덫이 된다.
// 1.583: **버전을 이 파일 한 곳에만 적는다.** 지금까지 버전은 sw.js 의 CACHE, app.html 하단 build 태그, iframe 주소의 ?v= — 열 곳에 **따로 손으로** 적혀 있었고 실제로 어긋나 있었다(terms·idp 369 · community 362 · analysis 277 · learning 375 — 앱은 1.582였다). 먼저 오해부터 정리하면, 이 어긋남이 옛 코드를 내보내진 **않았다**: 무효화는 캐시 **이름**(process-x.y)이 바뀔 때 다른 이름의 캐시를 통째로 버리는 방식이고, 프리캐시는 경로로 저장하며 cacheFirst 가 ?v= 로 미스나면 경로로 다시 맞춘다. 즉 그 ?v= 들은 아무 일도 안 하면서 "이 파일은 369다"라고 거짓말만 하고 있었다. **문제는 반대쪽이었다** — HTML 이 cache-first 이고 재검증이 없어서, 이 CACHE 한 줄을 안 올리고 배포하면 사용자는 옛 화면에 **영구히** 묶인다. 살아 있는 유일한 스위치가 손으로 적는 값 열 개 중 하나였던 셈이고, 나머지 아홉이 미끄러졌다는 건 이 하나도 미끄러질 수 있다는 뜻이다. 그래서 app.html 에 `window.PS_BUILD` 한 줄만 두고 build 태그·?v= 를 전부 거기서 만든다. 배포ZIP만들기.command 가 이 파일에서 버전을 읽어 PS_BUILD 에 도장을 찍고, ① 손으로 박힌 ?v=숫자 ② 하드코딩된 build 태그가 남아 있으면 **ZIP 을 만들지 않고 멈춘다**. scout.html 의 team-ui-v375.css 스탬프(1.473)도 뗐다 — 옆의 두 CSS 는 원래 스탬프가 없었고 셋 다 CORE 에 경로로 프리캐시되므로 처음부터 무의미했다(실제 파일은 1.577 스케일 통합본인데 1.473 이라 적혀 있었다).
// 1.582: **선수 화면을 좌우 여백 없이 화면 끝까지**(사용자 지시). 여백이 두 겹이었다 — .wrap 의 20px 과 #teamView>.card 의 20px 이 겹쳐 양쪽 40px 씩 먹고 있었다. 둘 다 걷고 카드의 옆 테두리·라운드도 지웠다(가장자리까지 간 판에 세로선이 남으면 잘린 것처럼 보인다). 다만 **글줄은 가장자리에 붙으면 못 읽으므로** 머리글(.tm-head)과 명단(.tm-split)에는 안쪽 여백을 되돌려 준다 — 끝까지 가는 건 판이고, 글은 읽을 자리를 지킨다(폰에서는 12px). 실측: 운동장 1280px 폭에 좌우 여백 0 · 가로 스크롤 없음. ※ 카드 패딩은 뒤쪽에 같은 요소를 다시 잡는 규칙이 있어 !important 로 눌렀다.
// 1.581: **스카우팅 후보 목록의 골격을 선수 목록에 맞췄다**(사용자 지시) — 선수 목록은 «굵은 이름 + 흐린 숫자» 아래 2px 밑줄로 묶음을 끊는데(.tm-col-h), 스카우팅만 흐린 잔글씨라 같은 '포지션별 묶음'인데 한쪽은 제목이고 한쪽은 주석처럼 보였다. 크기·굵기·자간·밑줄을 실측으로 일치시켰다(12px/800/0.6px/2px). 숫자는 자릿수 정렬. **그리고 1.580 의 두 줄 칩을 되돌린다** — 카드 안에 소속팀까지 다 보이게 하려고 칩을 두 줄로 늘렸는데 부작용이 둘이었다: ① 카드가 높아져 보드에서 3쌍이 겹쳤고(운동장을 640px 로 늘려도 3쌍) ② 소속팀이 한 글자씩 세로로 깨졌다(대/구/U/1/8 — flex 항목이 제 폭을 못 받은 상태에서 word-break 가 걸렸다). width:100% 를 명시해도 18px 만 받아 해결되지 않았다. **폭 180px 안에서 여덟 값을 다 펴는 건 이 방식으로는 안 된다**는 결론이라, 깨진 화면을 남기지 않도록 안정된 한 줄로 되돌렸다(겹침 0 · 운동장 520 복귀). 소속팀 전체 이름은 아래 «스카우트 후보» 표에서 그대로 보인다. 카드 안까지 다 보이게 하려면 다른 방법이 필요하다 — 카드 폭을 키우거나(두 보드가 다시 어긋난다), 팀명 약칭을 쓰거나, 카드에 띄울 항목을 고르게 하거나.
// 1.580: **'영입완료'를 없애고 '확정' 하나로 · 카드 정보를 하나도 숨기지 않는다**(사용자 지시). ① 후보 상태가 6단계였는데 **확정(done)과 영입완료(signed)가 같은 뜻**이라 코치가 어느 걸 눌러야 할지 알 수 없었다 — signed 를 없애고 5단계로. 이미 '영입완료'로 적어 둔 후보는 읽을 때 확정으로 넘겨 하나도 잃지 않는다. ② 스카우팅 칩이 소속팀·이름을 말줄임하고 있었다('신…' '김…'). 1.554 가 원래 두 줄로 뒀던 것을 1.564 가 한 줄+212px 로 바꿨고, 1.579 에서 선수 보드와 폭을 맞추려 180px 로 줄이자 잘림이 다시 나왔다 — **내가 만든 회귀다.** 폭을 도로 넓히면 두 보드가 또 어긋나므로 줄을 늘려 해결한다: 위=등번호·이름·상태·평가, 아래=소속팀. 어느 칸도 말줄임하지 않는다(양쪽 보드 잘린 칸 0 확인). ③ 스카우팅 카드 헤더에 인원수를 되살렸다 — 선수 보드는 보여 주는데 스카우팅만 display:none 으로 숨겨 두었다. 표기도 숫자만으로 맞췄다. ※ **미해결**: 칩이 두 줄이 되며 카드가 높아져 스카우팅에서 카드 3쌍이 겹친다(운동장을 640px 로 늘려 7→3 까지 줄였다). 포지션 좌표를 벌리거나 한 자리에 보일 후보 수를 정하는 판단이 필요하다.
// 1.579: **선수·스카우팅을 같은 화면처럼 · 장비를 휠로 돌린다.** ① **두 운동장을 맞췄다**(사용자 지시) — 같은 4-3-3 판인데 카드가 150 vs 212px, 높이가 610 vs 662px 로 달라 다른 앱처럼 보였다. 이제 카드 **둘 다 180px**, 높이 **둘 다 520px**. ※ 1.576 에서 "스카우팅 칩은 열이 하나 더 많아 좁히면 잘린다"며 212 를 유지했는데 **그 판단이 틀렸다** — 소속팀 칸은 212px 에서도 이미 말줄임으로 잘리고 있었고(원래 그렇게 설계된 칸), 180 으로 줄여도 잘리는 칸 수는 3개로 똑같다. 높이 660 도 1.566 에서 "카드가 아래로 넘쳐" 올린 값인데, 그 원인이던 2줄 빈 카드를 1.576 에서 1줄로 줄였으므로 근거가 사라졌다. 실측: 카드 11개 겹침 0 · 운동장 밖 0(선수 보드는 좌표가 촘촘해 190px 부터 겹치기 시작하므로 180 이 상한이다). ② **휠로 회전**(사용자 요청) — 골대·콘을 한 바퀴 돌리려면 15° 버튼을 24번 눌러야 했다. 이제 고른 상태에서 휠을 굴리면 돌아간다: 마우스 한 칸(deltaY≈100)이 버튼과 같은 **15°**, 트랙패드는 잘게 굴러 **미세 조정**(deltaY 8 → 1.2°), **Shift 는 45° 스냅**(90·180 을 정확히 맞출 때), **ctrl+휠은 브라우저 확대라 건드리지 않고**, **아무것도 안 골랐으면 평소처럼 화면이 스크롤된다**. 시야·쉐이퍼를 켠 선수도 같은 방식으로 방향을 돌린다. ③ **장비 회전이 저장되지 않던 버그** — rotateSel 이 선수 분기에서만 boardSaveLive 를 불렀다. 버튼으로 15°씩 돌릴 땐 잘 안 드러났지만 휠로 쉽게 돌리게 되면 바로 티가 난다. 소수점이 쌓이지 않게 0.1° 로 정리해 저장한다. ④ **닫기(✕) 아이콘 24곳이 안 그려지고 있었다** — `y2=11/>` 처럼 따옴표 없는 속성 뒤에 슬래시가 붙어 값이 `11/` 로 파싱됐다(선 두 개가 안 그려져 빈 네모). 닫기 버튼 7종(명단·화이트보드·애니메이션·실행·보관함·세션·선수단)이 전부 해당. 따옴표를 넣으면 JS 문자열 안에서 문자열이 끊기므로 **슬래시 앞을 띄우는** 방식으로 고쳤다 — 원래 따옴표가 있던 62곳은 건드리지 않았다.
// 1.578: **값싸 보이던 두 가지를 걷어냈다 — 문자 기호와 낮은 대비.** ① **글자를 아이콘처럼 쓰던 버튼을 전부 라인 SVG 로.** `▲ ▼ ✕ ▸ ↺ ‹ › ⠿` 가 버튼 노릇을 하고 있었는데, 이건 취향 문제가 아니라 **제품 자체 규칙 위반**이다 — gamemodel.html 주석이 이미 "이모지 금지(라인 SVG)"라고 못박아 두었고, 앱은 이미 `viewBox="0 0 24 24" stroke-width="2"` 라인 아이콘을 55개 쓰고 있었다. 새 세트를 고를 필요도 없이 **쓰던 규격에 맞추기만** 하면 됐다. 특히 게임모델은 SVG 가 **0개**이고 국면 행 컨트롤이 전부 글자였다 — 이 화면이 제일 싸 보이던 이유다(0 → 80개). 라벨은 title·aria-label 로 남겨 스크린리더에는 그대로 들리고, SVG 에 pointer-events:none 을 줘 끌기 로직이 핸들을 놓치지 않게 했다. 결과: 팀 탭 7개 전부 **문자 기호 버튼 0개**. ② **본문 대비가 WCAG AA 미달이었다.** `--text-3`(#767B85)은 흰 카드 위 **4.25**, 회색 배경 위 **3.63** 으로 기준(4.5)을 못 넘겼는데, 하필 캡션·라벨·플레이스홀더·보조 설명이 전부 이 토큰을 쓴다. 외부 리뷰의 "낮은 대비"는 인상이 아니라 **측정되는 결함**이었다 → #656A74(5.43 / 4.64). 다크 모드도 카드 위 4.40 이라 미달이어서 #7C8696 → #8A94A6(5.30). 27곳. ③ **드래그 핸들이 사실상 안 보였다** — `⠿` 색이 #c3c9d4 로 흰 카드 위 대비 **1.66:1**. 끌 수 있다는 유일한 신호인데 신호가 없던 셈이다. SVG 그립으로 바꾸고 #8A919E(3.17, UI 요소 기준 3:1 통과)로. ※ 색 토큰(--text-*)은 아직 페이지마다 따로 정의돼 있다 — --fs-* 처럼 한 곳으로 모으는 건 다음 판 몫.
// 1.577: **위계를 만든다 — 타이포 스케일 재조정.** 1.574~1.576 에서 한 일은 전부 '같은 것을 같게'(통일)였는데, 통일이 곧 위계는 아니었다. 옛 스케일은 열 단계 중 **다섯(10·11·12·13·14)이 4px 안에** 몰려 있었고, 특히 **본문 13 과 카드 제목 14 가 1px 차이**라 카드 제목이 제목으로 안 읽혔다. 그래서 화면 전체가 '한 덩어리'로 보였다(외부 리뷰: "제목·섹션명·보조 설명·컨트롤 라벨 사이의 크기 차이가 너무 작다"). **고친 방식은 '아래는 두고 위를 벌린다'** — 본문을 크게 키우면 열이 많은 화면(스카우팅 후보·주간 격자 7열·선수 명단)이 넘치므로, 본문은 한 단계만 올리고 카드 제목부터 위로 간격을 크게 줬다. 본문→카드제목이 1px 에서 2~3px 로, 카드제목→섹션제목이 4px 로 벌어진다. **화면폭별로 두 벌을 둔다** — 좁은 화면은 밀도가 곧 쓸모라(사이드라인의 폰) 지금 크기를 지키고, 넓은 화면은 여백이 남아 글자가 작으면 '축소된 웹페이지'처럼 보이므로 위쪽을 더 키운다. 폰: 본문 13·카드제목 15·섹션 19·화면제목 22·큰숫자 34. 넓은 화면(≥768px): 본문 14·카드제목 17·섹션 21·화면제목 26·큰숫자 40. --fs-input 은 두 벌 다 16px 로 고정 — 이보다 작으면 iOS 가 입력할 때 화면을 확대한다. 토큰 이름은 하나도 안 바뀌므로 값만 여기서 고치면 전 화면이 함께 움직인다(1.574 에서 정의처를 premium-ui.css 한 곳으로 합쳐 둔 덕이다). **검증**: 선수 14명·후보 5명(긴 이름·긴 소속팀 포함)을 실제로 넣고 7개 탭 × 데스크톱 1280 · 폰 375 에서 재서, 화면 밖으로 잘리는 실제 내용 **0개**·문서 가로 스크롤 **0개** 확인.
// 1.576: **남은 불일치를 정리했다.** ① **글자 크기가 이제 스케일 그대로다** — 7개 탭 어디에도 v286 열 단계(10·11·12·13·14·16·18·20·24·32) 밖의 값이 없다. 남아 있던 15px·30px 을 토큰으로 옮겼다: 오늘 인원 카드의 큰 숫자(30→--fs-num-lg), 카드 제목·주간 화살표·평가 수치(15→--fs-title). `.ev-name`·`.es-name` 은 **이미 토큰으로 옮겨 놓고도** 아래쪽 낡은 중복 규칙이 30px 로 덮고 있었다(중복 제거). 그리고 팝업 입력칸이 15px 이라 **iOS 에서 입력할 때마다 화면이 확대**되고 있었다 — 토큰 주석이 경고하던 바로 그 경우다(--fs-input 16px). ② **일정 격자에서 같은 말을 두 번 하지 않는다** — 왼쪽 라벨이 '미팅'인 행의 일곱 칸이 전부 '＋ 미팅'이었다. 일정·주제·강도 행은 이미 '＋'만 쓰고 있었으므로 미팅·웜업·훈련·보관함도 거기 맞췄다(글자 28개가 사라졌다). 이름은 title·aria-label 로 남겨 스크린리더와 툴팁에는 그대로 들린다. ③ **두 운동장을 같은 결로** — 스카우팅은 빈 자리마다 점선 상자가 **둘**이었다('비어 있음' + '＋ 선수'). '＋ 선수'가 이미 같은 말을 하므로 위 상자를 뺐다(11자리 × 2 = 22개 → 11개). 선수 탭 카드는 폭이 104~150px 사이에서 **이름 길이에 따라 제각각**이라 같은 보드 위에서 카드끼리 어긋났다 — 150px 로 고정. ※ 두 보드의 카드 폭(150 vs 212)은 **일부러 다르게 둔다** — 스카우팅 칩은 열이 하나 더 많다(출신·번호·이름·상태·평가, 1.564). 억지로 맞추면 칩이 다시 잘린다. ④ **IDP 보라는 고치지 않는다** — UI-가이드.md v147 의 '주색은 영역으로 갈린다(팀 도구=파랑, 개인 성장 영역=보라)' 가 그대로 지켜지고 있고, 세그 모양(둥글기 10px)도 앱·팀 탭과 이미 같다. 색이 의미를 나르는 자리라 통일 대상이 아니다.
// 1.575: **페이지 제목 규칙을 하나로 통일했다.** 규칙: **탭 내비가 이미 화면 이름을 말하므로, 페이지는 그 이름을 한 번 더 적지 않는다.** 이건 새로 정한 게 아니라 이미 있던 규약이다 — 통합 헤더가 `.apphd-name{display:none!important}` 로 제목 행을 꺼 두고 scout·process·gamemodel·terms 가 그렇게 쓴다. 그런데 **경기(h2 '경기 분석')·스카우팅(span '스카우팅')·IDP(h1 'IDP')** 만 각자 따로 만든 마크업이라 그 규약을 비켜 갔고, 그래서 7개 탭 중 제목이 있는 탭·없는 탭이 섞이고 태그도 h1/h2/span 으로 제각각이었다(크기도 24/16/20px). 이제 셋 다 `.ps-pagetitle` 로 통일한다. **DOM 에서 지우지 않고 눈에만 안 보이게** 한다 — 제목은 문서 구조이자 스크린리더의 길잡이라서, 지우면 화면 이름을 소리로 확인할 길이 사라진다. 단독 실행(셸 밖)에서는 이름을 말해 줄 내비가 없으므로 **그대로 보인다**(head 에서 data-shell 을 첫 페인트 전에 정한다 — 나중에 정하면 제목이 번쩍한다). 화면의 눈에 보이는 이름표는 '설명 한 줄'이 맡고, 이것도 `.ps-pagedesc` 한 토큰으로 통일했다. 곁들여: 스카우팅 설명이 늘 "…우리 선수단의 포지션 기…"로 잘리던 것 — 상한이 `34ch` 였는데 ch 는 '0' 글자 폭 기준이라 한글 한 자가 약 2ch 다(서른 자 문장에 예순 자 넘는 자리가 필요했다). 제목을 감춘 만큼 자리가 생겨 상한을 풀었다.
// 1.574: **탭마다 다른 앱처럼 보이던 이유를 잡았다.** ① 글꼴 — button·input 은 글꼴을 상속하지 않는데 여러 버튼에 font-family 를 안 적어 둬서, 크롬 기본값인 **Arial 13.333px** 로 찍히고 있었다('훈련 계획 열기'·'미확인' 배지·'상태 확인 ›'·게임모델 세그). 화면에서 재던 '정체 불명의 13.3px'의 정체가 이것이다. 모든 페이지가 부르는 vendor/fonts.css 에 폼 컨트롤 상속 규칙을 한 번만 뒀다. ② **타이포 스케일이 두 벌이었다** — premium-ui.css 의 v286 정본(본문 13px·굵기 600)과 team-ui-v375.css 의 덮어쓰기(본문 14px·굵기 400)가 **같은 토큰 이름에 다른 값**이라, --fs-body 가 페이지마다 13px 이기도 14px 이기도 했다. 게다가 그 덮어쓰기를 실제로 받는 건 일정(process.html) 하나뿐 — scout.html 은 .ps-page-scout 를 달고도 그 CSS 를 안 부른다. 설계가 아니라 끝나지 않은 마이그레이션의 잔재라, 7개 탭 중 6개가 이미 쓰는 정본으로 합쳤다. ③ **일정 첫 진입 0.5~1초 거짓말** — 마크업에 '월간'이 켜진 채로 박혀 있고 셸이 iframe 로드 뒤 60ms 에 '주간'을 눌러 주는 구조라, 그 사이 표시는 월간·내용은 주간이었다(느린 기기일수록 길다). 주소로 mode=week 를 넘겨 첫 파싱에서 맞게 칠한다. ④ **지우는 버튼과 만드는 버튼을 갈랐다** — 일정의 '이번 주 초기화'는 아래 '초기화'와 **완전히 같은 동작**(둘 다 blankWeek())이면서 '지난주 복사' 바로 옆 같은 크기라 잘못 누르기 쉬웠다: 중복을 없애고, 남긴 초기화는 경고색으로. 게임모델의 '기본 템플릿으로 초기화'도 '＋ 국면 추가'와 같은 폭·같은 회색이던 것을 줄여서 뗐다. ⑤ **같은 말·거짓말·빈 화면 정리** — 팀>오늘의 'MD 옆 한 줄'은 경기 날짜를 적는 자리인데 경기가 없을 때 제목과 똑같은 '경기를 등록해 주세요'를 또 넣어, 앞의 '일정 미정'과 붙어 「일정 미정 경기를 등록해 주세요」로 읽혔다(비웠다). 경기 탭은 경기가 하나도 없을 때 '＋ 경기 추가'와 '첫 경기 추가'가 **같은 동작으로 동시에** 떠 있었다 — 빈 화면에선 안내가 붙은 쪽 하나만 남기고, 고를 것이 없는 '선택 경기' 드롭다운도 접는다. 선수 탭은 선수가 0명인데도 '모든 선수가 배치됐습니다'라고 말했다(0명일 땐 '아직 등록된 선수가 없습니다'). ⑥ **게임모델 점 색에 범례** — 색은 '이 국면이 네 갈래 중 어디에 속하는가'인데(그래서 세트피스=공격 초록, 경합=전환 갈색으로 겹친다) 그 규칙이 어디에도 없어 색이 모자라 재사용한 오류처럼 보였다. 목록 위에 한 줄 범례를 붙이고, 점에 마우스를 올리면 지금 속한 갈래를 말해 준다.
// 1.573: **빈 값이 팀으로 올라가는 것을 막는다(출고 검사).** 1.568 구조선은 **받는 쪽**만 지켰다 — 덮어쓰기 전에 백업을 남길 뿐, 빈 값이 **올라가는 것**은 아무도 막지 않았다. 그래서 8월 5일 같은 사고가 또 나면 원인 기기는 조용히 올리고, 다른 기기들이 저마다 '되돌리기'를 눌러야 하고, 그 사이 새로 로그인한 기기는 그냥 빈 것을 받는다. 이제 **올리기 직전에도 같은 잣대로 센다**(5개 이상 줄었거나, 4개 이상이던 것이 절반 이하). 크게 줄었으면 올리지 않고 **멈추고 묻는다** — 「스카우팅 후보가 34 → 0 으로 줄어 팀에 올리지 않았습니다」. 멈춘 동안 팀 값도 이 기기 값도 그대로다(지운 것이 되살아나지 않는다). 「팀에 올리기」를 누르면 그 값만 통과하고, 「팀 값 받기」를 누르면 이 기기를 팀 것으로 되돌린다. 칩을 놓쳐도 계정 팝업에 줄이 남고, 멈춘 자료는 '저장 대기'로 계속 표시된다. 스카우팅뿐 아니라 보관함 폴더·선수단·경기·일정·평가·권한·매치데스크·IDP 까지 같은 검사를 받는다. 로컬이 '빈 목록'인 키는 서버 값을 함께 받아 기억한 숫자가 아니라 **실제 팀 값과** 견준다.
// 1.572: 합친 탭의 이름과 첫 화면을 정리(사용자 지시) — 팀 탭 '설정' → **'게임모델'**, 누르면 **게임모델이 먼저** 열린다. 안에서 «게임모델 / 포지션·기준» 으로 오가고 어느 쪽이든 같은 탭이 켜진 채다. 카드 제목 '포지션별 요구 — 이상적인 플레이어' → **'포지션별 기준'**. data-team-key 는 'settings' 그대로 뒀다 — 다른 코드가 이 키로 탭을 찾는다.
// 1.571: 폰에서 '오늘 기록' 버튼 정리 — ① **하단 탭 바와 겹치던 문제**. 이 버튼은 폰에서 화면 아래에 고정되는데(매일 누르는 단 하나의 버튼), 선수 화면에는 하단 탭 바(목표·평가·일정·학습)도 같은 자리에 고정돼 있어 버튼이 탭 바에 잘렸다. 버튼을 탭 바 위로 올리고 본문 아래 여백도 둘을 합친 만큼 준다(틈 21px). ② 폭을 다 쓰는 버튼인데 **라벨이 왼쪽에 붙어 있던 것**을 가운데로(.btn 이 inline-flex 기본이라 가운데 정렬이 없었다). ③ 카드 글자 크기를 11/17/12px 하드코딩에서 앱 스케일(--fs-*)로 바꾸고, 긴 글은 말줄임.
// 1.570: ① **'코드로 합류'가 안 보이던 문제** — 1.563에서 팝업에 세로 스크롤을 넣으며 .ap-b 에 flex:0 0 auto 를 걸었는데, 그 버튼은 '＋ 팀 만들기' 와 **가로로 나란한 줄** 안에 있고 각자 width:100% 라 줄지 못하고 넘쳤다. 화면이 좁을수록 '코드로 합류' 가 가로로 밀려 두 번째 열처럼 잘려 나갔다. 가로 줄에서만 줄어들게 고치고, 팝업이 화면 밖으로 넘지 않도록 폭 상한·가로 넘침 차단을 뒀다. ② **선수 화면 '팀 일정' 탭이 사라진 것** — 1.568에서 팀 탭을 감싼 홈(.tn-seg)을 선수 모드에서 통째로 숨겨, 그 안의 '팀 일정' 되살리기 규칙이 무력해졌다(부모가 없어져서). 홈은 두고 배경만 지운다. ③ IDP 탭 위계·정렬 — 선수 하단 바의 활성 탭에 보라 표시선과 굵은 글자를, 코치 화면 탭에는 앱·팀 탭과 같은 흰 알약+밑줄을. 캡션이 있는 '학습' 탭 때문에 라벨 기준선이 어긋나던 것도 맞췄다.
// 1.569: **게임모델을 설정 탭 안으로 합쳤다**(사용자 확정). 둘 다 '포지션별 기준'을 담고 있어 같은 걸 두 군데서 적게 됐다. 팀 탭은 8→7개(오늘·경기·일정·선수·스카우팅·IDP·설정)로 줄고, 설정 안에서 «포지션·기준 / 게임모델» 두 갈래로 오간다. 어느 쪽에 있든 '설정' 탭이 켜진 채로 유지된다.
// 1.568: **덮어쓰기 전 무조건 백업(구조선)**. 2026-08-05 사고 — 한 기기에서 스카우팅 후보가 잘못 지워졌고, 그 빈 값이 서버로 올라가 다른 기기의 34명을 덮었다. '충돌'이 아니라 정상 동기화로 판정돼 **백업조차 남지 않았다.** 이제 받은 값으로 로컬을 덮을 때는 충돌 여부와 무관하게 이전 값을 남긴다(IDB 키 포함 — 날아간 cs_scout_targets_v1 이 바로 그쪽이었다). 항목이 5개 이상 또는 절반 이하로 줄면 '34 → 1 로 줄었어요 · 되돌리기' 를 띄우고, 계정 팝업에서도 언제든 되돌릴 수 있다. 되돌리면 이 기기 것이 최신으로 잡혀 다음 동기화에 팀으로 올라간다. 팀 탭도 위 앱 탭과 같은 결로 통일.
// 1.567: 포지션 기준을 **한 곳으로 합쳤다** — 게임모델 '포지션별 요구'와 스카우팅 '포지션별 기준'이 서로 다른 자리(ideal vs spec)에 저장돼 한쪽에 적어도 다른 쪽엔 안 보였다. 이제 둘 다 같은 데이터(po.ideal · 전술·기술·멘탈·신체)를 읽고 쓴다. 앞선 판에서 적어 둔 것(note·spec)은 새 자리로 옮긴다 — 기술 공격/수비로 나눠 적은 것은 '기술' 한 칸에 두 줄로 합친다. 적은 내용은 하나도 버리지 않는다.
// 1.566: ① 게임모델 '포지션별 요구' 카드 — **입력칸이 아예 안 보이던 버그**를 잡았다(.idcard textarea 는 기본이 display:none 이고 .idcard.open 에서만 보이는데 그 클래스가 없었다). 접지 않고 늘 펼쳐 두고, 라벨을 **전술·기술·멘탈·신체**로 줄이고, 네 칸을 같은 폭으로 고정. ② 후보 목록에서 **상태를 맨 앞 열**로(이름 옆에 붙어 있어 이름 길이에 따라 흔들렸다) + **영입완료** 단계 추가. 여덟 열 머리글·데이터 정렬 0px. ③ 스카우팅 칩 등번호가 두 자리일 때 세로로 접히던 것(칸 16→24px). ④ 스카우팅 운동장 세로 520→660px(카드가 아래로 넘쳤다). ⑤ 조 칩이 사라지던 것 — 아무에게도 조를 안 줬으면 통째로 숨어 'A팀·B팀 나누기'로 가는 길이 없었다. 선수가 있으면 A~D 를 늘 띄운다.
// 1.565: ① 포지션별 기준에서 **요구사항(글)과 점수를 한 자리에서** — 고른 포지션의 속성별 목표(1~5)를 글 상자 아래에 붙였다. 위 표는 포지션끼리 비교하는 눈, 여기는 한 포지션을 정하는 자리. 값은 같은 곳(po.targets)에 쓴다. ② 스카우팅 칩의 상태 배지가 '영입…'으로 잘리던 것 — 폭 상한을 풀고 글자를 줄여 다 보이게. ③ 후보 목록 **머리글과 칸 내용을 같은 지점에서** 시작하게(입력칸 여백만큼 라벨을 밀어 맞춤) — 실측 차이 0px. ④ 메모는 아래로 쌓지 않고 **옆으로** 늘어난다(자리가 모자라면 접힘).
// 1.564: ① 스카우팅 칩에 **진행 상태(추천·보류·관찰중·영입대상·확정)** 를 띄운다 — 목록까지 내려가지 않아도 보드에서 보이고, 눌러서 바로 바꾼다. ② 칩을 **다섯 칸 고정**(출신·번호·이름·상태·평가) — flex 라 이름 길이에 따라 칸이 밀려 줄마다 어긋났다. 카드 폭 172→212px. ③ 선수 페이지 **운동장을 카드 끝까지**(넓은 화면에서 1005→1047px) — 카드 안쪽 여백만큼 양옆으로 빼냈다. 좁은 화면은 여백을 그대로 둔다.
// 1.563: 계정 팝업이 아이패드에서 **아래쪽이 잘리던 문제** — 항목이 늘어(팀 이름 바꾸기·충돌 확인·권한 관리·팀원 보기…) 팝업이 화면보다 길어졌는데 높이 상한이 없어 '팀 자료 새로고침'과 '로그아웃'이 화면 밖으로 나갔다. 화면 높이에 맞춰 상한을 두고 넘치면 팝업 안에서 스크롤한다(100dvh 기준, 지원 안 되면 100vh).
// 1.562: ① 포지션 기준을 **네 갈래로 적는다**(JFA 모델) — 전술 · 기술(공격/수비) · 정신 · 신체. 포지션을 골라 그 자리만 편집한다(16개 × 5칸을 한 번에 펼치면 못 읽는다). 한 줄에 하나씩이 곧 항목. 1.561의 한 줄 메모는 전술 칸으로 옮겨 살린다. ② 후보 목록을 **표준 순서(GK→…→CF)** 로 — 목록에 담긴 차례를 쓰다 보니 포지션을 추가·이동한 팀에서 CF가 위로 오기도 했다. ③ **정렬 고르기(포지션순/평가순)** 추가 — 평가순일 때는 등급으로 묶는다(포지션으로 묶으면 순서와 머리글이 어긋난다).
// 1.561: 포지션별 기준에 **말로 쓰는 기준**을 더했다 — 표 아래에 지금 보고 있는 포지션마다 칸이 하나씩 생긴다(예: '첫 패스로 상대 1선을 넘긴다 · 뒷공간 커버가 먼저'). 숫자(목표 레벨)만으로는 '이 자리에서 뭘 해야 하는지'가 적히지 않아서, 코치가 자기 말로 남길 자리를 둔 것. 포지션 데이터(po.note)에 붙어 저장되고 다시 그려도 남는다.
// 1.560: 스카우팅 — ① 후보 목록 열을 **평가레벨 · 이름 · 출신 · 등번호 · 프로필 · 기준대비 · 메모** 로. 포지션 열은 뺐다(이미 포지션별로 묶여 있어 같은 말을 두 번 했다). ② **메모를 여러 개** 붙인다 — 무엇을 적을지는 팀이 정한다(앱이 '장점/보완점' 같은 이름을 박지 않는다). 옛 한 줄 메모는 첫 줄로 살린다. ③ 보드 칩 순서를 **출신 · 등번호 · 이름 · 평가** 로, 출신과 등번호를 붙였다. ④ 포메이션 알약에서 **등번호를 바로 입력**. ⑤ 후보 상태를 **추천 / 보류 / 관찰중 / 영입대상 / 확정** 로 — 없어진 '관찰 예정'은 '관찰중'으로 읽는다.
// 1.559: 후보 빠른 보기 카드 — ① **점을 눌러 그 자리에서 평가**한다(같은 칸을 다시 누르면 지운다). 예전엔 '프로필·평가 편집'으로 나가야 해서 한 칸 고치려고 화면을 두 번 옮겨야 했다. 고치면 보드·후보 목록도 함께 갱신. ② 앱 결에 맞춤 — 10·11·19px 을 직접 박아 두던 것을 앱의 글자 토큰(--fs-*·--fw-*)으로 바꾸고, 라벨 열 84px 고정 · 점 5칸 균등 · 점수 우측 정렬로 행과 열을 맞췄다. 점은 손가락으로 누를 크기(22px)로.
// 1.558: ① 포메이션 알약을 **네 열(번호·이름·조·상태)로 고정** — 번호 없는 선수는 번호 칸을 아예 안 그려 이름이 왼쪽으로 밀렸다. ② 스카우트 후보 목록을 **포지션별로 묶고 메모 열 추가**. ③ 후보 칩에서 **이름·소속팀·등번호를 그 자리에서 수정**(끌기와 안 부딪히게 처리). ④ 조 칩을 **포메이션·유니폼과 같은 행**으로. ⑤ 팀원 목록과 권한 관리를 **역할별로 묶는다** — 관리자/임원 → 코칭스태프 → 선수. 권한 관리는 같은 역할 안에서 '선수 연결 안 된 사람'이 위로.
// 1.557: ① 스카우팅 보드 후보 칩을 **한 줄**로 — 이름 · 소속팀 · 등번호 · 평가. 카드 폭을 118→172px 로 넓혔다(사용자: 가로로 길어도 됨). 소속팀이 길면 이름을 밀지 않고 스스로 줄어든다. ② 후보 상태에 **'확정'** 추가 — 관찰 예정 → 관찰 중 → 보고됨 → 영입 추진 → **확정** → 보류. ③ 평가 설명 문구가 A~C 로 굳어 있던 것을 실제 단계(A~D)에서 만들도록 고쳤다.
// 1.556: 스카우팅 페이지를 선수 페이지 쪽으로 맞춘다 — ① 조를 **A~D 네 개**로(선수 페이지·포메이션 보드·명단 모두). ② 후보 평가도 **A~D 네 단계**. ③ 스카우팅 보드에 **조 칩(전체/A~D)** — 우리 팀 선수가 보이는 '우리팀·전체'일 때만 뜨고, 우리 선수는 선수 페이지와 같은 조 필터를 탄다(후보는 우리 조와 무관하므로 안 걸린다). ④ 보드 칩 생김새를 선수 페이지 알약(.tb-pill)과 같은 결로 — 후보는 남의 팀이라 우리 팀 색 대신 점선 테두리로 구분.
// 1.555: ① 주간 보드 보관함 칩을 누르면 **바로 그 자료가 열린다**(작은 창을 한 번 더 거치지 않게). 바꾸기·빼기는 칩의 ⋯ 로. ② 보관함 칩을 훈련 칩과 **구분하되 튀지 않게** — 아주 옅은 배경 + 점선 테두리(주제색은 왼쪽 띠가 이미 쓰므로 여기서 또 쓰지 않는다). ③ 스카우팅 운동장 높이를 **선수 탭 포메이션과 같은 520px** 로 — 1.551에서 화면 높이를 다 쓰게 했더니 706px 이 돼 두 화면이 따로 놀았다(가로는 그대로 꽉 채운다).
// 1.554: 스카우팅 보드 후보 입력·평가 — 자리에 넣을 때 **현재 팀·등번호·이름**을 함께 적고, 칩에서 **A·B·C 평가**를 눌러 매긴다(A → B → C → 없음). 칩은 두 줄(위: 등번호·이름·평가 / 아래: 현재 팀) — 한 줄에 다 넣었더니 소속팀이 자리를 안 내줘 이름이 '김성민'→'김'처럼 잘렸다. 소속팀은 후보 표가 이미 쓰던 club 칸을 그대로 쓴다.
// 1.553: ① 팀>오늘 주간 칸에서 **오늘이 항상 첫 칸** — 경기가 가까우면 이미 지나간 날부터 그려서(start 가 음수) 오늘이 가운데로 밀려 있었다. 지난 날은 ‹ 로 볼 수 있다. ② 주간 보드 보관함 칩에 **제목만** — 썸네일·분까지 넣었더니 칸이 부풀고 썸네일 안의 선수 이름까지 글자로 딸려 나왔다(그림·시간은 칩을 눌러 미리보기에서 본다). ③ **스카우팅 탭에 들어가면 스카우팅 화면이 먼저** 뜬다(전체 → 스카우팅).
// 1.552: **선수 명단에서도 조(A·B)를 바로 바꾼다** — 상태(정상·부상·재활) 버튼 옆에 조 버튼을 붙였다. 포메이션 보드와 같은 순환(A팀 → B팀 → 없음)이고 어느 쪽에서 바꿔도 양쪽이 함께 바뀐다. 명단 행은 5열 그리드라 버튼이 하나 늘자 다음 줄로 밀려 행이 48→80px 로 커졌다 — 열을 하나 늘려 한 줄을 지킨다.
// 1.551: 스카우팅 보드 **운동장을 가로로 꽉 채운다** — 폭이 '높이×1.4375'에 묶여 있어 넓은 화면·낮은 창에서 좌우가 남았다. 이제 가로는 화면 끝까지, 세로만 화면 높이에 맞춘다. 비율 유지를 끄므로 중앙원은 살짝 타원이 되지만, 이 화면은 포지션 카드를 늘어놓는 판이라 폭이 곧 쓸모다(카드가 골대·박스 선에 겹치던 것도 함께 풀린다).
// 1.550: 포메이션 알약에서 **조(A·B)를 바로 바꾼다** — 부상 표시와 같은 방식으로, 눌러서 A팀 → B팀 → 없음 순환. 1.549의 읽기 전용 조 태그를 버튼으로 바꿨다. A팀·B팀은 아직 안 쓰는 팀에서도 항상 고를 수 있고(있는 조에서만 뽑으면 B팀을 만들 길이 없다), 팀이 따로 쓰는 조는 그 뒤에 이어 붙는다. 거르는 중에 다른 조로 옮기면 왜 목록에서 사라졌는지 알려준다. 선수단 편집 권한이 없으면 막는다.
// 1.549: ① 주간 보드에 **'보관함' 행** — 요일마다 [＋ 보관함]으로 보관함에 만들어 둔 자료를 그대로 가져다 놓는다(이름·주제색·분·그림까지). 폴더별로 묶어 보여주고 이름·폴더·태그로 검색. 훈련 행(직접 적는 블록)은 그대로. 인쇄 주간표에도 한 줄 추가. ② 팀>오늘 **훈련 가능·GK·필드를 큰 숫자 세 칸**으로 — 회색 한 줄에 묻혀 있던 걸 카드의 주인공으로. ③ 선수 보드 세그를 **스카우팅 / 우리팀 / 전체** 로(이름·순서). ④ 포메이션 알약에 **조 태그(A팀·B팀)** — '전체'로 볼 때만 붙는다(그룹 필터는 예전부터 보드에 걸려 있었다).
// 1.548: ① 선수를 지우면 **포메이션의 빈 자리도 사라진다** — 예전 배치의 좌표만 남아 'LWB 0' 같은 빈 칸이 계속 떠 있었다(노션 QA). 좌표는 보관하므로 그 자리에 선수를 다시 넣으면 놓았던 위치로 돌아온다. ② 알림창이 **내용이 길면 스크롤된다** — 충돌 목록처럼 줄이 많으면 창이 화면 밖으로 자라 아무것도 누를 수 없었다(제목·버튼 고정, 본문만 스크롤). ③ 매치데스크 **명단 붙여넣기가 라인업 사이트 형식도 읽는다** — 번호·이름·포지션이 구분자 없이 붙어 오는 '1Ju-Hyeon Lee골키퍼' 형태를 번호/이름/GK·DF·MF·FW 로 나눈다.
// 1.547: 권한 관리에서 **'노트' 항목 제거**(7→6). 노트는 sync.js 의 PERSONAL 키라 팀에 올라가지 않는다 — 각자 개인 공간에만 백업되고 다른 팀원은 볼 수도 받을 수도 없다. 그래서 이 체크는 '남이 자기 개인 수첩에 글을 쓸 수 있는가'를 정하는 셈이라 팀 권한에 맞지 않았다. note.html 의 잠금(gate)도 함께 제거 — 남겨 두면 권한을 받을 길이 없어 노트가 영구히 보기 전용이 된다.
// 1.546: ① 보관함 목록 보기에서 **미리보기 칸 제거** — 줄마다 크기가 들쭉날쭉해 이름을 훑기 어려웠다. 내용을 볼 자리는 오른쪽 큰 미리보기가 맡는다(격자 보기는 그대로). ② 자료 메뉴 'PDF 저장' → **'PDF 내보내기'**. ③ 매치데스크 경기 일정: 늘 펼쳐져 있던 입력 여섯 칸을 감추고 **달력만** 보이게, **날짜를 누르면 그 날짜로 바로 경기 추가**(도구줄 ＋ 경기 추가는 오늘 날짜). ④ 상단 경기 드롭다운을 **텍스트 검색**으로 — 팀·대회·장소·날짜로 찾는다(비우고 누르면 전체 목록).
// 1.545: ① 보관함 목록에서 **가짜 미리보기 제거** — 미리보기가 없는 자료는 초록 사각형에 '훈련'이라고만 적힌 칸을 채웠는데, 그 글자는 옆 분류 배지가 이미 하는 말이라 자리만 먹었다. 이제 진짜 미리보기가 있을 때만 칸을 만든다(오른쪽 큰 미리보기는 그대로). ② **동기화 충돌 경고 칩 제거** — 여러 기기를 오가면 계속 쌓여 매번 같은 말로 화면을 덮었다. 밀려난 변경은 그대로 보관하고, 계정 팝업의 조용한 줄에서 확인·되돌리기 할 수 있다.
// 1.544: 팀>선수 명단에 **IDP 미연결 거르기** — 상단에 '미연결 N'이 뜨고, 누르면 계정이 아직 안 이어진 선수만 남는다(누구를 챙겨야 하는지 손으로 훑지 않아도 된다). 상단 숫자는 선수단 전체 기준을 유지하고, 포메이션 보드는 거르지 않는다. 혼자 쓰는 개인 공간과 전원 연결된 팀에서는 아예 뜨지 않는다.
// 1.543: 선수 칩을 **보드로 끌어내릴 때 티가 나게** — 지금까지는 손가락이 운동장 안에 들어가야 토큰이 처음 나타나서, 그 전까지는 칩을 잡은 건지조차 알 수 없었다. ① 누르는 즉시 칩이 눌리고 ② 손가락을 따라다니는 칩이 뜨고 ③ 운동장이 '여기 놓으세요'로 바뀌고(안에 들어오면 더 진하게) ④ 놓으면 토큰이 톡 튀며 자리잡는다. 운동장 밖에 놓으면 왜 안 됐는지 알려준다.
// 1.542: **아이패드 터치 묶음** — ① 훈련 탭·작전판 페이지·애니메이션 장면 순서를 손가락으로 바꾼다(0.2초 꾹 누른 뒤 끌기). 지금까지 HTML5 드래그앤드롭만 있어서 iOS 사파리에서는 세 곳 모두 아예 안 끌렸다. ×·복제 버튼은 잡히지 않고, 꾹 누르기 전에 움직이면 스트립 스크롤로 본다. ② 작전판을 꾹 눌렀을 때 iOS 텍스트 창(복사·찾아보기)이 뜨던 문제 — 억제가 SVG에만 걸려 있어 도구 막대·명단·화이트보드 등 나머지가 새고 있었다. 영역 전체에서 끄고 입력칸만 예외로.
// 1.541: **작전판 첫 탭이 먹히던 회귀 수정(1.530에서 유입)** — 색 팔레트를 접지 않게 바꾸면서 'open' 클래스가 한 번 붙으면 안 떨어졌고, 보드의 옛 가드가 그걸 보고 **탭을 통째로 삼켰다**(아무 반응 없음·토큰이 안 잡힘). 가드와 클래스를 함께 제거.
// 1.540: 스카우팅 **후보 데이터 분리** — 후보(type:target)를 cs_scout_targets_v1 로 옮겨 서버에서 임원 전용으로 잠근다(코칭스태프도 못 받는다). 선수 명단은 그대로. 앱 첫 실행 때 1회 자동 이전, 볼 권한 없는 역할은 후보 키를 쓰지 않는다(빈 값으로 덮어쓰기 방지). 서버 규칙 적용 완료.
// 1.539: **스카우팅은 임원 전용** — 팀 내비의 스카우팅 탭을 임원(owner 포함)에게만 표시. 코칭스태프·선수에게는 숨기고, 보고 있던 중이면 '오늘'로 돌려보낸다. (편집 권한은 원래도 임원만이었다.)
// 1.538: **팀 이름 바꾸기** — 계정 팝업에 추가(팀을 만든 사람만 보임). 자료·일정·권한은 그대로, 팀원 모두에게 새 이름으로 보인다. 권한이 없으면 조용히 무시되지 않고 이유를 말한다.
// 1.537: 선택 메뉴가 **선택한 토큰을 덮지 않게** 비켜난다 — 좁은 판(훈련 세션 편집기 등)에서 좌우 자리가 없으면 메뉴가 토큰 위로 끌려와, 메뉴가 포인터를 삼켜 토큰을 끌 수 없었다. 겹치면 토큰 위/아래로 옮긴다.
// 1.536: 저장 공간 경고가 **무엇이 자리를 쓰는지 이름으로** 알려준다(상위 3개 + 줄이는 방법). [지금 정리]가 사진 이전(PSImg.migrate)까지 수행하고 옮긴 장수를 보고한다.
// 1.534: 권한 관리에서 **코치가 새 팀원을 명단과 연결**하기 쉽게 — 상단에 '합류 N · 연결됨 N · 연결 안 됨 N' 요약, 미연결을 맨 위로, [연결 안 된 사람만] 거르기, 이미 다른 계정이 가져간 선수는 드롭다운에서 비활성(중복 연결 방지).
// 1.533: 팀원 이름 — 합류 때 입력한 이름이 기기에만 남아 권한 관리에 안 뜨던 문제 수정(서버 ps_members.name 에 저장, supabase-설치/supabase-member-name.sql 적용 필요). 권한 관리에 이름+이메일 함께 표시(이름 없으면 그렇게 표시). 팀 공간인데 이름이 비어 있으면 채울 때까지 묻는다. 보관함 폴더 줄에 ⋯ 버튼(아이패드에서 '팀 공유 끄기'를 찾을 수 없던 문제).
// 1.532: 보관함 공유를 **폴더 단위**로 재설계 — 자료마다 누르던 '팀에 공유' 폐지, 폴더 메뉴의 「☁ 팀과 공유」 스위치가 그 폴더(하위 포함) 전체의 공개를 정한다. 끄면 팀에서 사라지고 팀원 기기 사본도 다음 동기화에 정리. 남의 공유본은 원본 주인만 수정. 기존 공유본은 「팀 공유」 폴더로 1회 자동 이전. 서버 변경 없음.
// 1.531: 워크스페이스 전환 누수 수정 — 팀을 바꿔도 IndexedDB에 남아 이전 팀 것이 보이던 키 4개(경기·작전판 스태시·경기 스냅샷·편집 중 작업)를 전환 시 함께 비운다. 경기(cs_match_v1)는 보드가 IndexedDB에 쓰는데 동기화는 localStorage를 읽던 불일치도 해소. 선수 '팀 일정'이 안 열리던 오타 수정(hubKey schedule→training).
// 1.530: 작전판 색상은 **접지 않는다** — 선택 메뉴에 색 견본을 늘 펼쳐 두고 바로 고른다(여닫기·화살표 제거). 여러 색을 연달아 눌러도, 바깥을 눌러도 그대로 있다. 팀>오늘 '훈련 가능'에 GK·필드 인원 분리 표시(예: 13/46 · GK 2 · 필드 11).
// 1.528: 초대 코드에 **카톡용 초대 문구**를 함께 — 코드 화면에서 문구를 미리 보고 [초대 메시지 복사](앱 주소·합류 순서·코드 포함) / [코드만 복사] / [공유하기](폰·아이패드) 중에 고른다. 역할 조사 처리('선수로'·'임원으로').
// 1.527: 도구 막대의 팀 색 칩을 운동장으로 **끌어다 놓으면** 그 자리에 그 팀 선수가 생긴다(끄는 동안 색 미리보기, 운동장 밖에 놓으면 취소, 탭=팀 선택·길게=색 팝업은 그대로). 선수 화면 '팀 일정' 내비가 통째로 비어 있던 오타 수정(data-team-key: schedule→training).
// 1.526: 보관함 미리보기 복구 — 서버에서 받은 자료는 썸네일이 떼여 와 '미리보기 없음'이 떴다. 배치(snap)로 다시 그려 보여주고 항목에 저장한다. 동기화 충돌 알림: '전부 이 기기 것으로 유지'로 끌 수 있게(지금까지는 끄는 길이 없었다), 칩은 개수 먼저·이름 3개까지, 서버본이 내 것과 같으면 헛알림 안 냄, 날것 키 이름에 한글 라벨.
// 1.525: 팀>오늘에 '선수 체크인' 카드 — 선수가 IDP 오늘 기록에 남긴 강도(1~5)·한 줄을 코치 화면에 모아 보여준다(응답 수·평균·힘들다고 한 선수·남긴 말). 선수 계정에는 안 보인다. ※ 개인 데이터 서버 차단은 supabase-설치/supabase-kv-owner.sql 적용 필요.
// 1.524: 일정 달력에 상대팀 이름 표시(경기 칸이 'vs 성남FC'), 경기 선택 시 입력칸이 상대팀을 묻는다, 월간 팝업에서 줄마다 × 로 바로 삭제(경기·훈련·미팅·웜업·주제·강도) + '되돌리기' 7초. 선수·읽기전용 역할에는 × 를 숨긴다.
// 1.523: 보관함 백업 근본 수정 — 팀 공간에서 저장한 내 자료도 서버에 '비공개'로 백업(ps_library.private/owner_id + RLS). '팀에 공유'를 누르면 공개본으로 전환. 보관함에 '내 자료' 탭. ※ supabase-설치/supabase-library-private.sql 적용 필요.
// 1.522: 보관함 '이 기기에만 있음' 경고(팀 공간 자료는 공유 전까지 서버 백업 없음), 팀원 이름·이메일 함께 표시, 스카우팅 '비교' 탭 제거, IDP 평가 이력에 분류·항목 값 기록+지난 평가 대비 변화·진행률.
// 1.521: 기본 평가표를 실제 운영표 44개(전술6·기술15·체력8·심리7·태도8)로 교체 — 새 팀이 받는 기본값. 기존 팀 표는 그대로.
// 1.520: 평가표를 선수 말로(15개 항목, 팀이 고친 항목은 유지·ID 그대로라 기록 보존), 강도 설명 한 단어로 축약.
// 1.519: IDP 강도를 1~5 단계로 + 뜻풀이(아주 가벼움~아주 힘듦), 예전 1~10 기록은 자리를 맞춰 표시.
// 1.518: IDP 강도(RPE)를 슬라이더에서 1~10 버튼으로 — 폰에서 정확히 누르게, 폰은 한 줄씩 배치.
// 1.517: IDP 폰 최적화 — '오늘 기록' 하단 고정, 탭 터치 44px+, 열 때 현재 탭 보이게, 폰에서 PDF 버튼 숨김.
// 1.516: 스카우팅 비교 배치 깨짐 수정(1.515 회귀), 일정 편집 잠금 전수 적용·권한 되돌아감 감지, 노트 옛 사본 부팅 시 정리, 팀원 이름·이메일 분리(ps_members_of_v2), 매치데스크 리뷰 보고서 PDF.
// 1.515: 스카우팅 비교 — 작전판을 맨 위로, 자리마다 '＋'로 그 자리에 바로 선수·후보 추가, 능력치 점을 눌러 표에서 바로 편집.
// 1.514: 일정 편집 잠금이 '넣었다가 사라지는' 문제 수정 — 잠겼으면 입력 지점에서 막고 이유를 알림, 동기화가 권한으로 못 올린 것도 알림.
// 1.513: 팀원 관리 — 이름·이메일·합류일 함께 표시, 역할 변경, 내보내기(관리자). '다른 기기의 변경 반영됨' 알림 칩 제거.
// 1.512: 팀>선수 — 작전판 아래에 선수 명단·상태를 함께(모드 전환 제거), 명단은 1열 유지, 재활을 부상과 같은 경고색으로 통일.
// 1.511: 포메이션 보드에서 선수 상태를 바로 변경(명단과 같은 순환·제안 규칙), 재활을 부상과 같은 표시로 통일.
// 1.510: 매치데스크 캘린더 — 월 달력 그리드(분석 상태 색)와 목록 전환, 팀·대회·장소 찾기와 상태 거르기(찾으면 그 달로 이동).
// 1.509: 팀>오늘 인원이 선수 화면과 다르던 문제 수정 — 이름 없는 빈 슬롯을 사람으로 세지 않는다(김포FC U15 제보).
// 1.508: 매치데스크를 분석 아카이브로 — 경기별 진행 상태(미착수·작성 중·분석함·발행)와 근거 수, 상단 누적 요약, 발행 이력 기록.
// 1.507: 매치데스크 레이아웃을 앱 결에 통일 — 화면 전환을 가로 탭으로(좌측 세로 내비 제거), 빈 예시 바 삭제, 경기 0개일 때 화면이 어긋나던 문제 수정.
// 1.506: 매치데스크를 기술위원 관찰 도구로 — 방송(모드·대본·재생목록·TV 해설 역할) 완전 제거, 관찰 어휘를 게임모델 국면과 통일.
// 1.505: 매치데스크 '양 팀 비교' 화면 — 기술위원이 한 경기를 양쪽 관점에서 보도록 대형·기록·득점자·전술을 같은 줄에 나란히.
// 1.504: 저장공간 — 노트·양식을 IndexedDB로 이사(localStorage 5MB 한도 탈출, 저장 확인 후 옛 사본 정리), 동기화 충돌 사본 14일 만료 청소.
// 1.503: 매치데스크 — 기본 예시 경기 제거(내 경기만), 만들 때 날짜·대회·장소·시간 입력, 개인 채널(팀 공간에서도 개인 공간에 백업), 부팅 중 만든 경기 보호.
// 1.502: 매치데스크 — 첫 화면을 경기 목록으로(만들기→분석→목록에서 커뮤니티 발행), 장면 편집 중 토큰 이동이 저장되지 않던 문제 수정, 개인 데이터가 워크스페이스 전환 때 지워지던 경로 차단.
// 1.501: 매치데스크 — 저장 수정(IndexedDB 키를 동기화 어댑터에 등록, 개인 전용 PERSONAL), 경기 일정 달력화(다가오는 경기·월별·날짜 수정), 목록에서 바로 커뮤니티 발행. 일정 시점 복구(운영진, 서버 90일 기록).
// 1.497: 게임모델 팀 내비 1급 승격 + '포지션별 요구' 섹션 이관(스카우팅 ideal 탭 제거, 데이터 공유) + IDP 예시문 14곳 선수 눈높이로.
// 1.496: '이상적인 플레이어' 탭 신설(포지션별 전술·기술·정신·신체 문장 정의, 팀 자율 작성, Japan's Way 형식) + 기준 매트릭스 열 축소(쓰는 포지션만·전체 토글).
// 1.495: 후보 화면에 보드 통합 — 위 보드(전체/우리/후보 3모드 세그)+아래 후보 명단, 보드 탭 제거(후보로 흡수).
// 1.494: 보드 '후보만' 토글 — 우리 선수 숨기고 스카우트 후보만 포메이션으로, 후보 탭 '보드로 보기' 원탭 연결.
