// 1.492: 스카우터 퀵 프로필 — 스카우팅 보드에서 선수 탭=보고용 한 장(적합도·카테고리 평균·핵심 속성 기준 대비·메모), 편집은 기존 프로필 모달로.
// 1.491: 경기 리뷰 간소화 — 카드 6→4(FIFA 접이 진입로 제거·공유 체크 팀 리뷰 흡수), 번호 제거, 1열 문서형(860px), 게임플랜 있는 줄만 실행 확인.
// 1.490: 보관함 '팀 공유' 드롭 존+미리보기 '팀에 공유' 버튼, 매치데스크 우측 버튼 auto-fit, 다크 QA(명단 입력·제목·세그·구분선, 오늘 인원 그룹 헤더 틴트).
// 1.489: 디자인 통일 패스 — 무게 600/800 복귀(135곳)·반픽셀 스냅(125)·radius 9→10(90)·컬러 이모지 제거(13). UI-가이드 radius 10 개정.
// 1.488: 경기 삭제 묘비(cs_match_del_v1, 동기화 키) — 수동 경기 포함 삭제가 다른 기기 옛 목록으로 부활하지 않게.
// 1.487: 일정에서 지워진 경기 자동 정리(사용자 지시) — 기록 있으면 휴지통(cs_match_trash_v1) 보관, 일정 미동기화 시 스킵, 수동 경기 유지.
// 1.486: 다중 기기 정합 — 경기(cs_team_matches_v1)·선수단(scout_tool_v1) storage 반영(옛 메모리가 동기화 데이터를 덮던 근본 원인), 입력 중 보호, 경기 칩 '일정에 없음' 배지.
// 1.485: 매치위크 스트립 3상태 구분(OFF 회백 점선·훈련 테마색 점·경기 초록) + 강도(RPE) 1~10 원탭 버튼(슬라이더 제거).
// 1.484: 경기 중복 병합(같은 날짜·상대 — 내용 승자, 둘 다 내용이면 보존, 묘비로 부활 방지) + 일정 주간 보드 '경기 준비 →' 바로가기.
// 1.483: 선수단 편집 잠금 — 기본 운영진만(명단·포메이션·평가 보기 전용, 상태 제안·IDP 열람은 유지), cs_perms_v1.rosterEdit 토글.
// 1.482: 팀 일정 편집 잠금 — 기본 운영진만(스태프 보기 전용+안내 바), cs_perms_v1.schedEdit='staff' 토글로 전원 개방, 일정에 '마지막 수정 ○○ · n분 전'.
// 1.481: 데이터 안전 — 세션 만료 배너(백업 멈춤 상태 보고, 닫기 가능) + 보관함 불변식 가드(자료>0인데 표시 0이면 전체 자료로 자동 복귀).
// 1.480: 보관함 복구 — 폴더 목록 자가 치유(항목 folder 경로에서 재구성, 메타 유실 시 '27개인데 안 보임' 해결) + 진입 기본 '전체 자료'.
// 1.479: 명단 1열 리스트(760px 중앙)+행 구분선 — 3열은 시선 끊김(사용자 확정 '1열로').
// 1.478: 명단 행 위계·정렬 — 이름 주인공·입력 테두리 호버/활성만, '정상'·미연결 IDP는 유령(색은 부상·재활·연결에만), 등번호 고정폭·배지 우측 열 정렬.
// 1.477: 명단·상태 한 페이지 — '선수 명단·상태' 탭 하나로(전 행 상태 배지 상시), 상태 자세히는 접이, 행마다 IDP 연결 배지.
