// 1.761: 작전판 제작 도구 아이콘 통일 + 보기·펜 색 팝업 portal 수리 + 더보기를 사이드바 환경 설정 아래로 이동.
const CACHE = 'process-2.735';   // 2.735 경기 리뷰 — 결과 상세 접기 · 팀/국면 통합 · 선수별 미작성 큐와 빠른 이동   // 2.734 경기 준비 명단 — 미배정 선수를 선수단 조별 한 행으로 · iPad 명단 스크롤/3방향 놓기   // 2.733 경기 저장 신뢰 — 팀 전환 flush 장벽 · 키별 준비 판정 · exact 거울 · 빈/누락 기록 보존 복구   // 2.732 보드 설정을 도크로(사이드바 버튼 제거) · 설정의 화면 스위치 걷음(개발 문 ?layout=mobile)   // 2.731 선수 행 서버 판정(2단계) — 판본(cupd) 붙여 올리고 어긋나면 서버 값 적용 + «팀 것이 더 새로워요»   // 2.730 선수단을 항목으로(1단계) — sq: 행 읽기·워크스페이스별 색인·행 도착 신호·tmMigrate 정지   // 2.727 보관함 사진을 ps_blob 으로 분리(전송만) · sync_failed 에 name·msg 남김   // 2.726 짧은 공유 링크 뷰어 — PS_SYNC 정의 뒤(DOMContentLoaded)에 읽기   // 2.725 짧은 공유 링크 /s/<id>(누르면 바로 복사) · 전환 직후 일정→경기 재생성 금지(서울시 준비 글 덮임)   // 2.724 보관함에서 연 카드의 훈련 인원 복원(복제 카드 0명)   // 2.723 편집기 드래그 중 썸네일·초안 저장 미룸(토큰 DOM 재구성이 드래그를 끊던 것)   // 2.722 훈련 세션 만들기에도 제목 칸   // 2.721 보드 화면 워터마크 PRO+CESS   // 2.720 내보내기 워터마크 «PROCESS» — 가로 우측하단 · 릴스 좌측상단   // 2.719 작전판: 선 끝점 토큰에 묶기 · 장면 사이 그림 서서히 · 릴스 여백 잔디   // 2.718 전환 가드: 보관함 «아직 시도 전» 이면 한 회차 더 확인   // 2.717 관리자 오류 탭 캐시 무효화 — admin.html 새 탭이 일반 새로고침에서도 남게 함   // 2.715 선수단·스카우트 중복 — 거울 재이전 금지 · 거부 뒤 팀 것으로 맞춤 · 비움은 선수 수로   // 2.620 하루 여러 경기 → 팀 › 경기 목록(리뷰) + 일정표 전 화면·인쇄에 추가 경기 표시   // 2.619 IDP 한 줄 왕복 4·5단계 — 6주 점검(답 셋) · 분기 면담(KNVB 5단계 → 선수 기록 흐름 카드 · 다음 분기 시작)
